window.DATA = {"meta": {"programmes": [{"id": "ict", "label": "ICT (Islamabad)", "short": "ICT"}, {"id": "punjab", "label": "Punjab", "short": "Punjab"}, {"id": "tanzania", "label": "Tanzania", "short": "Tanzania"}], "stats": [{"value": "29 hours", "label": "of debrief audio listened to"}, {"value": "421", "label": "two-way debriefs scored against the evidence"}, {"value": "98", "label": "coaches in 3 programmes"}, {"value": "907", "label": "debriefs followed into the next lesson"}, {"value": "160", "label": "lesson pairs read blind"}]}, "summary": {"going_well": [{"title": "Coaches are kind, and safe to talk to", "text": "92% of ICT debriefs, 92% in Punjab and 98% in Tanzania were warm and respectful enough for a teacher to admit what went wrong. Not one was scored as blaming or humiliating."}, {"title": "Feedback is tied to what really happened", "text": "In ICT, 76% of debriefs pointed to real moments from the lesson, a median of 5 per debrief, and 89% gave praise for something specific."}, {"title": "Most debriefs pick one thing to work on", "text": "69% of ICT, 88% of Punjab and 71% of Tanzania debriefs settled on one area, not a long list. That is what the evidence asks for."}], "improve": [{"title": "Practise the step before leaving the room", "text": "Trying the new move out loud, with the coach, is the part of a debrief with the strongest evidence behind it. It happened properly in 3% of ICT debriefs, 0% in Punjab and 0% in Tanzania."}, {"title": "Let the teacher talk first, and more", "text": "The coach spoke a median 70% of the words in ICT debriefs. The teacher gave their own view of the lesson first in only 31% of them."}, {"title": "Record the conversation, not a speech", "text": "32 of 282 ICT recordings and 20 of 57 in Punjab had no teacher voice at all: the coach gave a talk, sometimes reading the AI guide aloud, stage directions included. Most came from a few coaches (11 in ICT, 8 in Punjab)."}, {"title": "End with the teacher's own words", "text": "Debriefs rarely closed with the teacher saying what they will do, and when: 13% in ICT, 0% in Punjab, 43% in Tanzania. One clear next step was agreed in 46% of ICT debriefs."}], "impact": [{"title": "A small, real shift, on the coached skill only", "text": "After a debrief, 12 in 100 ICT teachers moved up a level on the coached skill in their next lesson, and 8 moved down. Among similar teachers with no debrief it was 10 and 10. Other skills did not move. <a href=\"#impact\">The full test</a>"}, {"title": "Concrete steps moved. Questioning did not", "text": "Debriefs about differentiation (+0.23) and group work (+0.34) showed clear change. Debriefs about questioning, 71% of all, showed none we could detect. This split is exploratory, and points at how the step is worded."}]}, "arc": [{"name": "Open and frame", "what": "Greeting, purpose framed as support, link to the last agreed goal.", "seen": {"ict": 0.194, "punjab": 0.1538, "tanzania": 0.6607}}, {"name": "Teacher reflects first", "what": "Coach asks open questions about what went well, what was hard and what students did; teacher speaks before the coach judges.", "seen": {"ict": 0.5388, "punjab": 0.4231, "tanzania": 0.2679}}, {"name": "Specific strength", "what": "Coach names one or two strengths tied to concrete lesson moments and their effect on students.", "seen": {"ict": 0.8879, "punjab": 0.5385, "tanzania": 0.7321}}, {"name": "Agree one growth area with evidence", "what": "Teacher self-identifies or coach scaffolds toward one growth area, grounded in a specific moment; coach justifies why it matters.", "seen": {"ict": 0.6897, "punjab": 0.8846, "tanzania": 0.7143}}, {"name": "Name one concrete action step", "what": "One bite-sized, observable action the teacher can use in the next lesson, ideally co-constructed.", "seen": {"ict": 0.4655, "punjab": 0.3846, "tanzania": 0.625}}, {"name": "Model and rehearse", "what": "Coach models with reasons, teacher rehearses or scripts the step, coach gives quick feedback, teacher tries again.", "seen": {"ict": 0.0345, "punjab": 0.0, "tanzania": 0.0}}, {"name": "Plan ahead, commit and set follow-up", "what": "Teacher says when and where they will use the step, writes it into the next lesson plan if possible, success sign and follow-up date or check-in agreed.", "seen": {"ict": 0.1293, "punjab": 0.0, "tanzania": 0.4286}}], "rubric": [{"id": "purpose_and_relationship_opening", "name": "Opening: purpose, rapport and link to the last goal", "short": "Opening", "why": "Programme guidance says coaching only works inside a trusting relationship and that the coach should act as a mentor, not an inspector; the opening is where the purpose is framed as support. Evidence is practitioner guidance plus qualitative studies, not causal.", "strength": "Practitioner guidance", "citations": [{"author": "Wilichowski, T. and Popova, A. (World Bank Coach)", "year": 2021, "title": "Facilitating Effective 1-1 Coaching Sessions (Coach series summary)", "url": "https://thedocs.worldbank.org/en/doc/5b7f39c1822ef0127c8596fe0fb1ced0-0200022022/related/20220615-Facilitating-Effective-1-1-Coaching-Sessions-FINAL.pdf"}, {"author": "Kraft, M. A., Blazar, D. and Hogan, D.", "year": 2018, "title": "The Effect of Teacher Coaching on Instruction and Achievement: A Meta-Analysis of the Causal Evidence", "url": "https://journals.sagepub.com/doi/abs/10.3102/0034654318759268"}]}, {"id": "teacher_self_reflection", "name": "Teacher reflects first and analyses their own lesson", "short": "Teacher reflects first", "why": "World Bank Coach guidance starts the session with teacher reflection, and Bambrick-Santoyo's model asks the teacher to self-identify the problem before the coach names it. Reflection was part of the My Teaching Partner package that raised achievement in a randomised trial, but its separate effect has not been isolated. Practitioner consensus.", "strength": "Practitioner (part of programmes with causal effects)", "citations": [{"author": "Wilichowski, T. and Popova, A. (World Bank Coach)", "year": 2021, "title": "Facilitating Effective 1-1 Coaching Sessions (Coach series summary)", "url": "https://thedocs.worldbank.org/en/doc/5b7f39c1822ef0127c8596fe0fb1ced0-0200022022/related/20220615-Facilitating-Effective-1-1-Coaching-Sessions-FINAL.pdf"}, {"author": "Bambrick-Santoyo, P.", "year": 2012, "title": "Leverage Leadership: A Practical Guide to Building Exceptional Schools", "url": "https://www.oreilly.com/library/view/leverage-leadership-a/9781118238929/"}, {"author": "Allen, J. P., Pianta, R. C., Gregory, A., Mikami, A. Y. and Lun, J.", "year": 2011, "title": "An Interaction-Based Approach to Enhancing Secondary School Instruction and Student Achievement", "url": "https://eric.ed.gov/?id=ED556046"}]}, {"id": "coach_questioning_and_dialogue", "name": "Coach questioning and dialogue (who does the thinking)", "short": "Questions and dialogue", "why": "Studies of recorded coaching and supervision conferences repeatedly find coach or supervisor monologue dominating, which practitioner frameworks (Knight's partnership principles, Coach guidance) say limits teacher learning. Evidence is descriptive plus practitioner consensus; no published talk-ratio target exists.", "strength": "Practitioner and descriptive studies", "citations": [{"author": "Heineke, S. F.", "year": 2013, "title": "Coaching Discourse: Supporting Teachers' Professional Learning", "url": "https://eric.ed.gov/?id=EJ1013985"}, {"author": "Koc, F. S. and Savas, P.", "year": 2024, "title": "Supervision Models and Supervisory Feedback in English Language Teacher Education: A Meta-Synthesis Study Adopting a Discourse Analytic Perspective", "url": "https://tesl-ej.org/wordpress/issues/volume27/ej108/ej108a1/"}, {"author": "Knight, J.", "year": 2018, "title": "The Impact Cycle: What Instructional Coaches Should Do to Foster Powerful Improvements in Teaching", "url": "https://books.google.com/books/about/The_Impact_Cycle.html?id=79QuDwAAQBAJ"}]}, {"id": "evidence_from_the_lesson", "name": "Feedback grounded in specific lesson evidence", "short": "Evidence from the lesson", "why": "Coach guidance says feedback must be justified by specific examples from the observation; feedback research finds feedback about the task and process helps, while feedback aimed at the person can lower performance (over a third of feedback interventions reduced performance in one large meta-analysis). Mixed causal and correlational evidence from outside teaching, plus programme guidance.", "strength": "Correlational (feedback meta-analyses) and programme guidance", "citations": [{"author": "Hattie, J. and Timperley, H.", "year": 2007, "title": "The Power of Feedback", "url": "https://www.semanticscholar.org/paper/The-Power-of-Feedback-Hattie-Timperley/a341536770fc149df10408865bfb58f76246cfdc"}, {"author": "Kluger, A. N. and DeNisi, A.", "year": 1996, "title": "The effects of feedback interventions on performance: A historical review, a meta-analysis, and a preliminary feedback intervention theory", "url": "https://scholars.huji.ac.il/avrahamkluger/publications/effects-feedback-interventions-performance-historical-review-meta"}, {"author": "Wilichowski, T. and Popova, A. (World Bank Coach)", "year": 2021, "title": "Facilitating Effective 1-1 Coaching Sessions (Coach series summary)", "url": "https://thedocs.worldbank.org/en/doc/5b7f39c1822ef0127c8596fe0fb1ced0-0200022022/related/20220615-Facilitating-Effective-1-1-Coaching-Sessions-FINAL.pdf"}]}, {"id": "focus_on_one_growth_area", "name": "Focus on one (at most two) growth areas", "short": "One growth area", "why": "World Bank Coach guidance identifies 1 to 2 target skills per session and the TEACH-based approach recommends one growth area; Bambrick-Santoyo calls for one bite-sized step. Kraft et al. found more coaching hours did not predict bigger effects, suggesting quality and focus matter more. Practitioner consensus, consistent with goal-setting evidence.", "strength": "Practitioner guidance", "citations": [{"author": "Wilichowski, T. and Popova, A. (World Bank Coach)", "year": 2021, "title": "Facilitating Effective 1-1 Coaching Sessions (Coach series summary)", "url": "https://thedocs.worldbank.org/en/doc/5b7f39c1822ef0127c8596fe0fb1ced0-0200022022/related/20220615-Facilitating-Effective-1-1-Coaching-Sessions-FINAL.pdf"}, {"author": "Bambrick-Santoyo, P.", "year": 2012, "title": "Leverage Leadership: A Practical Guide to Building Exceptional Schools", "url": "https://www.oreilly.com/library/view/leverage-leadership-a/9781118238929/"}, {"author": "Kraft, M. A., Blazar, D. and Hogan, D.", "year": 2018, "title": "The Effect of Teacher Coaching on Instruction and Achievement: A Meta-Analysis of the Causal Evidence", "url": "https://journals.sagepub.com/doi/abs/10.3102/0034654318759268"}]}, {"id": "concrete_action_step", "name": "A concrete, observable next step", "short": "Concrete next step", "why": "Effective feedback answers 'where to next' (feed forward); Bambrick-Santoyo's model requires one bite-sized action step; across 104 randomised PD trials, programmes that combined goal-setting, technique and practice mechanisms had larger effects; and specifying when and how to act (implementation intentions) improves goal attainment (d = 0.65 in a meta-analysis outside education).", "strength": "Correlational across trials; causal outside education", "citations": [{"author": "Hattie, J. and Timperley, H.", "year": 2007, "title": "The Power of Feedback", "url": "https://www.semanticscholar.org/paper/The-Power-of-Feedback-Hattie-Timperley/a341536770fc149df10408865bfb58f76246cfdc"}, {"author": "Bambrick-Santoyo, P.", "year": 2012, "title": "Leverage Leadership: A Practical Guide to Building Exceptional Schools", "url": "https://www.oreilly.com/library/view/leverage-leadership-a/9781118238929/"}, {"author": "Sims, S., Fletcher-Wood, H., O'Mara-Eves, A., Cottingham, S., Stansfield, C., Goodrich, J., Van Herwegen, J. and Anders, J.", "year": 2022, "title": "Effective teacher professional development: new theory and a meta-analytic test (EdWorkingPaper 22-507)", "url": "https://files.eric.ed.gov/fulltext/ED616856.pdf"}, {"author": "Gollwitzer, P. M. and Sheeran, P.", "year": 2006, "title": "Implementation intentions and goal achievement: A meta-analysis of effects and processes", "url": "https://www.socmot.uni-konstanz.de/publications/implementation-intentions-and-goal-achievement-meta-analysis-effects-and-processes"}]}, {"id": "practice_or_modelling", "name": "Modelling and rehearsal of the step", "short": "Practice or modelling", "why": "Across professional development programmes in low- and middle-income countries, lesson enactment (practising during training) was associated with larger learning gains; in a meta-analysis of 104 PD trials, rehearsal and modelling are among the mechanisms in better-designed programmes; Coach and Bambrick-Santoyo both build practice into the meeting itself. Correlational evidence across trials plus strong practitioner consensus.", "strength": "Correlational across trials, including low- and middle-income countries", "citations": [{"author": "Popova, A., Evans, D. K., Breeding, M. E. and Arancibia, V.", "year": 2019, "title": "Teacher Professional Development around the World: The Gap between Evidence and Practice (CGD Working Paper 517)", "url": "https://www.cgdev.org/publication/teacher-professional-development-around-world-gap-between-evidence-and-practice"}, {"author": "Sims, S., Fletcher-Wood, H., O'Mara-Eves, A., Cottingham, S., Stansfield, C., Goodrich, J., Van Herwegen, J. and Anders, J.", "year": 2022, "title": "Effective teacher professional development: new theory and a meta-analytic test (EdWorkingPaper 22-507)", "url": "https://files.eric.ed.gov/fulltext/ED616856.pdf"}, {"author": "Grossman, P., Compton, C., Igra, D., Ronfeldt, M., Shahan, E. and Williamson, P.", "year": 2009, "title": "Teaching Practice: A Cross-Professional Perspective", "url": "https://www.semanticscholar.org/paper/Teaching-Practice%3A-A-Cross-Professional-Grossman-Compton/6018abe8f22ac30ec7937edf6dea8989f3e9b105"}, {"author": "Lampert, M., Franke, M. L., Kazemi, E., Ghousseini, H., Turrou, A. C., Beasley, H., Cunard, A. and Crowe, K.", "year": 2013, "title": "Keeping it complex: Using rehearsals to support novice teacher learning of ambitious teaching", "url": "https://www.scirp.org/reference/referencespapers?referenceid=2455221"}, {"author": "Wilichowski, T. and Popova, A. (World Bank Coach)", "year": 2021, "title": "Facilitating Effective 1-1 Coaching Sessions (Coach series summary)", "url": "https://thedocs.worldbank.org/en/doc/5b7f39c1822ef0127c8596fe0fb1ced0-0200022022/related/20220615-Facilitating-Effective-1-1-Coaching-Sessions-FINAL.pdf"}]}, {"id": "commitment_and_follow_up", "name": "Teacher commitment, timeline and follow-up", "short": "Commitment and follow-up", "why": "Coach guidance ends with agreeing when and how the teacher will use the skill, citing implementation-intention evidence; implementers in many countries report follow-up visits as among the most effective PD features; on-site coaching outperformed virtual coaching in South Africa, with the authors pointing to accountability and support from in-person contact.", "strength": "Correlational; causal outside education", "citations": [{"author": "Wilichowski, T. and Popova, A. (World Bank Coach)", "year": 2021, "title": "Facilitating Effective 1-1 Coaching Sessions (Coach series summary)", "url": "https://thedocs.worldbank.org/en/doc/5b7f39c1822ef0127c8596fe0fb1ced0-0200022022/related/20220615-Facilitating-Effective-1-1-Coaching-Sessions-FINAL.pdf"}, {"author": "Gollwitzer, P. M. and Sheeran, P.", "year": 2006, "title": "Implementation intentions and goal achievement: A meta-analysis of effects and processes", "url": "https://www.socmot.uni-konstanz.de/publications/implementation-intentions-and-goal-achievement-meta-analysis-effects-and-processes"}, {"author": "Popova, A., Evans, D. K., Breeding, M. E. and Arancibia, V.", "year": 2019, "title": "Teacher Professional Development around the World: The Gap between Evidence and Practice (CGD Working Paper 517)", "url": "https://www.cgdev.org/publication/teacher-professional-development-around-world-gap-between-evidence-and-practice"}, {"author": "Cilliers, J., Fleisch, B., Kotze, J., Mohohlwane, N., Taylor, S. and Thulare, T.", "year": 2021, "title": "Can Virtual Replace In-person Coaching? Experimental Evidence on Teacher Professional Development and Student Learning (RISE WP 20/050)", "url": "https://riseprogramme.org/sites/default/files/2021-01/RISE_WP-050_Cilliers_etal_2021_update_0.pdf"}]}, {"id": "tone_and_psychological_safety", "name": "Tone and psychological safety", "short": "Tone and safety", "why": "Kraft and colleagues note that when the coach is also an evaluator, trust and feedback quality suffer; feedback directed at the self rather than the task tends to hurt performance; team learning behaviour rises with psychological safety; and Pakistani school leaders describe supervision as fault-finding. Correlational and qualitative evidence.", "strength": "Correlational and qualitative", "citations": [{"author": "Kraft, M. A. and Gilmour, A. F.", "year": 2016, "title": "Can Principals Promote Teacher Development as Evaluators? A Case Study of Principals' Views and Experiences", "url": "https://eric.ed.gov/?id=EJ1118321"}, {"author": "Kluger, A. N. and DeNisi, A.", "year": 1996, "title": "The effects of feedback interventions on performance: A historical review, a meta-analysis, and a preliminary feedback intervention theory", "url": "https://scholars.huji.ac.il/avrahamkluger/publications/effects-feedback-interventions-performance-historical-review-meta"}, {"author": "Edmondson, A.", "year": 1999, "title": "Psychological Safety and Learning Behavior in Work Teams", "url": "https://eric.ed.gov/?id=EJ589456"}, {"author": "Gardezi, S., McNamara, G., Brown, M. and O'Hara, J.", "year": 2023, "title": "School inspections: a rhetoric of quality or reality?", "url": "https://www.frontiersin.org/journals/education/articles/10.3389/feduc.2023.1204642/full"}]}], "programmes": {"ict": {"headline": "232 of 282 ICT recordings were two-way debriefs (32 were the coach alone, 18 were not debriefs). They are the longest (median 5 minutes) and the most grounded in the lesson. They are warm and focused, and they almost never include practice. Last week's debriefs look the same as July to September's (median score 43 against 44 out of 100).", "n_scored": 232, "dim_title": "ICT: how the debriefs scored on each part", "dims": {"purpose_and_relationship_opening": {"dist": [14, 173, 44, 1], "mean": 1.138, "n": 232}, "teacher_self_reflection": {"dist": [22, 85, 109, 16], "mean": 1.513, "n": 232}, "coach_questioning_and_dialogue": {"dist": [23, 114, 95, 0], "mean": 1.31, "n": 232}, "evidence_from_the_lesson": {"dist": [2, 54, 142, 34], "mean": 1.897, "n": 232}, "focus_on_one_growth_area": {"dist": [23, 49, 144, 16], "mean": 1.659, "n": 232}, "concrete_action_step": {"dist": [11, 113, 106, 2], "mean": 1.427, "n": 232}, "practice_or_modelling": {"dist": [166, 58, 8, 0], "mean": 0.319, "n": 232}, "commitment_and_follow_up": {"dist": [69, 133, 30, 0], "mean": 0.832, "n": 232}, "tone_and_psychological_safety": {"dist": [0, 19, 161, 52], "mean": 2.142, "n": 232}}, "tiles": [{"label": "Debriefs read", "value": "232", "note": "42 coaches, 28 Sep to 2 Oct"}, {"label": "Typical length", "value": "5 min", "note": "median"}, {"label": "Coach's share of the talking", "value": "70%", "note": "median, by words spoken"}, {"label": "One clear next step agreed", "value": "46%", "note": "106 of 232 debriefs"}, {"label": "Teacher tried the step out loud", "value": "3%", "note": "rehearsed at least once in the meeting"}, {"label": "Overall score", "value": "43/100", "note": "median; middle half 37-51"}], "failure_modes": [{"name": "Teacher never tries the step out loud", "count": 224, "of": 232}, {"name": "No commitment from the teacher", "count": 186, "of": 232}, {"name": "Teacher never reflects first", "count": 160, "of": 232}, {"name": "No single next step agreed", "count": 126, "of": 232}, {"name": "Coach does most of the talking (70%+ of words)", "count": 117, "of": 232}, {"name": "Three or more things to improve at once", "count": 53, "of": 232}, {"name": "Praise stays general", "count": 26, "of": 232}, {"name": "Coach asks no open questions", "count": 22, "of": 232}], "patterns": [{"title": "Good at seeing, weak at practising", "finding": "Coaches describe lesson moments well (evidence mean 1.90, tone 2.15) but the step is almost never tried in the room (practice mean 0.32) or locked in with a when (commitment mean 0.74). The skill gap sits at the end of the debrief, not the start.", "count": "evidence 2+ in 51 of 62; practice 2+ in 2 of 62; commitment 2+ in 5 of 62"}, {"title": "The coach does most of the talking", "finding": "Median coach share is 0.74. Long explanation turns of two to four minutes are common after the teacher's first answer, so the teacher's thinking stops early.", "count": "36 of 62 over 70% coach words; 15 of 62 in the 40-60% band"}, {"title": "Short recordings score low", "finding": "No debrief under 4 minutes scored above 48. Recordings under 4 minutes average 35 against 46 for the rest; many are one coach turn with the teacher silent or absent.", "count": "24 of 62 under 4 minutes (mean overall 35); 38 of 62 at 4 minutes or more (mean 46)"}, {"title": "Teacher raises a real difficulty, coach moves on", "finding": "Teachers often name a constraint (too much material, late notice, a confusing plan, syllabus pressure, worry about being criticised). Coaches acknowledge it in a word and return to their own point instead of turning it into the problem to solve.", "count": "16 of 62"}, {"title": "Teacher offers a fix, coach does not build on it", "finding": "In several debriefs the teacher proposes a workable step (split the lesson over two days, time each stage on the phone, use the Class 2 attention signal) and the coach asks 'what else?' or switches to a different idea.", "count": "11 of 62"}, {"title": "Lesson-plan structure is the default growth area", "finding": "The most common growth area is the five-step lesson structure (missing guided or independent practice, stages merged or out of order). It is usually delivered as a full template rather than one move for tomorrow.", "count": "19 of 62"}, {"title": "Some steps serve the recording, not the children", "finding": "In two debriefs the agreed step is to say stage names aloud so the recording tool can detect them; in others the visit is framed as report, percentage or recording calibration.", "count": "2 of 62 with a recording-detection step; 8 of 62 with report, score or recording framing"}, {"title": "Coach-level habits", "finding": "ICT Coach 21 drew a self-identified growth area in both debriefs (reflection 3 and tone 3 in 2 of 2). ICT Coach 58 closed both debriefs by asking for a 'promise' and the teacher stated a step in both (2 of 2). ICT Coach 24 named a single step in all three debriefs (3 of 3). ICT Coach 26's four recordings are all 80-180 seconds with no commitment in 3 of 4; ICT Coach 04 held 79% or more of the words in all 3.", "count": "Coach 21: 2 of 2; Coach 58: 2 of 2; Coach 24: 3 of 3; Coach 26: 3 of 4; Coach 04: 3 of 3"}, {"title": "Data problems in the upload stream", "finding": "Three pairs of duplicate recordings were found, one of them filed under two different coach pseudonyms, and a fourth recording duplicates one in another group. Six recordings in the group are not debriefs at all, and in 4 the AI guide describes a different lesson from the one discussed.", "count": "3 duplicate pairs in 71; 6 of 71 not debriefs; guide mismatch in 4 of 62"}, {"title": "Feedback is specific and kind", "finding": "Coaches here describe what they saw. Most praise names a teacher action and what the children did (a child saying 'Madam I can't write this', a class correcting each other in guided practice, children choosing the right word themselves). Tone is respectful throughout, and no blaming language was found.", "count": "evidence 2+ in 50 of 64; tone 2+ in 54 of 64"}, {"title": "The teacher is asked, but after the verdict", "finding": "Most coaches ask 'what went well?' and 'what could be better?', which is the right instinct. Usually, though, they first deliver their own praise and judgement, so the teacher responds to the coach rather than reflecting first.", "count": "teacher spoke first in 18 of 64; reflection 0-1 in 32 of 64"}, {"title": "Teachers name their own gap; coaches move on", "finding": "Teachers often volunteer a real difficulty: a skipped activity, children who went quiet, two mistakes, a child stuck on a rule. Coaches tend to reassure ('it's fine') or cut in, then switch to their own point. One coach stopped a teacher twice to 'tell the good things first'.", "count": "teacher named a gap in 27 of 64; that gap became the worked-on area in 3 of 64"}, {"title": "Telling, not practising", "finding": "Steps are explained, sometimes well modelled in the coach's voice, but the teacher is almost never asked to say the instruction aloud or try it. Even the coaches who had a ready-made role play described it instead of doing it.", "count": "no modelling or rehearsal in 49 of 64; teacher rehearsal in 1 of 64"}, {"title": "Ending on assent", "finding": "Closings are 'thank you so much', 'keep up the good work' or 'will you do it next class?', and the teacher answers 'inshallah'. The teacher rarely says what they will do and when, and no debrief fixed a dated follow-up or how both would know the step worked.", "count": "commitment 0-1 in 58 of 64; dated follow-up in 0 of 64"}, {"title": "Several fixes, no priority", "finding": "When coaches move from praise to improvement, they often list several changes in one long turn (back-row engagement, explanation length, group task, homework). The teacher leaves with no clear single focus. The best debriefs narrow explicitly ('one small but important thing').", "count": "3+ areas in 17 of 64; explicit single priority (focus 3) in 4 of 64"}, {"title": "Short debriefs score lower", "finding": "Debriefs under four minutes scored lower on average than longer ones, and none of them scored above 50. All nine top-quartile debriefs lasted about five minutes or more. The extra time in good debriefs went into the teacher's thinking, not into longer coach turns.", "count": "27 of 64 under 4 min, mean 35.2 vs 44.8 for the 37 longer debriefs; 0 of 27 short debriefs above 50"}, {"title": "Lesson-plan and app talk crowds out teaching", "finding": "A large share of several debriefs went on generating or downloading the lesson plan, recording length, the AI assistant or attendance, rather than on a teaching move.", "count": "at least 10 of 64"}, {"title": "Recordings that are not two-way debriefs", "finding": "Some uploads are not conversations: a dictated summary, a teacher's voice note, the guide read aloud, a call with a principal, single-turn coach monologues with no teacher voice, and the same recording uploaded twice.", "count": "4 non-debriefs + 3 duplicate uploads among 71 files; 5 of the 64 valid debriefs are coach-only (mean overall 24)"}, {"title": "Coach-level patterns", "finding": "One coach (ICT Coach 37) scored 61 and 60 on two debriefs, both linking back to the goal agreed last time and both scoring 3 on evidence and tone. A second coach (ICT Coach 57) scored 36, 28, 26 and 22, with no genuine questions in any of the four, two of which were coach-only. A third (ICT Coach 26) held all four debriefs under four minutes, with reflection at 1 in each. A fourth (ICT Coach 04) opened all four by asking the teacher for 'best practices' and scored 3 on evidence in three of the four, but raised two or three areas and never got a rehearsal. Two coaches reuse a fixed closing move: 'promise me one thing' (ICT Coach 58) and 'what would make the lecture more proficient?' (ICT Coach 52).", "count": "19 coaches with 2+ debriefs, of 36 coaches"}, {"title": "Praise is specific and the tone is safe", "finding": "Coaches name real teaching moves and student responses (flash cards, a water-skin prop, a child's question welcomed). Specific praise appears in 54 of 65 and evidence scores 2 or 3 in 47 of 65; tone scores 2 or 3 in 58 of 65 and no debrief is blaming.", "count": "54 of 65 specific praise; 58 of 65 tone 2+"}, {"title": "The coach judges first, then explains", "finding": "In 44 of 65 the coach evaluates the lesson before the teacher does, usually in a long praise turn, and in 33 of 65 the coach holds over 70 percent of the words. Open questions are asked but rarely probed.", "count": "44 of 65 coach first; 33 of 65 over 70% coach talk"}, {"title": "Practice almost never happens", "finding": "The teacher said the step aloud in 3 of 65 debriefs. In 13 more the coach modelled good classroom words but never asked the teacher to try them, so the strongest raw material went unused.", "count": "3 of 65 rehearsal; 13 of 65 model only"}, {"title": "Debriefs end on thanks, not a plan", "finding": "54 of 65 end without the teacher restating a step with a when; a specific follow-up is agreed in 3 of 65. Two coaches hand follow-up to 'whoever the next coach is'.", "count": "54 of 65; follow-up 3 of 65"}, {"title": "The teacher's own diagnosis is often dropped", "finding": "In 12 of 65 the teacher names a precise growth area (longer practice, an exit ticket, a working attention signal, children solving in groups) and the coach moves to a different topic of their own.", "count": "12 of 65"}, {"title": "Building on the teacher's diagnosis goes with better debriefs", "finding": "The 5 debriefs where the teacher analysed students and owned the growth area average 54 overall against a group mean of 42; 3 of the 5 are by one coach.", "count": "5 of 65"}, {"title": "Lesson-plan fidelity is the default growth area, sometimes framed by score", "finding": "Coaches frequently make 'follow the five-step plan' the growth area, and in 8 of 65 they frame it through scores, credit or how the recording is marked ('zero credit', 'your score will go down', 'say the stage names so it is picked up').", "count": "8 of 65 score or credit framing"}, {"title": "Coach-level habits are visible", "finding": "Among coaches with two or more debriefs: ICT Coach 12 has the highest and third-highest scores (76, 62) and 2 of the group's 3 teacher rehearsals; ICT Coach 04 draws strong teacher reflection in 3 of 3 (3 of the 5 top reflection scores) but never reaches a commitment; ICT Coach 24 keeps coach talk at or under 0.57 and lands one concrete step in 4 of 4, with no practice in any; ICT Coach 26 uses the same scripted opening in 4 of 4, all under three minutes, with questioning scored 1 in 4 of 4; ICT Coach 40 has both debriefs in the bottom quarter (20 and 27, against a median of 42), each with tone scored 1.", "count": "Coach 12: 2 of 2; Coach 04: 3 of 3; Coach 24: 4 of 4; Coach 26: 4 of 4; Coach 40: 2 of 2"}, {"title": "Recording problems hide the teacher", "finding": "8 of 65 recordings contain only the coach's voice, clustered in 5 coaches (three coaches have 2 of 2 coach-only). A further 2 files are the coach reading the AI guide aloud and 2 are duplicate uploads.", "count": "8 of 65; plus 4 of 70 files not usable"}, {"title": "Praise first, reflection second", "finding": "Coaches open with their own list of strengths before the teacher evaluates the lesson. The praise is usually specific, but it means the teacher's first reflection is a reaction to the coach's verdict.", "count": "48 of 62"}, {"title": "Teachers do reflect when asked", "finding": "The 'what went well / what was missed' question pair draws real analysis in many debriefs; teachers name their own gap and sometimes their own fix (priced objects, opposite tasks for neighbours, moving the back row).", "count": "30 of 62 score 2+ on teacher_self_reflection"}, {"title": "Advice is described, never tried", "finding": "Steps are explained, sometimes with a model line from the coach, but the teacher almost never says the step aloud. This is the largest gap against the ideal arc, where practice is the biggest block.", "count": "43 of 62 no modelling or rehearsal; 2 of 62 teacher rehearsal"}, {"title": "Endings rely on 'insha'Allah'", "finding": "Most debriefs close with thanks and teacher assent. Some coaches ask for a promise ('ek ahad'), which is a good move, but accept a general answer ('follow the lesson plan more') instead of a class and a day.", "count": "54 of 62 commitment 0 or 1; follow-up set in 3 of 62"}, {"title": "Very short or one-voice recordings score lowest", "finding": "Debriefs under two minutes average 31.9 against 47.7 for those of 4-12 minutes. In 8 recordings only the coach is heard, so reflection and commitment cannot happen on tape.", "count": "14 of 62 under 2 minutes; 8 of 62 teacher not heard"}, {"title": "Lesson-plan fidelity as the default growth area", "finding": "When coaches do not use the guide's suggested move, they most often fall back on 'follow the five steps' or lesson-plan fidelity, which is a goal rather than one observable action, and sometimes links to the app's score.", "count": "14 of 62 name the lesson plan or its steps as an improvement area"}, {"title": "Score and app framing creeps in", "finding": "A minority of coaches explain the visit as checking the app's marking or tie the step to the teacher's digital coaching score or a red fidelity rating. Teachers in these debriefs react with justification ('you did more judgement').", "count": "6 of 62"}, {"title": "Coach-level: ICT Coach 52 closes well", "finding": "Both debriefs by ICT Coach 52 score 57 or more, both reach commitment 2 with the teacher restating the step for the next class, and both include modelling.", "count": "2 of 2"}, {"title": "Coach-level: ICT Coach 26 is safe but stops early", "finding": "ICT Coach 26 draws good teacher reflection (2 in 4 of 5) and safety (3 in 3 of 5), but all five debriefs are five minutes or shorter, none includes modelling and none reaches a restated commitment.", "count": "5 of 5 practice 0; 5 of 5 commitment 0 or 1"}, {"title": "Coach-level: ICT Coach 04 is rich on evidence, weak on focus", "finding": "ICT Coach 04 gives detailed, student-grounded feedback (evidence 3 in 2 of 3) but raises three or four areas each time with none prioritised.", "count": "3 of 3 focus 0 or 1"}, {"title": "Coach-level: ICT Coach 57 runs very short debriefs", "finding": "Three of four debriefs by ICT Coach 57 are under two minutes; mean overall 31.8; in two the teacher gives no account of the lesson.", "count": "3 of 4 under 2 minutes"}, {"title": "Data hygiene problems in the upload stream", "finding": "Three audio files were uploaded twice (one under two coach pseudonyms), two recordings are a coach reading the AI guide aloud, one is a classroom lesson and two are a briefing or report orientation.", "count": "8 of 70 files are duplicates or not debriefs"}]}, "punjab": {"headline": "Only 26 of the 57 Punjab recordings were two-way debriefs. 20 were the coach speaking alone, often reading the AI guide, and 11 were not debriefs at all. The 26 real conversations, from 8 coaches, are short (median 3 minutes) and coach-led, so treat Punjab's numbers as early.", "n_scored": 26, "dim_title": "Punjab: how the debriefs scored on each part", "dims": {"purpose_and_relationship_opening": {"dist": [5, 17, 4, 0], "mean": 0.962, "n": 26}, "teacher_self_reflection": {"dist": [3, 12, 11, 0], "mean": 1.308, "n": 26}, "coach_questioning_and_dialogue": {"dist": [3, 17, 6, 0], "mean": 1.115, "n": 26}, "evidence_from_the_lesson": {"dist": [3, 10, 12, 1], "mean": 1.423, "n": 26}, "focus_on_one_growth_area": {"dist": [2, 1, 21, 2], "mean": 1.885, "n": 26}, "concrete_action_step": {"dist": [3, 13, 10, 0], "mean": 1.269, "n": 26}, "practice_or_modelling": {"dist": [19, 7, 0, 0], "mean": 0.269, "n": 26}, "commitment_and_follow_up": {"dist": [13, 13, 0, 0], "mean": 0.5, "n": 26}, "tone_and_psychological_safety": {"dist": [0, 2, 22, 2], "mean": 2.0, "n": 26}}, "tiles": [{"label": "Debriefs read", "value": "26", "note": "8 coaches, 28 Sep to 2 Oct"}, {"label": "Typical length", "value": "3 min", "note": "median"}, {"label": "Coach's share of the talking", "value": "74%", "note": "median, by words spoken"}, {"label": "One clear next step agreed", "value": "42%", "note": "11 of 26 debriefs"}, {"label": "Teacher tried the step out loud", "value": "0%", "note": "rehearsed at least once in the meeting"}, {"label": "Overall score", "value": "35/100", "note": "median; middle half 31-46"}], "failure_modes": [{"name": "Teacher never tries the step out loud", "count": 26, "of": 26}, {"name": "No commitment from the teacher", "count": 24, "of": 26}, {"name": "Teacher never reflects first", "count": 23, "of": 26}, {"name": "Coach does most of the talking (70%+ of words)", "count": 17, "of": 26}, {"name": "No single next step agreed", "count": 15, "of": 26}, {"name": "Praise stays general", "count": 12, "of": 26}, {"name": "Coach asks no open questions", "count": 2, "of": 26}, {"name": "Three or more things to improve at once", "count": 1, "of": 26}], "patterns": [{"title": "Half the recordings are the coach alone", "finding": "28 of 57 recordings contain only the coach's voice. 18 of these recite or closely mirror the AI guide, often with its stage directions read out ('stay silent here', 'the teacher has to answer'). They come from four coaches: PB Coach 08 (9 recordings, none with a teacher heard), PB Coach 17 (5), PB Coach 09 (3) and PB Coach 06 (1). A further 5 files from PB Coach 10 are one identical 56 s message uploaded five times. These recordings cannot show a conversation and were set aside.", "count": "28 of 57"}, {"title": "Short, verdict-first conversations", "finding": "Two-way debriefs are short (median 155.5 s; 18 of 26 under 4 minutes) and 20 of 26 open with a one-line verdict ('bahut achha lecture') before the teacher says anything.", "count": "20 of 26"}, {"title": "The teacher's own diagnosis is dropped", "finding": "In 11 of 26 the teacher names a specific problem or fix (children answer 'yes' without reasons, a shy child mumbles, ten weaker readers, more thinking time, a drawing activity) and the coach says 'bilkul sahi' and moves to a different suggestion or to nothing. This happens in 4 of the 6 best debriefs too.", "count": "11 of 26"}, {"title": "'Add an activity' is the default advice", "finding": "In 15 of 26 the main suggestion is to add an activity or group or pair work, often without pointing to a moment in the lesson where it would have helped.", "count": "15 of 26"}, {"title": "Told, never tried", "finding": "No teacher rehearses the step in any debrief (0 of 26); in 19 of 26 there is not even an example script. The closest is a coach listing sample questions while the teacher listens.", "count": "0 of 26 rehearsed"}, {"title": "Open-ended endings", "finding": "No debrief sets a day, a check-in or a success sign (0 of 26), and no teacher restates the step with a when (0 of 26). 6 of 26 end on bare assent ('ji sir', 'sahi').", "count": "0 of 26"}, {"title": "Talk share is not a quality marker here", "finding": "The 6 debriefs with balanced talk (coach 40 to 60% of words) average 30.5 overall, below the group mean of 37.5, because the teacher's extra talk is general. The 6 best debriefs all have the coach at 70 to 83% of words.", "count": "6 of 26"}, {"title": "Coach habits are consistent", "finding": "PB Coach 30 (4 debriefs, overall 51 to 60) is the only coach who states a joint purpose (4 of 4) and gives an example script every time (4 of 4). PB Coach 29 (4 debriefs, 42 to 52) always asks the teacher's view before giving feedback (4 of 4) and gets a detailed reflection each time (4 of 4 at 2). PB Coach 04 (6 debriefs, 27 to 35) uses the same script each time: vague praise (0 of 6 specific), 'how can we improve?', leading yes/no questions about activities, 'see you next week'. PB Coach 32 (6 two-way debriefs) holds both tone scores of 3.", "count": "18 of 26 from four coaches"}, {"title": "Safe, respectful tone", "finding": "23 of 26 are respectful and lesson-focused; nobody reads out scores or mentions reports (0 of 26). Only 2 show clear defensiveness, both after the coach opened with criticism.", "count": "23 of 26"}]}, "tanzania": {"headline": "Tanzania debriefs are the shortest (median 1.6 minutes) but the most likely to end with one clear step (71%) and a commitment from the teacher. They rarely start with the teacher's own view.", "n_scored": 56, "dim_title": "Tanzania: how the debriefs scored on each part", "dims": {"purpose_and_relationship_opening": {"dist": [1, 18, 37, 0], "mean": 1.643, "n": 56}, "teacher_self_reflection": {"dist": [3, 38, 15, 0], "mean": 1.214, "n": 56}, "coach_questioning_and_dialogue": {"dist": [1, 40, 15, 0], "mean": 1.25, "n": 56}, "evidence_from_the_lesson": {"dist": [1, 23, 31, 1], "mean": 1.571, "n": 56}, "focus_on_one_growth_area": {"dist": [5, 11, 39, 1], "mean": 1.643, "n": 56}, "concrete_action_step": {"dist": [4, 17, 35, 0], "mean": 1.554, "n": 56}, "practice_or_modelling": {"dist": [51, 5, 0, 0], "mean": 0.089, "n": 56}, "commitment_and_follow_up": {"dist": [5, 27, 24, 0], "mean": 1.339, "n": 56}, "tone_and_psychological_safety": {"dist": [0, 1, 54, 1], "mean": 2.0, "n": 56}}, "tiles": [{"label": "Debriefs read", "value": "56", "note": "36 coaches, 28 Sep to 2 Oct"}, {"label": "Typical length", "value": "2 min", "note": "median"}, {"label": "Coach's share of the talking", "value": "74%", "note": "median, by words spoken"}, {"label": "One clear next step agreed", "value": "71%", "note": "40 of 56 debriefs"}, {"label": "Teacher tried the step out loud", "value": "0%", "note": "rehearsed at least once in the meeting"}, {"label": "Overall score", "value": "45/100", "note": "median; middle half 38-50"}], "failure_modes": [{"name": "Teacher never tries the step out loud", "count": 56, "of": 56}, {"name": "Teacher never reflects first", "count": 50, "of": 56}, {"name": "Coach does most of the talking (70%+ of words)", "count": 33, "of": 56}, {"name": "No commitment from the teacher", "count": 27, "of": 56}, {"name": "No single next step agreed", "count": 16, "of": 56}, {"name": "Praise stays general", "count": 15, "of": 56}, {"name": "Coach asks no open questions", "count": 1, "of": 56}, {"name": "Three or more things to improve at once", "count": 0, "of": 56}], "patterns": [{"title": "The guide script is followed, but it skips the teacher's thinking", "finding": "Debriefs judged to follow the guide closely reach a concrete step and a 'when' far more often, but the teacher almost never analyses the lesson: in guide-following debriefs, teacher reflection reaches 2 in 0 of 26 and the teacher speaks first in 0 of 26, against 14 of 32 and 6 of 32 in the rest.", "count": "0 of 26 vs 14 of 32"}, {"title": "Coach answers the teacher's first reply with a ready-made step", "finding": "In my count from reader files, the coach moves from the teacher's first short answer straight to their own (usually the guide's) step without a single follow-up probe.", "count": "35 of 58"}, {"title": "Teacher assent is taken as agreement", "finding": "The teacher's only response to the coach's step is 'Sawa, nitajaribu' or similar, with no restatement in their own words.", "count": "31 of 58"}, {"title": "Teachers hand coaches the growth area and it is dropped", "finding": "The teacher names a specific difficulty (place value, borrowing, the 'I' to 'she' song line, fluency) and the coach neither makes it the focus nor builds a step from it.", "count": "11 of 58"}, {"title": "Constraints raised by teachers are passed over", "finding": "The teacher gives a reason or constraint (time, young pupils, pupils not ready, 10 minutes is a lot) and the coach moves on without acknowledging it or adapting the step.", "count": "8 of 58"}, {"title": "Questions that presume a fault", "finding": "The guide's stem 'nini kilikufanya usi.../wasi...' ('what made you not...') is used in at least 13 debriefs (10 confirmed in transcripts, 3 from reader summaries); it tends to draw a defence rather than reflection.", "count": "13 of 58"}, {"title": "Guide text read aloud", "finding": "Readers flagged near-verbatim reading of the guide in 21 of 58; 3 of 58 attribute the content to 'Rumi' aloud, and 2 read stage directions aloud (timestamps in da94b52c9c9; the '30 to 60' seconds wait read as minutes in dd0664d7298).", "count": "21 of 58"}, {"title": "Coach style is consistent within coach", "finding": "Of 20 coaches with two valid debriefs, several show a stable style: TZ Coach 12 and TZ Coach 29 use the three-open-question template in all 4 of their debriefs (reflection 2, evidence 1, step 1 in all 4); TZ Coach 14 lets the teacher talk most in both (coach share 0.43 and 0.34) but raises no area; TZ Coach 21 ends both without any step (step 0, commitment 0); TZ Coach 40 gives detailed lesson evidence and builds on the teacher's own plan in both (evidence 2 and focus 2, both about 4.5 minutes); TZ Coach 41 uses the same script and a closed yes/no question in both.", "count": "6 of 20 coaches with 2 debriefs"}, {"title": "Very short debriefs score lowest", "finding": "All 8 debriefs scoring 30 or below last under 2 minutes, and 7 of those 8 end with no concrete step.", "count": "8 of 8"}]}}, "clips": [{"key": "d4beedf9f54_ict1_00", "file": "clips/d4beedf9f54_ict1_00.mp3", "dur": 24.4, "kind": "strength", "dimension": "coach_questioning_and_dialogue", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 16", "title": "'Where exactly did you feel that?'", "quote_original": "اچھا، یہ آپ کو کہاں فیل ہوا؟ کس جگہ پہ آ کے؟ | مجھے تقریباً، مطلب، اینڈ پہ نا، جو میرا لاسٹ گروپ ایکٹیویٹی آیا نا، اور بچوں میں، بچوں نے معرفہ اور نکرہ پہ ہی وہ ابھی اٹک رہے تھے۔ تو پھر میں صوت اور اعلیٰ پہ تو ذرا وہ کر بھی لیتے۔ تو اس لیے میں سوچ رہی تھی، اگر میں صرف تین چیزیں کرتی نا، اسم بالحاظ، معنی کرتی، آج معرفہ اور نکرہ کے ساتھ صرف میں صفت اور موصوف کر لیتی۔", "quote_en": "Coach: Where did you feel that? At what point? | Teacher: Near the end, at my last group activity, the children were still stuck on definite and indefinite nouns. So I was thinking, if I had done only three things, today I would have done just adjective and noun along with definite and indefinite.", "why": "A seven-word probe turns the teacher's general worry ('too many topics') into a specific moment, what the children did there, and what the teacher would change. This is the move that most separates the best debriefs from the rest.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "d400c6a08ca_ict1_01", "file": "clips/d400c6a08ca_ict1_01.mp3", "dur": 43.1, "kind": "strength", "dimension": "concrete_action_step", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 12", "title": "Teacher chooses where the new question goes", "quote_original": "جی۔ تو وہ پھر تھوڑا سا lesson سے ہٹ کے بھی ہو سکتا ہے۔ وہ آپ کی اپنی creativity ہے، teacher کس جگہ پہ اس کو use کرنا چاہے، کیوں اور کیسے کے سوالات ہم ان کو add کر سکتے ہیں۔ تو ma'am، ایسا کر سکتے ہیں؟ اگر next class اگر آپ کی کوئی بھی ہوتی ہے، اسی topic کی ہوتی ہے، تو آپ کیا سمجھتی ہیں، کہاں پر آپ اس طرح کے سوالات pinch کر سکتے ہیں؟ کوئی ایسی جگہ، کوئی شروع میں، درمیان میں، آخر میں، یا کہاں پر؟ Independent work کے دوران۔ | اسی پہ، اسی اسی طرح کے topic پہ، یا like... جیسے ابھی میں نے ایک reading کرانی ہے۔ | جی، reading کرانی ہے۔ | بچوں کو reading کراتے ہوئے پھر میں کوئی سا بھی ان کو ایک paragraph، دو چار لائن کا دوں گی، اور وہ بچہ read کر رہا ہے۔ | جی۔ | تو میں اس سے یہی پوچھوں گی کہ ہاں بتائیں کہ اس میں یہ والا sentence کیوں آیا۔", "quote_en": "Coach: It is your own creativity where you use it; we can add why and how questions. So, ma'am, in your next class on this topic, where do you think you could slip in this kind of question? Beginning, middle, end, during independent work? | Teacher: Like now, I have a reading to do. | Coach: Yes, a reading. | Teacher: While the children read, I will give a paragraph of two or four lines and a child is reading. | Coach: Yes. | Teacher: Then I will ask just this: tell me, why did this sentence come here?", "why": "Instead of telling the teacher where to use 'why' questions, the coach asks, and the teacher names the lesson, the activity and the exact words. The step is co-built and observable; the only thing missing is a follow-up date.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "dbcd7358a9f_ict1_02", "file": "clips/dbcd7358a9f_ict1_02.mp3", "dur": 29.1, "kind": "strength", "dimension": "coach_questioning_and_dialogue", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 58", "title": "'What did you do that made it work?'", "quote_original": "اور آپ کی اس میں کیا، as a teacher، آپ کا کیا ایکشن تھا جس کی وجہ سے بچے کر پا رہے تھے؟ | میں نے بچوں کو ٹائم دیا، اس چیز کے لیے، سوچنے کا ٹائم دیا، اور آپس میں، مطلب، جیسے بچے کولیبریٹ نہیں کر رہے تھے، انڈیویجول وہ چاہ رہے تھے کہ ہم اچیو کر لیں، ہم جیت جائیں۔ تو میں نے کہا کہ نہیں، آپ لوگ مل کے کریں۔ تو کچھ بچے تھے جو مل کے کر نہیں رہے تھے، تو میں نے ان کو انکریج کیا، بیٹا، آپ مل کے کرو۔ جب انہوں نے مل کے کیا تو انہوں نے پھر آنسر کیا۔ اس سے پہلے میں نے ان کو دیکھ رہی تھی کہ وہ بلینک بیٹھے تھے، دونوں بچے، لیکن جب انہوں نے مل کے کیا تو at least وہ ایک سینٹنس کا آنسر ان کو بھی مل گیا تھا۔ تو یہ چیز مجھے اچھی لگی، بچوں کی۔", "quote_en": "Coach: And as a teacher, what was your action that made the children able to do it? | Teacher: I gave them time to think. Some wanted to win on their own, so I said no, do it together, and I encouraged the ones who were not working together. Before that, two children were sitting blank, but when they worked together they at least got a one-sentence answer. I liked that.", "why": "One probe links the teacher's own move to what two specific children did. The teacher, not the coach, explains why the strength worked, which makes it repeatable.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "dc4455a0c2a_ict1_03", "file": "clips/dc4455a0c2a_ict1_03.mp3", "dur": 22.4, "kind": "strength", "dimension": "evidence_from_the_lesson", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 36", "title": "Why '7 x 9' was not an open question", "quote_original": "دیکھیں، آپ نے آج یہ کیا تھا، اچھا یہ ہوا، یہ کیسے ہوا، یہ کیسے ہوا، جب math میں نظر آتا ہے نا تو اس کا answer بہت obvious تھا۔ | بالکل۔ | کہ سیون ملٹی پلائی بائی نائن، جب میں نے کیا، سیون کا ٹیبل پڑھا تو یہ آیا۔ یہ obvious answer ہے نا۔ کیوں، کیسے آپ نے پوچھا ہے۔ پر open-ended سوال نہیں پوچھا، جو ان کے اندر کہ اس کا answer obvious نہ ہو، بچے تھوڑا سوچیں پھر جواب۔", "quote_en": "Coach: Look, today you did ask 'how did this happen, how did this happen', but in maths the answer was very obvious. | Teacher: Exactly. | Coach: Seven times nine: I read the seven times table and got it. That is an obvious answer. You asked why and how, but not an open-ended question where the answer is not obvious and children have to think before answering.", "why": "The coach uses the teacher's own question from the lesson to show the difference between a why-question with an obvious answer and a truly open one. The teacher agrees at once because the evidence is theirs.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "d9e33ebab73_ict1_04", "file": "clips/d9e33ebab73_ict1_04.mp3", "dur": 39.9, "kind": "strength", "dimension": "evidence_from_the_lesson", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 09", "title": "Praise that says what it did for children", "quote_original": "گروپ ورک بہت بیسٹ تھا، کیونکہ آپ نے ان سے پریزنٹیشنز دی ہیں۔ تو وہ پریزنٹیشن کے تھرو آپ کو پتہ چل گیا کون سا بچہ کہاں لیگ کر رہا ہے، تو آپ نے ان کو ساتھ ہی سمجھاتی بھی گئی ہیں۔ تو وہ گروپ ورک بہت اچھا تھا، بچوں کو ساتھ بلوایا، بچوں کا کانفیڈنس جو ہے وہ بلڈ ہوا۔ بچے ساتھ پارٹیسپیٹ کرتے ہوئے اپنا گروپ ورک انہوں نے کیا، ہیلپ کی ہے، سپورٹ کیا ہے، اور بڑے اچھے سے کام انہوں نے کر لیا۔ آپ نے اپنا ریپ اپ کروایا، اور اس میں ریپ اپ میں سب سے چیز اچھی مجھے جو لگی وہ یہ کہ ٹیچرز اکثر یہ کرتے ہیں، خود ریپ اپ کر دیتے ہیں نا۔ لیکن آپ نے اوپن اینڈ کے تھرو ان سے اتنے کوئسچنز پوچھ دیے، اوپن اینڈڈ، ساتھ ریپ اپ بھی ہو گیا، اور ساتھ ہی آپ کو سمجھ آ گئی کہ بچوں کی رَوِیان جو ہے وہ بڑی اچھی ہو گئی ہے۔ یہ چیزیں تو دونوں ہیں جو آپ کی بہت اچھی گیم ہے۔ ان کیس، ابھی بھی اگر میں بات کروں۔", "quote_en": "Coach: The group work was the best, because you had them present. Through the presentations you found out which child was lagging, and you explained to them right there. The children's confidence grew; they helped and supported each other. In the wrap-up, what I liked most is that teachers often do the wrap-up themselves, but you asked open-ended questions, so the wrap-up happened and you also saw how well the children had understood.", "why": "Each piece of praise names a teacher action (presentations, explaining on the spot, an open-question wrap-up) and its effect on students, so the teacher knows exactly what to keep doing.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "df48ab6f75e_ict1_05", "file": "clips/df48ab6f75e_ict1_05.mp3", "dur": 26.6, "kind": "strength", "dimension": "teacher_self_reflection", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 21", "title": "Teacher names their own growth area", "quote_original": "میں آ رہا ہوں، جی۔ اور یہ شروع میں میں نے آپ سے پہلے بھی آپ نے میری کلاس آپ نے ابزرو کی ہے کہ ٹائم مینجمنٹ کے حوالے سے تھوڑا سا میں ڈھیلا ہوں۔ کیونکہ یہاں زیادہ باریک میننگ میں چلا جاتا ہوں، پہلے جو چیزیں سمجھانی ہیں میں اس کو skip کر جاتا ہوں۔ اس وجہ سے کچھ زیادہ ٹائم لے جاتا ہوں نا۔ تو آگے کافی چیزیں ہیں وہ missing ہیں جن پہ کام کیا جا سکتا ہے، وہ میں نہیں کر پاتا۔", "quote_en": "Teacher: I'm coming to it. You have observed my class before too: I am a bit slack on time management, because I go into very fine meanings and skip what should be explained first. So I take extra time, and many later things that could be worked on are missing; I can't get to them.", "why": "Asked what was missing, the teacher names the growth area and its cause before the coach says anything. The coach then builds the step (one example in the explanation, one in group, one independent) on this admission.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "d1b8b90e7f4_ict1_06", "file": "clips/d1b8b90e7f4_ict1_06.mp3", "dur": 30.3, "kind": "strength", "dimension": "tone_and_psychological_safety", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 24", "title": "Safe enough to say 'why should I lie?'", "quote_original": "نہیں کرنا چاہیے، بالکل، اپنی وہ ہو جاتا ہے۔ اچھا، لیکن جب ایکٹیویٹیز کرتی ہیں آپ، تو آپ کو لگتا ہے آپ کی کلاس جو ہے، بچے، they act the way they are supposed to act? The discipline wise? | ڈسپلن، وہ تو پھر ہنڈرڈ پرسنٹ ایسے ایکوریسی نہیں رہتی جو صحیح بات ہے۔ تھوڑا بہت تو ڈسٹربنس ہوگی۔ یہ تو پرفیکٹ ہے کہ یہ ون پریپ ون ٹو میں، ایسا نہیں ہو سکتا کہ میں کہوں جی بڑی ڈسپلنڈ کلاس، سب بیٹھے رہیں گے۔ I think it's impossible۔ کہ ہم کیا، میں ہی کیوں جھوٹ بولوں؟ | ہاں، بالکل۔", "quote_en": "Coach: But when you run activities, do you feel the children act the way they are supposed to, discipline-wise? | Teacher: Honestly, discipline is not one hundred percent; there will be some disturbance. In these small classes I can't claim everyone stays seated. I think it's impossible. Why should I lie? | Coach: Yes, exactly.", "why": "A curious, non-blaming question lets the teacher admit a real difficulty, and the coach accepts it as normal. That admission becomes the single target the rest of the debrief works on.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "dbf1d9ede30_ict1_08", "file": "clips/dbf1d9ede30_ict1_08.mp3", "dur": 34.1, "kind": "missed_opportunity", "dimension": "practice_or_modelling", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 04", "title": "Seven minutes of telling, then 'did you understand?'", "quote_original": "یہ آپ نے سب مجھے بتا دیا۔ | یہ آپ کو سمجھ آ گیا؟ اس میں پھر آپ کو کوئی پرابلم ہو؟ سب سے پہلے پرائر نالج میں آپ نے خود سے نہیں پوچھنا۔ میں آپ کو لکھ کے بھیج دوں گا، یہ میں نے بہت رف سا لکھا ہوا ہے، تو میں آپ کو نا یہ ڈیٹیل میں میسج بھی کر دوں گا۔ اچھا اوپننگ میں ہوتا ہے کہ آپ پرائر نالج پوچھتے ہو، پچھلے نالج کا، اور اس میں آپ نے بچوں کو انگیج کرنا ہے، خود نہیں بتانا کہ آج کل ہم نے یہ پڑھا تھا۔ آپ نے بچوں کو ری کال کروانا ہے، بیٹا آپس میں ڈسکس کر لیں، یو ہیو ٹو منٹس، میں پوچھوں گی کہ۔ | میں ایسے ہی کرتی ہوں کہ پہلے بچوں کو میں نے بتایا تھا کہ کل ہم نے، انہوں نے بتایا کہ یہ پڑھا ہے، اس کے بارے میں پہلے میں نے تھوڑا سا بتایا، پھر بچوں سے پوچھا۔ یعنی کہ میں نے نہیں بتانا، بچوں سے ہی پوچھنا ہے۔", "quote_en": "Teacher: You have told me everything. | Coach: Did you understand? Any problem? First, in prior knowledge you should not tell them yourself. I'll write it up and message you in detail. In the opening you ask about yesterday's learning and you engage the children; you make them recall: 'Children, discuss with each other, you have two minutes, I will ask...' | Teacher: That's how I do it: I told them a little first, then asked. So I should not tell, I should ask the children.", "why": "After about seven minutes of explanation the teacher says 'you have told me everything'. The coach checks with a yes/no question and promises a text message, so the teacher leaves without ever saying the new opening aloud, even though the coach has just given the exact words.", "better_move": "Stop adding content and practise one piece. 'Let's take just one thing for tomorrow: the opening. Say to me exactly what you will say to the children in the first two minutes, as if I am the class.' After the attempt: 'Good. This time add: talk to your partner for one minute, then I will ask any pair. Try it once more.'", "better_move_local": "چلیں، کل کے لیے صرف ایک چیز لیتے ہیں: اوپننگ۔ کل پہلے دو منٹ میں بچوں سے جو کہنا ہے، وہ مجھے بالکل ویسے ہی بول کر سنائیں، سمجھیں میں کلاس ہوں۔ ... بہت اچھا۔ اب اس میں یہ شامل کریں: 'ایک منٹ اپنے ساتھی سے بات کریں، پھر کسی بھی جوڑی سے پوچھا جائے گا۔' ایک دفعہ اور کر کے دکھائیں۔", "lang": "ur", "rtl": true}, {"key": "d3b3f8ec29a_ict1_09", "file": "clips/d3b3f8ec29a_ict1_09.mp3", "dur": 28.0, "kind": "missed_opportunity", "dimension": "tone_and_psychological_safety", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 11", "title": "A real constraint answered with 'ji, ji, ji'", "quote_original": "میم، وہ آپ صحیح کہہ رہی ہیں۔ میں نے فالو کیا ہے، لیکن وہ آگے پیچھے ہو گیا ہے۔ | ہاں، وہ آگے پیچھے ہو گیا ہے۔ | آگے پیچھے ہو گیا ہے، جیسے آپ بتا رہی ہیں نا۔ | جی، جی، جی۔ | سیم اسی طرح میں نے اس کو کیا ضرور ہے۔ | جی، جی، جی۔ | لیکن میم، وہ یقین کریں کہ مٹیریل ہمارے پاس ہوتا ہے اتنا زیادہ، اور آپ کا یہ جو سٹرکچر آپ لوگوں نے دیا ہے نا، یہ بہت اچھا ہے۔ | جی، جی، جی۔ | لیکن اس کو ذرا تھوڑا سا آپ یہ ہے کہ ذرا ایک دو دفعہ بندہ پہلے بھی کر لے نا، تو وہ اور زیادہ اچھا پریزنٹ ہو جاتا ہوتا ہے۔", "quote_en": "Teacher: You're right, ma'am. I did follow it, but it got out of order. | Coach: Yes, it got out of order. | Teacher: ...I did do it that way. | Coach: Yes, yes, yes. | Teacher: But believe me, we have so much material, and this structure you gave is very good. | Coach: Yes, yes, yes. | Teacher: But if one could try it once or twice beforehand, it would come out much better.", "why": "This follows a three-minute coach monologue that also mentioned scoring. The teacher names a real constraint (too much material) and even asks to practise the structure first, which is an invitation to rehearse. The coach answers only 'ji, ji, ji' and the debrief ends on 'inshallah'.", "better_move": "Treat the constraint as the problem to solve together. 'Thank you for saying that; many teachers feel there is too much material. Which part was hardest to fit in today? ... Let's take tomorrow's lesson and decide together which one activity comes first. Tell me how you will start it, as if I'm the class.'", "better_move_local": "شکریہ کہ آپ نے یہ بتایا، بہت سی ٹیچرز کو مٹیریل زیادہ لگتا ہے۔ آج کون سا حصہ فٹ کرنا سب سے مشکل لگا؟ ... چلیں کل کا لیسن لیتے ہیں اور مل کر طے کرتے ہیں کہ کون سی ایک ایکٹیویٹی پہلے آئے گی۔ اس کی شروعات کیسے ہوگی، مجھے بول کر بتائیں، سمجھیں میں کلاس ہوں۔", "lang": "ur", "rtl": true}, {"key": "de133d1b8d0_ict1_10", "file": "clips/de133d1b8d0_ict1_10.mp3", "dur": 23.6, "kind": "missed_opportunity", "dimension": "concrete_action_step", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 01", "title": "'More engagement' never becomes a move", "quote_original": "نہیں، تو اس کے لیے آپ کی کیا سٹریٹیجی ہو سکتی ہے نیکسٹ ٹائم، جب کوئی نیکسٹ ٹائم آبزرویشن کے لیے آئے؟ | ہاں، مطلب یہ ہے کہ بچوں پہ بھی نظر ہو، بندہ چلو پڑھائے ساتھ ساتھ بچوں پہ بھی نظر ہو، بچوں کو بات۔ میں نے کوشش میں نے کی ہے کہ کوئی بچہ مطلب ساروں کو میں نگرانی میں دیکھوں۔ | نہیں، ڈسپلن وائز وہ بہت اچھے بیٹھے تھے، لیکن میں چاہتا ہوں کہ تھوڑا سا نا اس میں انگیجمنٹ ہو، آپ کے ساتھ انگیج ہو۔ | اور کچھ اور، مطلب بچوں کو انٹرسٹنگ، انٹرسٹنگ چیزیں نیکسٹ ٹائم دیکھیں گے، کوئی اور انٹرسٹنگ۔", "quote_en": "Coach: So what could your strategy be next time, when someone comes to observe? | Teacher: I mean, keep an eye on the children while teaching; I've tried to watch all of them. | Coach: No, discipline-wise they sat very well, but I want a bit more engagement, for them to engage with you. | Teacher: And something else, more interesting things for the children, we'll see next time.", "why": "The question is open, but 'engagement' stays abstract: the teacher hears it as discipline, then as 'more interesting things'. The coach never points to the moment the coach saw (students silent while the teacher read fast), so no observable step emerges. Note too that the step is framed for 'next observation', not for the children.", "better_move": "Anchor it in one moment and one move. 'When you finished the second paragraph, the children were sitting silently. What is one question you could ask right there? ... Good. Now ask it to me the way you'd ask the class, then add: tell your partner first. That's the one thing I'll look for on my next visit.'", "better_move_local": "جب دوسرا پیراگراف ختم ہوا تو بچے خاموش بیٹھے تھے۔ وہاں کون سا ایک سوال پوچھا جا سکتا ہے؟ ... اچھا، اب وہ سوال مجھ سے ویسے پوچھیں جیسے کلاس سے پوچھا جاتا ہے، اور ساتھ کہیں: 'پہلے اپنے ساتھی کو بتائیں۔' اگلے وزٹ پر صرف یہی ایک چیز دیکھی جائے گی۔", "lang": "ur", "rtl": true}, {"key": "d72e4a3d79b_ict1_11", "file": "clips/d72e4a3d79b_ict1_11.mp3", "dur": 30.3, "kind": "missed_opportunity", "dimension": "focus_on_one_growth_area", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 32", "title": "All praise, no growth area", "quote_original": "صحیح۔ آپ کی جو lesson delivery ہے، وہ بہت اچھی ہے۔ آپ کی explanation بہت اچھی ہے، اور آپ پوری کلاس کو engage کرتی ہیں اپنے ساتھ، اور ساتھ میں ان کو لے کے چلتی ہیں۔ کوشش آپ کی یہی ہوتی ہے کہ بچہ جو ہے وہ اس چیز کو سمجھ جائے۔ اور دوسرا یہ چیز کہ effort آپ کی طرف سے بہت زیادہ تھی، یہ آج دیکھنے کو ملا ہے۔ | بہت شکریہ۔ | آپ کی، بہت شکریہ۔ جی بالکل، بالکل ایسا ہی ہے۔ اور ہم امید کرتے ہیں کہ آنے والے وقتوں میں ہم اس چیز کو اور مزید اچھے سے اچھا ہوتے ہوئے دیکھیں۔", "quote_en": "Coach: Right. Your lesson delivery is very good, your explanation is very good, and you engage the whole class and take them along. You try to make sure every child understands. And your effort today was a lot. | Teacher: Thank you very much. | Coach: Thank you. Yes, exactly. And we hope that in the coming times we'll see this get better and better.", "why": "The lowest-scoring conversation with a teacher present (22). The close is generic praise and a hope for improvement: no growth area, no step, no follow-up. The teacher had described pair work and merging two lessons, either of which could have become the focus.", "better_move": "Keep the praise, then choose one thing to grow. 'Your explanation kept everyone with you. Now let's pick one thing to build on. In the anagram pair work, how many pairs got to share their word? ... What could you do so more pairs share next time? Let's agree that one step, and I'll look for it on my next visit.'", "better_move_local": "آپ کی ایکسپلینیشن نے سب کو ساتھ رکھا۔ اب ایک چیز چنتے ہیں جس پر آگے کام کریں۔ اینگرام والے پیئر ورک میں کتنی جوڑیوں کو اپنا لفظ بتانے کا موقع ملا؟ ... اگلی دفعہ زیادہ جوڑیوں کو موقع ملے، اس کے لیے کیا کیا جا سکتا ہے؟ یہی ایک قدم طے کر لیتے ہیں، اگلے وزٹ پر یہی دیکھا جائے گا۔", "lang": "ur", "rtl": true}, {"key": "d5d0fb78f66_ict1_12", "file": "clips/d5d0fb78f66_ict1_12.mp3", "dur": 39.2, "kind": "missed_opportunity", "dimension": "purpose_and_relationship_opening", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 44", "title": "The visit explained as a recording check", "quote_original": "نہیں نہیں، نہیں، آپ کانشیس نہ ہوں۔ ابھی میں آپ کو نا explain کرتا ہوں، ٹھیک ہے؟ ہم basically نا یہ observations کا مقصد یہ ہوتا ہے نا کہ جب آپ لوگ نا اپنی ڈی سی کرتے ہیں، اور جب آپ لوگ اپنی recordings کو دیکھتے ہیں، تو ہم یہ چیک کرتے ہیں کہ میری presence میں اگر کوئی recording غلط ہو گئی تو میں اس کو back end میں جا کے اس کو re- تو اس سے یہ ہوتا ہے، وہ re-calibrate ہوتا ہے۔ Let's suppose recording میں کوئی چیز آئی، but I saw it کہ آپ نے اس میں غلطی کی، ٹھیک ہے؟ So then I go back، اور میں اسے کہتا ہوں، ہاں، یہ وہی ہے، اور میں اس کا evidence دیتا ہوں، ٹھیک ہے؟ تو اس سے نا وہ re-calibrate ہوتا ہے۔ | ہاں، لیکن میں نے تو re-calibrate کیا نہیں۔", "quote_en": "Coach: No, no, don't be self-conscious. Let me explain. The purpose of these observations is that when you do your recordings, we check: if a recording came out wrong in my presence, I go to the back end and re-calibrate it. Suppose something in the recording showed you made a mistake; I saw it, I go back and give the evidence, and it gets re-calibrated. | Teacher: Yes, but I didn't re-calibrate anything.", "why": "The teacher opens worried that the class was below their usual energy. The coach reassures, then explains the visit as checking and correcting recordings, with talk of 'mistakes' and 'evidence'. The teacher's reply shows they still do not know what the visit is for. The rest of the debrief has no coach questions at all.", "better_move": "Frame the visit as help, then hand over. 'Don't worry, this visit isn't to check you or the recording. I'm here to help with your teaching. You said the energy felt lower today; what felt different to you? ... Is there one thing you'd like us to work on together?'", "better_move_local": "پریشان نہ ہوں، یہ وزٹ آپ کو یا ریکارڈنگ کو چیک کرنے کے لیے نہیں ہے، یہ آپ کی ٹیچنگ میں مدد کے لیے ہے۔ آپ نے کہا آج انرجی کم لگی، آپ کو کیا مختلف لگا؟ ... کیا کوئی ایک چیز ہے جس پر ہم مل کر کام کریں؟", "lang": "ur", "rtl": true}, {"key": "ddd30cf3389_ict1_13", "file": "clips/ddd30cf3389_ict1_13.mp3", "dur": 32.5, "kind": "missed_opportunity", "dimension": "coach_questioning_and_dialogue", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 45", "title": "The coach diagnoses instead of asking", "quote_original": "بالکل۔ سو جیسے جو بھی ڈیسیملز کے ورڈ پرابلمز تھے، اس میں بچوں کا جو کنسیپٹ تھا کہ مائنس کیسے آیا، یہ کون سی، کیوں سبجیکٹ کا کوئسچن ہے، یہ کیوں ملٹی پلائی کا کوئسچن ہے، ان سے بار بار آپ پوچھیں کہ اس میں کی ورڈ آپ نے کیا ہے آپ کا، کہ آپ اس پہ پتہ چل رہا ہے۔ ٹھیک ہے؟ آپ خود بتا رہی تھیں، آپ سارا کچھ بہت زیادہ، مطلب، لائک، بچوں کو بتا رہی تھیں، لیکن بہت زیادہ ٹیچر بیسڈ کلاس روم لگ رہی تھی۔ اس میں سٹوڈنٹ کا ان پٹ اتنا اس طرح سے نہیں تھا کہ وہ... اگر آپ ان سے یہ سارے کوئسچن، اگر آپ ان سے بورڈ پہ خود کرواتی نا، کہ بچے سٹیٹمنٹ بھی خود لکھتے، بچے اس کو سولو بھی خود کرتے، تو وہ زیادہ بہتر ہو جاتا۔ مجھے ایسا لگتا ہے۔", "quote_en": "Coach: Right. In the decimal word problems, the children's idea of why it's a subtraction question or a multiplication question: keep asking them what the key word is. You were telling the children everything; it felt like a very teacher-based classroom, with little student input. If you had them do these questions on the board, write the statement and solve it themselves, it would be better. That's how it seems to me.", "why": "The coach delivers the verdict ('a very teacher-based classroom') before asking the teacher who was doing the thinking. The teacher's next turns are a list of justifications (syllabus not covered, children are new to mixed problems), and the debrief ends on 'okay'.", "better_move": "Let the teacher see it first, then make it small. 'During the word problems, who was doing most of the talking and thinking, you or the children? ... Which one problem tomorrow could a child write and solve at the board, while you only ask: what is the key word here?'", "better_move_local": "ورڈ پرابلمز کے دوران زیادہ بات اور سوچ کون کر رہا تھا، آپ یا بچے؟ ... کل کا کون سا ایک سوال ایسا ہے جو کوئی بچہ بورڈ پر خود لکھ کر حل کرے، اور آپ صرف یہ پوچھیں کہ 'اس میں کی ورڈ کیا ہے؟'", "lang": "ur", "rtl": true}, {"key": "d720d42bf45_ict1_14", "file": "clips/d720d42bf45_ict1_14.mp3", "dur": 17.2, "kind": "missed_opportunity", "dimension": "commitment_and_follow_up", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 06", "title": "'You must do this next time', then goodbye", "quote_original": "اپنا۔ ٹھیک ہے؟ سو اس کو آپ نے ضرور نیکسٹ ٹائم رکھنا ہے۔ صحیح؟ اور ابھی ریکارڈنگ میں آپ کو بھیج دیتی ہوں، آپ اس کو اپلوڈ کر دیں۔ ٹھیک ہے میم؟ پھر ملتی ہیں۔ کچھ، کچھ کہا تو نہیں ہے نا؟ صحیح ہے؟ بہت شکریہ۔", "quote_en": "Coach: Your own. Okay? So you must keep this next time. Right? And I'll send you the recording now; you upload it. Okay, ma'am? See you. I haven't said anything wrong, have I? Right? Thank you very much.", "why": "The step (one pair question in guided practice before independent work) was clear, but the close is an instruction plus an upload request. The teacher never says what they will do or when, and there is no date for the coach to see it.", "better_move": "Close by having the teacher say the step back with a when. 'Before we finish, tell me in your own words what you'll do in your next addition lesson after the explanation, and in which period. ... Good. I'll come on Thursday and we'll look at just that part together.'", "better_move_local": "ختم کرنے سے پہلے، آپ اپنے الفاظ میں بتائیں کہ اگلے ایڈیشن کے لیسن میں ایکسپلینیشن کے بعد کیا کیا جائے گا، اور کون سے پیریڈ میں؟ ... بہت اچھا۔ جمعرات کو دوبارہ ملاقات ہوگی اور ہم مل کر صرف وہی حصہ دیکھیں گے۔", "lang": "ur", "rtl": true}, {"key": "d413807a09a_ict1_15", "file": "clips/d413807a09a_ict1_15.mp3", "dur": 25.8, "kind": "missed_opportunity", "dimension": "concrete_action_step", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 63", "title": "Teacher's own fix passed over for 'what else?'", "quote_original": "اس کو پھر یہ ہوگا کہ مجھے تھوڑا سا، جو مطلب، ٹائم، مجھے باقاعدہ موبائل پر دیکھنا چاہیے، ساتھ ساتھ۔ ہر سٹیپ کے لیے مجھے ٹائم نوٹ کرنا چاہیے کہ میں نے جتنا ٹائم، آہ، آپ کے لیسن پلان میں دکھایا جاتا ہے نا، اسی حساب سے مجھے ٹائم جو ہے وہ دیکھ کے، موبائل سے، تو پھر ٹائم کے حساب سے چلنا چاہیے۔ تب ہی شاید ایسا پرفیکٹلی ہو سکے۔ | ہاں، ٹائم کو ٹریک کریں۔ اور اس کے علاوہ آپ کیا کر سکتی ہیں؟", "quote_en": "Teacher: Then I should properly watch the time on my phone as I go. For each step I should note the time given in the lesson plan and go by that, watching the phone. Only then can it work perfectly. | Coach: Yes, track the time. And apart from that, what else can you do?", "why": "The teacher has just designed a concrete, teacher-owned step for the problem they named (rushed endings). Instead of firming it up, the coach asks for more ideas, and the conversation drifts to home support; the step is never made specific or rehearsed.", "better_move": "Lock in the teacher's idea before asking for anything else. 'That's a clear step. Which part of tomorrow's lesson will you time first? And when the minutes are up, what will you say to the class? Say it to me now.'", "better_move_local": "یہ بہت واضح قدم ہے۔ کل کے لیسن کا کون سا حصہ سب سے پہلے ٹائم کیا جائے گا؟ اور جب منٹ پورے ہو جائیں تو کلاس سے کیا کہا جائے گا؟ ابھی مجھے بول کر سنائیں۔", "lang": "ur", "rtl": true}, {"key": "d5855ef4529_ict2_00", "file": "clips/d5855ef4529_ict2_00.mp3", "dur": 43.1, "kind": "strength", "dimension": "concrete_action_step", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 12", "title": "Teacher chooses where the new question goes", "quote_original": "کوچ: جی۔ تو وہ پھر تھوڑا سا lesson سے ہٹ کے بھی ہو سکتا ہے۔ وہ آپ کی اپنی creativity ہے، teacher کس جگہ پہ اس کو use کرنا چاہے، کیوں اور کیسے کے سوالات ہم ان کو add کر سکتے ہیں۔ تو ma'am، ایسا کر سکتے ہیں؟ اگر next class اگر آپ کی کوئی بھی ہوتی ہے، اسی topic کی ہوتی ہے، تو آپ کیا سمجھتی ہیں، کہاں پر آپ اس طرح کے سوالات pinch کر سکتے ہیں؟ کوئی ایسی جگہ، کوئی شروع میں، درمیان میں، آخر میں، یا کہاں پر؟ Independent work کے دوران۔ ٹیچر: اسی پہ، اسی اسی طرح کے topic پہ، یا like— جیسے ابھی میں نے ایک reading کرانی ہے۔ کوچ: جی، reading کرانی ہے۔ ٹیچر: بچوں کو reading کراتے ہوئے پھر میں کوئی سا بھی ان کو ایک paragraph، دو چار لائن کا دوں گی، اور وہ بچہ read کر رہا ہے۔ کوچ: جی۔ ٹیچر: تو میں اس سے یہی پوچھوں گی کہ ہاں بتائیں کہ اس میں یہ والا sentence کیوں آیا۔", "quote_en": "Coach: That can go a little beyond the lesson too; it's your own creativity where you use it. So, ma'am, can we do this? In your next class on this topic, where do you think you could slip in questions like this? At the start, in the middle, at the end, or where? During independent work? Teacher: On the same kind of topic, or like, I have a reading coming up. Coach: Yes, a reading. Teacher: While doing the reading I'll give them a paragraph of two to four lines, and a child is reading. Coach: Yes. Teacher: Then I'll ask: 'Tell me, why did this sentence come here?'", "why": "Instead of telling, the coach asks where the teacher will use the 'why/how' question. The teacher picks the lesson (the next reading), the moment (after a child reads a short paragraph) and the exact words. That is a co-built, observable step, the only one in the group to score 3.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "d65cbfdfbce_ict2_01", "file": "clips/d65cbfdfbce_ict2_01.mp3", "dur": 35.1, "kind": "strength", "dimension": "evidence_from_the_lesson", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 37", "title": "Praise that names what children did", "quote_original": "کوچ: بالکل، بہت فرق آیا تھا۔ جو رونگ آنسرز ایکسپلینیشن کے ٹائم پہ ہمیں نظر آ رہے تھے، وہ جب آپ نے جی پی کو ڈی بریف کرنا شروع کیا، وہ وہاں پہ بہت چیزیں ٹھیک ہو گئیں۔ کیونکہ وہی بات کہ بچے آپس میں ہی ایک دوسرے کی غلطیاں، جو آپ سے شاید نہیں سیکھ پائے تھے، وہ انہوں نے ایک دوسرے کو خود سکھا دیا۔ تو وہ جی پی بہت بہترین تھی، بہت بہترین۔ 4 منٹ، آپ نے باری باری ہر گروپ کو آگے بلایا، انسٹرکشنز کلئیر تھے، کوئی کلاس روم میں شور نہیں ہوا۔ یا جب بچے بات کر رہے تھے، ان کے اوپر سے ٹیچر کی ایک اور آواز نہیں گونج رہی تھی۔ بہت اچھا تھا جی پی کہ بچوں نے آبزرو کیا، بچے واپس جا کے بیٹھے۔", "quote_en": "Coach: Exactly, it made a big difference. The wrong answers we saw during the explanation got fixed when you debriefed the guided practice, because the children taught each other the mistakes they perhaps hadn't learned from you. That guided practice was excellent. Four minutes; you called each group up in turn, the instructions were clear, there was no noise, and when the children were talking there wasn't a second teacher voice over them. The children watched, and went back and sat down.", "why": "One listen shows what specific praise sounds like: a timed moment (four minutes), what the teacher did (called groups in turn, kept quiet while children talked), what the children did (corrected each other's wrong answers), and why it mattered for learning.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "d3468c0b054_ict2_02", "file": "clips/d3468c0b054_ict2_02.mp3", "dur": 38.4, "kind": "strength", "dimension": "teacher_self_reflection", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 24", "title": "Teacher sorts their own questions", "quote_original": "کوچ: ٹھیک۔ ایک ہی چیز۔ اچھا، آپ نے وہ آئی فیلڈ کہ تھی، کہ آپ نے ذرا رش میں نہیں کیا، it's a— that was a smooth transition everywhere. آپ نے کوئسچننگ کی، لیکن آپ کو لگتا ہے آپ نے اوپن اینڈڈ کوئسچننگ کی؟ ٹیچر: ایک میں نے کیا تھا، I guess کہ اگر، فار ایگزیمپل، اگر ایک ایگزیمپل ہے جو بالکل رینڈم سی ہے، جیسے میں نے کہا تھا 'Is Lahore smaller than Rawalpur?' تو اگر آپ کو سمالر لاہور ہے تو آپ اس کو کیسے گیس کریں گی؟ اور آپ کو کیا، آپ کو ڈفرینشی ایشن کا پوائنٹ کیسے پتہ چلے گا کہ یہاں پہ کمپیریٹیو نہیں یوز ہونا چاہیے؟ I think that was an open-ended question. کوچ: اچھا۔ ٹیچر: لیکن ایڈجیکٹو کا جو میں نے ڈیفینیشن پوچھی تھی، that was a closed-ended question.", "quote_en": "Coach: Fine, just the one thing. You said you weren't rushed; it was a smooth transition everywhere. You did questioning, but do you think you did open-ended questioning? Teacher: I did one, I guess. For example the random one, when I asked 'Is Lahore smaller than Rawalpindi?': if Lahore is smaller, how would you work it out, and how would you know the comparative shouldn't be used here? I think that was an open-ended question. Coach: Okay. Teacher: But when I asked for the definition of an adjective, that was a closed-ended question.", "why": "Rather than announcing 'your questions were closed', the coach asks the teacher to judge their own questioning. The teacher correctly separates an open question from a closed one with their own examples, so the growth area (more open questions) comes from the teacher.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "d70820c0dce_ict2_03", "file": "clips/d70820c0dce_ict2_03.mp3", "dur": 32.8, "kind": "strength", "dimension": "coach_questioning_and_dialogue", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 42", "title": "A 'why' question turns self-blame into analysis", "quote_original": "کوچ: اچھا میم، اس کی آپ کو جو بچے distract ہو رہے تھے، اس کی آپ کو کیا وجہ لگی؟ آپ کو کیا لگتا ہے کہ کیوں ہو رہے تھے؟ ٹیچر: سر، میں ٹھیک سے ہی نہیں پڑھا رہی تھی۔ کوچ: نہیں، آپ— میں نے وہ، وہ بات میں نے پہلے کر لی کہ آپ اچھا پڑھا رہے تھے۔ مطلب، جو آپ کی teaching والا part تھا، وہ اچھا تھا۔ اچھا— ٹیچر: کچھ بچے ہیں، کچھ ایسے ہیں کہ جن کو پہلی دفعہ میری بات سمجھ آ گئی، اور انہوں نے پھر جب اس کے بعد میں اس کو دوبارہ سے بتا رہی تھی تو وہ، وہ لوگ زیادہ وہ ہو رہے تھے کہ ان کو پہلے سے بات، وہ بات پہلے سے پتا تھی۔ لیکن کچھ بچے ایسے ہیں جن کو end تک بھی وہ نہیں سمجھ آ رہی تھی۔", "quote_en": "Coach: Ma'am, the children who were getting distracted: what do you think was the reason? Why do you think it was happening? Teacher: Sir, I wasn't teaching properly. Coach: No, I already said you were teaching well; the teaching part was good. Teacher: Some children understood me the first time, so when I explained it again they got restless because they already knew it. But some children still didn't understand it by the end.", "why": "The teacher's first reaction is to blame themselves. The coach removes the blame in one sentence and holds the question open, and the teacher then analyses two groups of learners. This is the kind of thinking the rest of the debrief can build on.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "df6a74a38f2_ict2_04", "file": "clips/df6a74a38f2_ict2_04.mp3", "dur": 44.0, "kind": "strength", "dimension": "practice_or_modelling", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 01", "title": "Coach says the class instructions aloud", "quote_original": "کوچ: اب اس کے بعد آپ آتی ہیں گروپ ورک پہ، یا گائیڈڈ پریکٹس پہ۔ اس میں ہم بچوں کو یہ کہتے ہیں کہ اچھا بچوں، اب ہم 8 منٹ کی یا 5، آپ سپیسیفکلی بتاتے ہیں ٹائمنگ کہ ہم 5 منٹ کی ایک ایکٹیویٹی کر رہے ہیں، جس کو ہم گروپ ورک کہتے ہیں یا جی پی کہتے ہیں، جو بھی آپ ان کو نام دے دیں۔ ٹھیک ہے؟ ٹیچر: جی۔ کوچ: اب آپ نے بیٹا یہ کرنا ہے کہ جو گروپ اے ہیں، وہ سارے ایک ساتھ ملے، مل کے بیٹھیں۔ جو گروپ بی ہیں، اینڈ دین سی ہیں، جتنے بھی آپ کے گروپس بنتے ہیں۔ آپ کی آسانی کے لیے، میم، آپ ایسا کریں کہ جو بچہ جس کے ساتھ بیٹھا ہے، بس وہ گروپ ہے۔ ٹیچر: وہ ٹھیک ہے۔ کوچ: دو دو بیٹھے ہیں، تین تین بیٹھے ہیں، وہ پیئر بن جائے گی، گروپ بن جائے گا۔ آپ ان کو بولیں کہ اب میں یہ سوال لکھ رہی ہوں، آپ لوگوں نے مل کے کرنا ہے۔ ایک دوسرے سے پوچھیں گے، یا مجھ سے پوچھیں گے، یا بورڈ سے بھی دیکھ سکتے ہیں، کتاب سے بھی دیکھ سکتے ہیں۔", "quote_en": "Coach: After that you come to group work, or guided practice. We tell the children: 'Okay children, now we'll do an activity', and you say the time exactly, 'a five-minute activity, which we call group work or GP', whatever you call it. Okay? Teacher: Yes. Coach: 'Now, children, group A sits together, group B, and then C', however many groups you have. To make it easy, ma'am, whoever a child is sitting with, that's the group. Teacher: That's fine. Coach: Two sitting together, three sitting together, that's a pair or a group. Tell them: 'Now I'm writing this question and you'll do it together. Ask each other, or ask me, or look at the board or the book.'", "why": "The coach switches into classroom voice and gives the teacher the exact words: the time limit, how to group children without moving desks, and where they can get help. It is a model the teacher can copy tomorrow. The missing step, which almost every debrief misses, is asking the teacher to say it back.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "d07da2c378b_ict2_05", "file": "clips/d07da2c378b_ict2_05.mp3", "dur": 42.8, "kind": "strength", "dimension": "commitment_and_follow_up", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 55", "title": "Teacher says the plan in their own words", "quote_original": "کوچ: اس میں ہم نے کیا چیز آپ سے ڈسکشن کی ہے کہ ہم کیا کریں گے نیکسٹ ٹائم میں؟ ٹیچر: نیکسٹ ٹائم میں یہ ہے کہ ہم نے پیئر ورک جو ہے وہ لازمی کروانا ہے، بچوں کے گروپس بنانے ہیں، اور گروپ میں بچوں کو کام کروانا ہے۔ اور دوسرا، تمام بچے جو ہیں انوالو ہوں، اور ہر بچہ انڈیویجولی اپنا کام کر کے جو ہے وہ دکھائے۔ اور انڈیویجولی کام کرے۔ 15 منٹس کا ہم انہیں—ہم بول کے ان کو بتائیں، اور 15 منٹس کے بچے جو ہیں وہ خود کام کریں، اور وہ ہمارے ساتھ شیئر کریں اپنا کام۔ کوچ: بالکل، بالکل۔ ٹیچر: ہاں جی۔ کوچ: ٹھیک ہے، اس سے یہ ہوگا کہ ہم چھوٹی سی اسیسمنٹ لے سکیں گے کہ آیا جو بچے—جس طرح کوئی بالکل نہیں رسپانس کر پائے، یا جن کو سمجھ نہیں آئے—تو ہم ایک چھوٹی سی ایک طرح سے جانچ پاتے ہیں کہ ابھی کس بچے کو ہماری بہت زیادہ توجہ کی ضرورت ہے۔", "quote_en": "Coach: So what did we discuss that we'll do next time? Teacher: Next time we must do pair work, make groups and have the children work in groups. Second, all children should be involved, and every child should do their own work individually and show it. We talk for 15 minutes, and for 15 minutes the children work themselves and share their work with us. Coach: Exactly, exactly. Teacher: Yes. Coach: Right. That way we can do a small check of which children couldn't respond at all or didn't understand, and see which child needs most of our attention.", "why": "One of only 6 of 64 debriefs where the teacher restates the step themselves, with a concrete time split (15 minutes of talk, 15 of student work). The coach then gives the reason. Adding a day and a follow-up check would make it complete.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "d8f0bcd3c2c_ict2_06", "file": "clips/d8f0bcd3c2c_ict2_06.mp3", "dur": 32.8, "kind": "strength", "dimension": "tone_and_psychological_safety", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 27", "title": "Accepting a resource gap, offering a workaround", "quote_original": "کوچ: بالکل، وہ ٹچ کرنے کے لیے۔ اور سم ٹائمز اگر نہیں بھی ہو تو ہم پکچرز کے تھرو بچوں کو دکھا سکتے ہیں۔ ٹیچر: پکچرز کے تھرو۔ میں ان شاء اللہ نیکسٹ ویک کوشش کروں گی کہ اگر میں کوئی اس طرح کا ہوں تو اپنے پاس کوئی ایسی پکچر رکھوں، انور کر کے رکھوں۔ کوچ: ہاں، وہ پھر آپ بے شک فون میں دکھا دیں ان کو۔ ٹھیک ہے، تو وہ دیکھ کے آپ کو ریسپانڈ کر سکتے ہیں۔ مطلب، آئی انڈرسٹینڈ، ریسورسز کا مسئلہ ہوتا ہے۔ بعض اوقات آپ نہیں آ سکتے۔ جیسے ڈو یا اس طرح کی چیزیں، وہ بندہ لانے میں کبھی کبھار مسائل ہوتے ہیں۔ تو دیٹ آئی انڈرسٹینڈ۔ بس وہ بچوں کو پکچرز دکھا دیں، فنگس سے ریلیٹڈ، وہ لگا ہوا ہے، وہ بریڈ کے اوپر لگا ہوا ہے، اس طرح کی کوئی تصاویر ہوں۔", "quote_en": "Coach: Exactly, for touching. And sometimes, if you don't have the material, we can show the children pictures. Teacher: Through pictures. God willing, next week I'll try to keep a picture like that with me. Coach: Yes, you can even show it on your phone, and they can respond to it. I understand there's a resource problem; sometimes you can't bring things like dough. I understand that. Just show them pictures of fungus, like the fungus on bread.", "why": "The teacher raises missing materials. The coach takes the constraint seriously ('I understand'), offers a fix that needs no new resources (a picture on the phone), and the teacher commits to it for next week in their own words.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "d6a5fc2923b_ict2_07", "file": "clips/d6a5fc2923b_ict2_07.mp3", "dur": 30.3, "kind": "strength", "dimension": "focus_on_one_growth_area", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 47", "title": "One small thing, and why it matters", "quote_original": "کوچ: ہاں۔ میں بس آپ کو ایک چیز پہ ڈائریکشن دوں گی، ضرور۔ ہے، بہت چھوٹی سی چیز، لیکن ضروری ہے۔ کہ جیسے ابھی بورڈ ہے نا، اس کے اوپر ابھی لکھا ہے آپ نے، لیکن وہ پراپرلی وزیبل بھی نہیں ہے۔ تو میم، پراپر ٹاپک کا ایس ایل او، یعنی آج ہم یہ پڑھیں گے، اور اس میں آپ لکھیں کہ ہم ریڈنگ پڑھیں گے۔ ایک یہ چیز۔ دوسرا یہ کہ جو مشکل الفاظ ہوتے ہیں نا، ایٹ لیسٹ وہ بورڈ پہ ضرور لکھیے گا۔ ٹیچر: صحیح، صحیح۔ کوچ: اس سے یہ ہوتا ہے کہ بچے ہیں، چھوٹے ہیں، ان کا فوکس ادھر ادھر ہو جاتا ہے، لیکن جب وہ بورڈ پہ— ہاں، دیکھتے رہیں گے تو ان کو یاد آئے گا۔", "quote_en": "Coach: Yes. I'll give you direction on just one thing. It's a very small thing, but important. The board: you have written on it, but it isn't properly visible. So, ma'am, write the topic's SLO properly, 'today we will read this'. That's one part. The other: at least write the difficult words on the board. Teacher: Right, right. Coach: Because they're small children and their focus wanders, but if they can keep looking at the board, they'll remember.", "why": "The coach explicitly narrows the conversation to one small, visible change (topic and hard words clearly on the board) and gives the reason in terms of the children. It shows what prioritising sounds like, in a group where 17 of 64 debriefs raised three or more areas.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "ddb14c50340_ict2_08", "file": "clips/ddb14c50340_ict2_08.mp3", "dur": 37.6, "kind": "missed_opportunity", "dimension": "focus_on_one_growth_area", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 11", "title": "A fifth fix in the last thirty seconds", "quote_original": "کوچ: نہیں نہیں، میں یہاں کر رہی ہوں، پھر اس کے اوپر فارم فل ہوگا، مگر وہ فارم میں ایڈٹ کروں گی۔ اس طرح نہیں کہ وہ میں ایڈٹ نہیں کروں گی، مگر کوشش کریں کہ وہ چیز ہو جائے۔ اور جب انڈیپینڈنٹ پریکٹس میں بچے اسٹرگل کر رہے تھے، تو پھر وہاں پہ ایک پوائنٹ مجھے لگا کہ آپ نے وہ صحیح طریقے سے پھر بچوں کو وہ سولو نہیں ہوا۔ بچے بھی کنفیوز رہے، انڈیپینڈنٹ پریکٹس میں بھی اور ایگزٹ ٹکٹس میں بھی۔ کچھ بچوں نے غلط ہی کیا تھا، اور کچھ بچوں نے وہ کیا تھا، تو وہ کریکشن نہیں ہوئی وہاں پہ۔ تو وہ ایک اور بات مجھے—کوشش کریں اگلے اس میں آپ نے وہ کر لیں۔ چلیں، تھینک یو سو مچ۔", "quote_en": "Coach: No, no, I'm doing it here, then the form will be filled in, but I'll edit it on the form. Not that I won't edit it, but try to make that happen. And when the children were struggling in independent practice, I felt you didn't get them to solve it properly. The children stayed confused, in independent practice and in the exit tickets. Some had done it wrong, some had done it right, and the correction didn't happen there. So that's one more thing: try to do it next time. Okay, thank you so much.", "why": "This comes after almost two minutes of uninterrupted feedback. The coach adds a fifth area (correcting mistakes), mentions the observation form, and closes. The teacher, who said 37 words in the whole debrief, leaves with five 'try to' requests and no priority.", "better_move": "Of everything I saw, let's take just one thing: fixing mistakes during independent practice. When you saw a wrong answer in a copy today, what could you have said to that child? ... Good. So next lesson, after five minutes of independent work, you check three copies and solve one wrong answer again on the board with everyone. I'll look for that on my next visit.", "better_move_local": "آج جو کچھ میں نے دیکھا، اس میں سے ہم صرف ایک چیز لیتے ہیں: انڈیپینڈنٹ پریکٹس میں غلطیوں کی درستی۔ آج جب کسی کاپی میں غلط جواب نظر آیا تو اس بچے سے کیا کہا جا سکتا تھا؟ ... بہت اچھا۔ تو اگلے سبق میں پانچ منٹ کے انڈیپینڈنٹ کام کے بعد تین کاپیاں دیکھی جائیں گی اور ایک غلط جواب بورڈ پر سب کے ساتھ دوبارہ حل کیا جائے گا۔ اگلے وزٹ پر یہی دیکھا جائے گا۔", "lang": "ur", "rtl": true}, {"key": "d69d5a9cf4d_ict2_09", "file": "clips/d69d5a9cf4d_ict2_09.mp3", "dur": 33.5, "kind": "missed_opportunity", "dimension": "teacher_self_reflection", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 21", "title": "Cutting off the teacher's own mistakes", "quote_original": "ٹیچر: جی سر۔ بچوں کو اصل میں یہ ریڈنگ کر کے جو بتایا نا، سر، اس میں بھی بچوں کا ہونٹس جو ہے نا، آواز تھوڑا سا، یعنی کہ، اچھا ہوتا ہے۔ اس کے بعد جو ہے، بچوں کو دو مسٹیک ہو گئی ہیں۔ ایک جو ہے، بچوں کو ایکٹیویٹی کے لیے جو ہے نا— کوچ: سر، اس کے بعد میں آتا ہوں، کائنڈلی ابھی جو اچھی اچھی چیزیں ہیں وہ بتائیں۔ ٹیچر: ایکٹیویٹی کے لیے کوئی چیز، اسی طرح کھلونے وغیرہ ہوتا تھا، تو پھر بچوں کو دکھا کے آگے— کوچ: سر، اس پہ، سوری، فُل بیک ہو گیا۔ اس پہ بعد میں آتے ہیں۔ ابھی جسٹ یہ بتائیں کہ کیا کیا اسٹیپ اچھے لیے، جس کی بنا پہ یہ چیزیں ان کو، آہ، کانسیپٹ کلیئر ہو گیا؟ قاری اعظم کے بارے میں بہت زیادہ—", "quote_en": "Teacher: Yes sir. When I explained through the reading, the children's voices were quite good. After that, there were two mistakes. One, for the activity... Coach: Sir, I'll come to that later. Kindly tell me the good things for now. Teacher: For the activity, something like toys, to show the children and then... Coach: Sir, sorry, we've jumped back. We'll come to that later. For now, just tell me which steps went well and made the concept clear. About the Quaid, a lot...", "why": "The teacher volunteers 'there were two mistakes', which is the best possible opening for the growth area. The coach stops them twice to keep to 'good things first'. The coach never comes back to the mistakes, and later supplies an unrelated growth area of their own.", "better_move": "You said there were two mistakes. Tell me about the first one: what happened, and what did the children do at that moment? ... And what would you do differently there next time? We'll come back to what went well; I don't want to lose this.", "better_move_local": "آپ نے کہا کہ دو غلطیاں ہوئیں، پہلی والی بتائیں: کیا ہوا تھا، اور اس وقت بچوں نے کیا کیا؟ ... اگلی بار اس جگہ کیا مختلف کیا جا سکتا ہے؟ اچھی چیزوں پر بھی بات کریں گے، لیکن یہ بات چھوٹنی نہیں چاہیے۔", "lang": "ur", "rtl": true}, {"key": "d721f3c347d_ict2_10", "file": "clips/d721f3c347d_ict2_10.mp3", "dur": 33.2, "kind": "missed_opportunity", "dimension": "coach_questioning_and_dialogue", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 06", "title": "Asking 'why?' and answering it yourself", "quote_original": "کوچ: لیکن میم، میرا سوال یہ ہے کہ 30 کی کلاس میں صرف 8 بچے کیوں گروپ میں کام کر رہے ہیں؟ ٹیچر: تیسری نہیں، فورتھ کلاس تھی۔ کوچ: اوہ، تھرٹیئتھ، 30 کی کلاس۔ ٹیچر: اچھا، 30 کی۔ کوچ: ٹھیک ہے۔ اس کے اندر صرف 8 بچے گروپ کا کام کر رہے ہیں، اور مین ٹائم آپ نے باقی بچوں کو انڈیپینڈنٹ ٹاسک دیا۔ تو differentiated task at the same time ہمارے، ہمیں نہیں کرانا۔ 8 بچوں کو گروپ میں کرائیں، باقیوں کو individually کرائیں، آپ engage۔ وہ تھوڑا کلیش آف ٹاسک آ جاتا ہے نا۔ ٹھیک ہے۔ So جب آپ نے pair work کرا رہے ہیں، یا گروپ ورک کرا رہے ہیں، تو وہ ساری کلاس کے لیے گروپ ورک ہونا چاہیے۔ ٹھیک ہے؟", "quote_en": "Coach: But ma'am, my question is: why are only 8 children working in groups in a class of 30? Teacher: Not third, it was fourth class. Coach: Oh, thirty, a class of 30. Teacher: I see, 30. Coach: Okay. Only 8 children are doing group work, and meanwhile you gave the rest an independent task. We shouldn't do differentiated tasks at the same time; it becomes a clash of tasks. So when you do pair work or group work, it should be for the whole class. Okay?", "why": "The teacher had just described a thoughtful strong-with-weaker pairing and a board check. The coach asks a good 'why' question but answers it in the same breath and closes with 'okay?'. The teacher never explains the choice, and spends the rest of the debrief defending it.", "better_move": "Pairing a strong child with one who needs help, then calling the weaker child to the board, was a smart check. My question: while those four pairs worked, what were the other 22 children doing? ... (wait) ... How could that same pairing work for the whole class at once?", "better_move_local": "اچھے بچے کے ساتھ کمزور بچے کو بٹھانا اور پھر کمزور بچے کو بورڈ پر بلا کر چیک کرنا، یہ بہت سمجھداری کی بات تھی۔ میرا سوال یہ ہے: جب وہ چار جوڑیاں کام کر رہی تھیں تو باقی بائیس بچے کیا کر رہے تھے؟ ... (رکیں) ... یہی جوڑی والا طریقہ ایک ساتھ پوری کلاس کے لیے کیسے ہو سکتا ہے؟", "lang": "ur", "rtl": true}, {"key": "dab52fd2dcf_ict2_11", "file": "clips/dab52fd2dcf_ict2_11.mp3", "dur": 19.9, "kind": "missed_opportunity", "dimension": "evidence_from_the_lesson", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 16", "title": "When the teacher says 'I did do it'", "quote_original": "کوچ: آج کے ٹاپک میں آپ نے جیسے وہ پیئر ورک یا گروپ ورک نہیں کروایا۔ ٹیچر: آج کے ٹاپک میں میں نے وہ کروائے تھے، کوئسچن کروائے تھے ان کو۔ کوچ: تو وہ ان کو آپ اگر، جس طرح یہ والے جو بچے ہیں، آپ اگر اس میں کچھ سوچتی ہیں کہ جیسے پیئر ورک نہیں کروایا، آپ جیسے کہہ رہی ہیں کروانا چاہیے، آج کا جو ٹاپک ہوا ہے، تو پیئر ورک اس کو کیسے ہیلپ کرے گا، یا گروپ ورک اس کو کیسے ہیلپ کرے گا؟", "quote_en": "Coach: In today's topic you didn't do pair work or group work. Teacher: In today's topic I did do it; I gave them questions. Coach: So if, as with these children, you think that pair work wasn't done, as you say it should be, how would pair work help today's topic, or how would group work help?", "why": "The coach states a judgement without describing what was seen, and the teacher contradicts it. Instead of checking ('tell me what it looked like'), the coach repeats the claim. The feedback now rests on a disagreement neither side has evidence for, and the debrief closes on 'pair work was not done'.", "better_move": "Oh, tell me how the pair work went: what did the pairs do, and what were the children who were confused about 0.5 and 0.05 doing during it? ... What I saw from where I sat was ... So what could make the pairs help those children more?", "better_move_local": "اچھا، پیئر ورک کیسے ہوا، ذرا بتائیں: جوڑیوں نے کیا کیا، اور جو بچے 0.5 اور 0.05 میں الجھ رہے تھے وہ اس دوران کیا کر رہے تھے؟ ... جہاں سے مجھے نظر آ رہا تھا وہاں سے یہ دکھائی دیا کہ ... تو ایسا کیا ہو کہ جوڑیاں ان بچوں کی زیادہ مدد کر سکیں؟", "lang": "ur", "rtl": true}, {"key": "d28fb5b5275_ict2_12", "file": "clips/d28fb5b5275_ict2_12.mp3", "dur": 34.6, "kind": "missed_opportunity", "dimension": "concrete_action_step", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 32", "title": "'Be patient, give clear instructions'", "quote_original": "کوچ: نہیں، آپ کی لیسن کی تیاری اچھی تھی آج کی۔ اور اس طرح سے جو آپ نے پریپیئر کیا تھا، وہ آپ نے ڈیلیور کیا ہے۔ تو اچھا رہا آپ کا لیسن پلان۔ بس یہ ہے کہ تھوڑا سا ایک ہوتا ہے نا، ہسل تھی، ایک تھوڑی سی جلدی سی محسوس ہوئی۔ تو نیکسٹ ٹائم سے آپ کوشش کیجیے گا کہ جب بھی اس طرح کی کوئی کلاس ہو رہی ہو، اور ویسے بھی آپ جب نارملی پڑھا بھی رہی ہیں نا، تو تب بھی آپ تھوڑا سا نا، چیزوں کو تحمل سے لے کے چلیں، اور بچوں کو کلیئر انسٹرکشنز دیں، تاکہ بچہ جو ہے اس کو سنے اور آپ کی بات پہ توجہ دے۔ ٹھیک ہے مس؟ باقی اوور آل آپ کا اچھا رہا ہے۔ تھینک یو سو مچ فار یور ٹائم۔", "quote_en": "Coach: No, your preparation for today's lesson was good, and you delivered what you prepared, so your lesson plan went well. It's just that there was a bit of a rush; it felt a little hurried. So from next time, please try, whenever you have a class like this, and also when you're teaching normally, to take things patiently and give the children clear instructions, so the child listens and pays attention to you. Okay, miss? Otherwise overall it went well. Thank you so much for your time.", "why": "The coach had seen a real moment: the teacher asked for hands up and the whole class answered in chorus. The next step, though, is a general exhortation with no routine, no words to say, no practice and no reply from the teacher.", "better_move": "Let's pick one routine for next lesson: ask the question, say 'hands up, no calling out', count three in your head, then say one child's name. How would you say that to your class? Try it now. ... Good, and say the name last so everyone keeps thinking. Which lesson tomorrow will you use it in?", "better_move_local": "اگلے سبق کے لیے ایک طریقہ چن لیتے ہیں: سوال پوچھیں، کہیں 'ہاتھ کھڑا کریں، کوئی بولے گا نہیں'، دل میں تین تک گنیں، پھر کسی ایک بچے کا نام لیں۔ کلاس کو یہ کیسے کہا جائے گا؟ ابھی ایک بار کہہ کر دکھائیں۔ ... بہت اچھا، اور نام آخر میں لیں تاکہ سب سوچتے رہیں۔ کل کس پیریڈ میں اسے آزمایا جائے گا؟", "lang": "ur", "rtl": true}, {"key": "d7e3b61f359_ict2_13", "file": "clips/d7e3b61f359_ict2_13.mp3", "dur": 23.3, "kind": "missed_opportunity", "dimension": "practice_or_modelling", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 62", "title": "A role play described, not done", "quote_original": "کوچ: تو یہ جب ایک دفعہ، ایک بار بلڈ کریں گے نا، ایک دفعہ تھوڑا ٹائم لگے گا، اس کے بعد آپ پیغام دیں گے۔ اب گروپ پریکٹس ہو گی نا، دیکھیں، میں آپ کو اب ایز اے ٹیچر والی ایگزیمپل دیتی ہوں۔ میں نے ایک ٹاسک دیا آپ کو، ایپلیکیشن کا۔ آپ کو میں اکیلی دے دوں، آپ کو اس طرح سے سمجھ نہیں آئے گی۔ لیکن میں آپ کو بولوں گی، آپ اور میم، بلکہ مل کے کر لیں۔ ٹیچر: کر لیں، آسان ہے۔ کوچ: آسان ہے۔ وہی ٹاسک میں آپ کو اس کے بعد، ہمم، چیز ایزی ہو جائے گی، ایزی ہو جائے گی۔ اسی طرح بچوں کے لیے بھی۔", "quote_en": "Coach: Once you build this, it takes a bit of time the first time, and after that you just give the signal. Now, for group practice, let me give you an example as a teacher. Say I gave you a task, writing an application. If I give it to you alone, you won't get it the same way. But if I tell you, 'You and ma'am, do it together'... Teacher: Do it together, it's easy. Coach: It's easy. Then that same task becomes easy for you. It's the same for children.", "why": "The coach starts a mini role play with the teacher as the learner, and the teacher immediately gets the point ('together, it's easy'). Then the coach explains instead of letting the teacher give the group instruction. The teacher had already said group practice was 'completely new'.", "better_move": "Let's try it now. I'm your class. Give me the group instruction and the time limit, exactly as you'd say it to the children. ... Good, you gave the time. Now add who will answer for each group, and say it once more.", "better_move_local": "چلیں ابھی کر کے دیکھتے ہیں۔ میں آپ کی کلاس ہوں۔ مجھے گروپ کی ہدایت اور وقت بالکل ویسے بتائیں جیسے بچوں کو بتایا جاتا ہے۔ ... اچھا، وقت آپ نے بتا دیا۔ اب یہ بھی بتائیں کہ ہر گروپ کی طرف سے جواب کون دے گا، اور ایک بار پھر کہیں۔", "lang": "ur", "rtl": true}, {"key": "d66f5046c80_ict2_14", "file": "clips/d66f5046c80_ict2_14.mp3", "dur": 29.9, "kind": "missed_opportunity", "dimension": "commitment_and_follow_up", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 37", "title": "A strong debrief that ends on 'inshallah'", "quote_original": "کوچ: ٹھیک ہے، تو ریویژن کلاس میں بھی اس کو یوز کریں۔ یہ تو بس بچہ بٹھائے رکھنے کے لیے، کہ وہ ایک دوسرے کے اوپر سے نہ بولیں۔ آپ کی نظر میں آ سکے کون، کس کو زیادہ مدد کی ضرورت ہے۔ کیونکہ جو یہ والی لائن تھی نا، یہ بچے میں دیکھ رہی تھی، اتنا سا ہاتھ کھڑا کرتے تھے، لیکن جب وہ ان کے— وہ کھڑے ہو کے جواب دے رہے ہیں، ان کا یہ والا ہاتھ نظر نہیں آتا تھا۔ تو پھر آپ کی اٹینشن ادھر بھی آئے گی، پھر آپ کو پتہ چلے گا ان کو کتنا آتا ہے، کتنا اسسٹنس چاہیے۔ ٹیچر: انشاء اللہ، نیکسٹ کلاس میں۔ کوچ: ٹھیک ہے میم، بس یہی لے کے چلیں۔ اللہ حافظ۔", "quote_en": "Coach: Okay, so use it in the revision class too. It's only to keep children seated so they don't talk over each other, and so you can see who needs more help. Because in that line, I was watching, the children raised their hands only a little, and when others stood up to answer, those hands couldn't be seen. So your attention will go there too, and you'll know how much they know and how much help they need. Teacher: God willing, in the next class. Coach: Okay ma'am, let's go with this. Goodbye.", "why": "This is one of the group's best debriefs, with specific praise and a points routine adapted to the teacher's lack of resources. It still closes on a one-line 'inshallah'. The teacher never says how they will start the routine, nobody agrees what success looks like, and there is no date to check.", "better_move": "Before we close: how will you start the points routine in the first minute of the revision class? Say it the way you'll say it to the children. ... And how will we know it's working? Maybe the quiet line answers at least three times. I'll come on my next visit to see exactly that.", "better_move_local": "ختم کرنے سے پہلے: ریویژن کلاس کے پہلے منٹ میں پوائنٹس والا طریقہ کیسے شروع ہوگا؟ ویسے کہہ کر دکھائیں جیسے بچوں سے کہا جائے گا۔ ... اور ہمیں کیسے پتہ چلے گا کہ یہ کام کر رہا ہے؟ شاید خاموش والی لائن کم از کم تین بار جواب دے۔ اگلے وزٹ پر یہی دیکھنے کے لیے ملاقات ہوگی۔", "lang": "ur", "rtl": true}, {"key": "d2b3eab1866_ict2_15", "file": "clips/d2b3eab1866_ict2_15.mp3", "dur": 29.1, "kind": "missed_opportunity", "dimension": "tone_and_psychological_safety", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 23", "title": "Mentioning the score turns talk into proof", "quote_original": "کوچ: اچھا میم، اگر کلاس... کیونکہ آپ کی recording میں نا وہ ایک factor تھی، اُس کی بھی scores ہوتی ہیں نا۔ تو اس وجہ سے آپ بے شک orally بچوں کو ایک دفعہ بتائیں کہ بچوں، آپ کا homework... تاکہ یہ ہو کہ آپ... آپ دے تو رہی ہیں، لیکن اُس basis پہ آپ اُس time نہیں دے رہی، تو وہ تھوڑا آپ کے score پر— ٹیچر: نہیں، ہم ڈائری دیتے ہیں باقاعدہ daily ڈائری بچوں کو۔ یہ میں آپ کو بتا رہی ہوں۔ ہم روز کا homework دیتے ہیں۔ ایک آپ نہیں، ہمارے اسکول میں ایک آتے ہیں monitoring والے بھائی صاحب بھی۔", "quote_en": "Coach: Okay ma'am, because in your recording there's a factor for that, and it has scores too. So please just tell the children the homework orally once, 'children, your homework...', because you are giving it, but not at that time, so it affects your score a bit... Teacher: No, we give a proper daily diary to the children. I'm telling you, we give homework every day. And it's not just you; a monitoring person also comes to our school.", "why": "The reason the coach gives for a small change is the score on the recording form. The teacher shifts at once to proving compliance (the diary, the monitoring officer, then their phone), and the next two minutes go on evidence rather than on teaching.", "better_move": "You give homework daily through the diary; that's good. I'd just like the children to hear it in the lesson too, so the ones without WhatsApp don't miss it. In the last two minutes, could you say the homework aloud and have one child repeat it back?", "better_move_local": "ڈائری کے ذریعے روز ہوم ورک دیا جاتا ہے، یہ اچھی بات ہے۔ بس یہ بھی اچھا رہے گا کہ بچے سبق کے اندر بھی یہ سن لیں، تاکہ جن کے پاس واٹس ایپ نہیں وہ بھی پیچھے نہ رہیں۔ آخری دو منٹ میں ہوم ورک بول کر بتا دیں اور ایک بچے سے دہروا لیں۔", "lang": "ur", "rtl": true}, {"key": "d1cca120c06_ict3_00", "file": "clips/d1cca120c06_ict3_00.mp3", "dur": 28.1, "kind": "strength", "dimension": "purpose_and_relationship_opening", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 37", "title": "Picking up the goal from last visit", "quote_original": "کوچ: ٹھیک ہے۔ میم، ہم نے لاسٹ ابزرویشن میں ڈیسائیڈ کیا تھا کہ ہم جو لیسن پلان کے فائیو سٹیپس ہوں گے، ان کو لازمی کمپلیٹ کریں گے۔ تو وہ چیز مجھے آج کل کلاس روم میں ہوتی نظر آ رہی تھی۔ آپ نے انٹروڈکشن کروایا، آپ نے اس کے بعد ایکسپلینیشن دی بچوں کو، ایریا یہ ہوتا ہے، پیریمیٹر یہ ہوتا ہے۔ پھر آپ نے جی پی کروائی، پھر آپ نے آئی پی کروائی۔ جو لاسٹ سٹیپ تھا، پانچواں سٹیپ، کلوزنگ، وہ نہیں ہو سکا کیونکہ بچے ابھی آئی پی میں ہی لگے ہوئے تھے اور ویلو ہو رہے تھے۔", "quote_en": "Coach: Okay. Ma'am, at the last observation we decided that we would definitely complete all five steps of the lesson plan, and I could see that happening in the classroom today. You did the introduction, then you explained to the children what area is and what perimeter is. Then you did guided practice, then independent practice. The last step, the fifth one, closing, could not happen because the children were still busy with their independent practice.", "why": "The coach recalls the goal agreed at the last observation and checks it against what was seen, step by step, so the gap (no closing) is a fact both can see, not a judgement. Only 11 of 65 coaches link back to earlier work at all.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "d13a6ed5383_ict3_01", "file": "clips/d13a6ed5383_ict3_01.mp3", "dur": 32.5, "kind": "strength", "dimension": "teacher_self_reflection", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 04", "title": "The teacher names their own growth area", "quote_original": "کوچ: ہمم۔ اس لیے پھر میرا خیال ہے وہی ریشنل ہے کہ آپ نے جو کل لیسن پڑھایا ہوگا، تو ڈیفینٹلی وہ اتنا ڈیٹیلڈ اور انوالوڈ کیا ہوگا اپنے بچوں کو۔ ڈیفینٹلی ان کی ڈرلنگ کرائی ہوگی، جو آج بھی کلاس میں تھی۔ تو ایک یہ بہت بڑا ریشنل ہوتا ہے۔ اوکے، میم، کوئی ایسا پوائنٹ جو آپ کو لگتا ہے کہ آج آپ کلاس میں نہیں کروا سکیں، یا کروانا چاہ رہے تھے، یا کرواتے تو اس سے لرننگ آؤٹ کمز آپ کے اور مزید بہتر ہو سکتے تھے؟ / ٹیچر: ایک تھوڑی سی چیز جو لیک کر رہی تھی، اور NIAT ہمیں گائیڈ بھی کر رہا ہے اس حوالے سے، کہ ریپ اپ تھوڑا سا کمزور تھا میرا۔ اور اس میں اوپن اینڈڈ اور وائی ٹائپ کوئسچنز جو ہیں نا، وہ آئی اگنور بیٹھ جاتے تھے۔", "quote_en": "Coach: So I think that is the reason: yesterday's lesson must have been detailed and you must have involved and drilled the children, and that showed today. OK ma'am, is there any point you feel you could not do in class today, or wanted to do, or that would have made the learning outcomes even better? / Teacher: One small thing was lacking, and NIAT guides us on this too: my wrap-up was a bit weak. And the open-ended, why-type questions, I tend to skip those.", "why": "One open, non-leading question ('anything you could not do, or wanted to do?') and the teacher identifies the growth area in their own words. The rest of the debrief can now work on the teacher's diagnosis instead of the coach's.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "d0bcb407dff_ict3_02", "file": "clips/d0bcb407dff_ict3_02.mp3", "dur": 30.6, "kind": "strength", "dimension": "coach_questioning_and_dialogue", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 09", "title": "Narrowing the question, not answering it", "quote_original": "کوچ: ہاں، کوئی آپ بتائیں، آپ کو کیا لگتا ہے کہ فزیکلی کمپلیٹ والی کون سی کرا سکتی ہیں آپ؟ / ٹیچر: وہی میں بتا رہی ہوں نا۔ / کوچ: اس کلاس میں، اس سبجیکٹ میں، اس ٹاپک میں؟ / ٹیچر: اس ٹاپک میں، آئی تھنک، بچوں کو کاؤنٹنگ کر سکتے ہیں۔ بچوں کی، مطلب، دو بچے کھڑے کریں، پھر دو، پھر دو، دو، ایسے کر کے۔ پھر وہ بچے ان کو کاؤنٹ کریں کہ یہ ٹو، یہ ٹو، یہ ٹو، یہ ٹو، اس طرح سے۔ یا تھری تھری بچے ایڈ کر سکتے ہیں۔ یہ بھی ہو سکتا ہے۔ / کوچ: بورڈ پہ بھی کروا سکتے ہیں؟ / ٹیچر: ہاں جی، بورڈ پہ فزیکلی بھی بچوں سے کام کروا سکتے ہیں۔ ٹھیک ہے، چلیں نیکسٹ ہم وہ بھی کروا لیتے ہیں۔", "quote_en": "Coach: You tell me, which hands-on activity do you think you could do? / Teacher: That's what I'm telling you. / Coach: In this class, this subject, this topic? / Teacher: In this topic, I think, the children can count. Two children stand up, then two more, then two more, and the others count them: this is two, this is two. Or add three at a time. / Coach: Could they do it on the board too? / Teacher: Yes, children can do work physically on the board too. OK, next time we'll do that as well.", "why": "When the teacher is stuck, the coach does not supply the answer; they narrow the question to this class, this subject, this topic. The teacher then invents a concrete counting activity and says they will use it next.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "d775a8e43c8_ict3_03", "file": "clips/d775a8e43c8_ict3_03.mp3", "dur": 20.4, "kind": "strength", "dimension": "evidence_from_the_lesson", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 24", "title": "Praise for one moment, and why it matters", "quote_original": "کوچ: ہاں۔ ایک بچی نے آپ سے کوئسچن کیا تھا، تو آپ نے اس کو بڑا ویلکم کیا کہ ہاں، اس نے بڑا اچھا کوئسچن کیا، اس کو ایپریشیٹ کیا۔ / ٹیچر: اس نے کوئسچن کیا تھا کہ اگر وہ 100 نہ نیچے بنے، تو میں نے کہا تھا کہ اس کا دوسرا میتھڈ ہے کہ آپ اس کو ڈیوائیڈ کریں۔ / کوچ: بالکل۔ مجھے وہ چیز بڑی اچھی لگی، خود کو بھی، کہ آپ نے اس کو ایپریشیٹ کیا، کیونکہ پھر ورنہ بچے نا سوال کرنے سے ڈر جاتے ہیں، اور وہ والا ہے۔", "quote_en": "Coach: A girl asked you a question, and you welcomed it: you said it was a very good question and appreciated the girl. / Teacher: The girl asked what to do if the denominator doesn't come to 100, and I said there is another method, you divide. / Coach: Exactly. I really liked that you appreciated the girl, because otherwise children become afraid of asking questions.", "why": "The praise points to one observed moment, the teacher adds the detail, and the coach explains the effect on students (they stay willing to ask). This is what turns praise into something the teacher will repeat on purpose.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "d1adbea82af_ict3_04", "file": "clips/d1adbea82af_ict3_04.mp3", "dur": 39.5, "kind": "strength", "dimension": "focus_on_one_growth_area", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 12", "title": "One growth area, made safe, then planned", "quote_original": "کوچ: जी। तो उसने help किया आपको काफी चीज़ों में। तो इस चीज़ को फिर हम follow करेंगे, इस practice को हम रखेंगे। इसके अलावा, हमारी एक और discussion हुई थी last time, मैम, हमने pair work और group work के ऊपर बात की थी थोड़ी बहुत। सो, वो किस हद तक implement हो सका class में आज? / ٹیچر: आज, I think, missing था वो। / کوچ: हाँ, वो नहीं हो पाया। तो अगर next time अगर करवाना चाहें आप, that's totally fine, हर चीज़ हर time नहीं हो पाती है। But in case अब next अगर हम इसको area of growth रखते भी हैं, तो आप उसको कैसे implement करेंगी? Like, क्या steps होंगे आपके? / ٹیچر: Pairs बनाकर pair work करवा लूँगी। / کوچ: जैसे दो-दो बच्चे बैठे हुए हैं? / ٹیچر: दो-दो। / کوچ: ठीक है। तो उसी task को कैसे उनको मैम assign करेंगी pairs में?", "quote_en": "Coach: So that helped you with a lot, and we'll keep that practice. Apart from that, ma'am, last time we also talked a little about pair work and group work. How far could that be done in class today? / Teacher: Today, I think, that was missing. / Coach: Yes, it didn't happen. That's totally fine, not everything happens every time. But if we now keep this as the area of growth, how will you do it? What will your steps be? / Teacher: I'll make pairs and do pair work. / Coach: Like two children sitting together? / Teacher: Two each. / Coach: OK. So how will you give that same task to them in pairs?", "why": "The coach links back to last meeting's goal, treats the gap as normal ('not everything happens every time'), names it as the one area of growth, and asks 'how' twice so the teacher builds the plan. This is from the highest-scoring debrief in the group.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "dcd6f481273_ict3_05", "file": "clips/dcd6f481273_ict3_05.mp3", "dur": 27.9, "kind": "strength", "dimension": "concrete_action_step", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 42", "title": "Asking the teacher to choose one target", "quote_original": "کوچ: اچھا میم، اگر ہم target set کریں اگلی observation کے لیے، کہ اگلی کلاس کے اندر آپ کون سی ایک، ایک ایریا ہے جس کے اوپر آپ کام کرنا چاہیں گے، ہم نے دو ایریاز کی بات کی، ایک تو جو کلاس ہے اس کو زیادہ سٹوڈنٹ سینٹرک بنایا جائے، جس میں ٹیچر۔ / ٹیچر: I am trying کہ the explanatory part would be more simpler، مطلب simplest فارم میں ہو، terminologies بعد میں describe، introduce کروائی جائیں، first they must be given the idea۔", "quote_en": "Coach: OK ma'am, if we set a target for the next observation: which one area would you like to work on in the next class? We talked about two areas; one is making the class more student-centred, where the teacher... / Teacher: I'm trying to make the explanation part simpler, in the simplest form, with the new terms described and introduced later. First they must be given the idea.", "why": "After a long discussion the coach narrows to one area and lets the teacher choose it; the teacher names an observable change (core idea first, new terms afterwards) in their own words.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "d10e2469964_ict3_06", "file": "clips/d10e2469964_ict3_06.mp3", "dur": 18.6, "kind": "strength", "dimension": "practice_or_modelling", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 12", "title": "The teacher says the instruction aloud", "quote_original": "کوچ: چار، ڈسکشن۔ اور وہی والی بات آپ کی، ٹائم دے کے، دین وی کین آسک دیم نا۔ ٹھیک ہے میم؟ تو اگر آپ اس طرح کریں گی تو نیکسٹ ٹائم کیسے اس کو آپ پریکٹس کریں گی، اسی گروپ والی چیز کو؟ / ٹیچر: اسی گروپ میں، چار چار میں ڈیوائیڈ کر دوں گی۔ / کوچ: جی، اور سوال میں پھر ان چار میں سے کسی ایک سے پوچھ لیں گے۔ / ٹیچر: چار میں سے ہم گروپ سے کہیں گے۔ / کوچ: ہمم، کہ پہلے سوچو۔ / ٹیچر: گروپ سے کہیں گے، سوچیں اور ہمیں بتائیں۔ / کوچ: ڈسکس کریں۔ / ٹیچر: وہ ہمیں گروپ ہی بتائے گا۔", "quote_en": "Coach: Fours, discussion. And your own point: give time, then we can ask them, right ma'am? So how will you practise this group idea next time? / Teacher: In the same groups, I'll divide them into fours. / Coach: Yes, and then for the question you ask one of the four. / Teacher: We'll tell the group, of the four. / Coach: Hmm, 'first think'. / Teacher: We'll tell the group: think, and tell us. / Coach: Discuss. / Teacher: The group itself will tell us.", "why": "One of only 3 debriefs out of 65 where the teacher says the new step in their own classroom words. The coach prompts with half-sentences and the teacher completes the routine: groups of four, think, discuss, then the group answers.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "d8df2b4b1e7_ict3_07", "file": "clips/d8df2b4b1e7_ict3_07.mp3", "dur": 27.8, "kind": "strength", "dimension": "commitment_and_follow_up", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 16", "title": "Asking the teacher to say it back", "quote_original": "کوچ: اس میں ہم نے کیا چیز آپ سے ڈسکشن کی ہے کہ ہم کیا کریں گے نیکسٹ ٹائم میں؟ / ٹیچر: نیکسٹ ٹائم میں یہ ہے کہ ہم نے پیئر ورک جو ہے وہ لازمی کروانا ہے، بچوں کے گروپس بنانے ہیں، اور گروپ میں بچوں کو کام کروانا ہے۔ اور دوسرا، تمام بچے جو ہیں انوالو ہوں، اور ہر بچہ انڈیویجولی اپنا کام کر کے جو ہے وہ دکھائے۔ اور انڈیویجولی کام کرے۔ 15 منٹس کا ہم انہیں—ہم بول کے ان کو بتائیں، اور 15 منٹس کے بچے جو ہیں وہ خود کام کریں، اور وہ ہمارے ساتھ شیئر کریں اپنا کام۔", "quote_en": "Coach: What have we discussed about what we'll do next time? / Teacher: Next time we must do pair work: make groups of children and have them work in groups. Second, every child should be involved, each child should do their own work individually and show it. For 15 minutes we explain to them, and for 15 minutes the children work on their own and share their work with us.", "why": "Instead of summarising, the coach asks the teacher to restate the plan, and the teacher gives it in their own words with a time split (15 minutes teacher talk, 15 minutes student work). Only 11 of 65 debriefs reach this point.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "d5a4a9b9e0d_ict3_08", "file": "clips/d5a4a9b9e0d_ict3_08.mp3", "dur": 15.7, "kind": "missed_opportunity", "dimension": "teacher_self_reflection", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 10", "title": "A one-line answer accepted", "quote_original": "کوچ: اچھا، میں نے آج آپ کی گریڈ فور کی اردو کی کلاس آبزرو کی۔ سب سے پہلے آپ سے جاننا چاہوں گی کہ آپ کے اکارڈنگ آج کی آپ کی کلاس کا کیا ریفلیکشن ہے؟ کہ آپ کی کلاس کیسی گئی؟ / ٹیچر: میری کلاس، الحمدللہ، بہتر ہوئی ہے۔ / کوچ: ٹھیک ہے۔ / ٹیچر: جی۔ / کوچ: ٹھیک ہے۔ / ٹیچر: جی۔", "quote_en": "Coach: I observed your Grade 4 Urdu class today. First I'd like to know your own reflection on today's class: how did it go? / Teacher: My class, thank God, went better. / Coach: Okay. / Teacher: Yes. / Coach: Okay. / Teacher: Yes.", "why": "The opening question is right, but 'it went better' is accepted as it is; the coach then speaks for over four minutes and the teacher says almost nothing else (about 3 percent of the words).", "better_move": "Treat the first answer as a door, not an answer: 'Better in what way? Tell me one moment where the children did something that pleased you, and one moment you would teach differently.' Then wait before giving any praise.", "better_move_local": "شکریہ۔ بہتر کس لحاظ سے؟ مجھے ایک لمحہ بتائیں جب بچوں نے کچھ ایسا کیا جس سے خوشی ہوئی، اور ایک لمحہ جسے اگلی بار مختلف طریقے سے پڑھایا جائے۔", "lang": "ur", "rtl": true}, {"key": "d0c97a86602_ict3_09", "file": "clips/d0c97a86602_ict3_09.mp3", "dur": 34.5, "kind": "missed_opportunity", "dimension": "coach_questioning_and_dialogue", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 27", "title": "The teacher's own growth area, dropped", "quote_original": "ٹیچر: تو باقی میرا یہی ہے کہ گروتھ کے لیے یہ ہے کہ اگر یہ جو میں نے 10 منٹ پریکٹس کرائی ہے، اگر میرے دو پیریڈز ہوتے ہیں، اگر یہ پریکٹس میں 50 منٹ کراتی تو اگر ابھی 20 بچوں سے رسپانس آ رہا ہوتا تو پھر 30 بچوں سے آتا۔ / کوچ: بالکل۔ / ٹیچر: تو یہی ہے کہ پریکٹس کا دورانیہ تھوڑا سا زیادہ ہونا چاہیے تھا۔ میں اٹھ کے بورڈ پہ بھی لکھتی تو وہ زیادہ ہوتا۔ / کوچ: بالکل، بالکل آیا نہیں سر۔ اچھا، لَیسن پلان سے ریلیٹڈ، مطلب جو آپ نے بات کی، for example اگر if I ask کہ جو گروپ پریکٹس یا گائیڈڈ پریکٹس تھی، لَیسن پلان کے اندر کون سی ٹاسک تھا جو بچوں کے لیے انہوں نے اسائن کیا ہوا تھا؟", "quote_en": "Teacher: For growth, it's this: I gave 10 minutes of practice. I have a double period; if I had given 50 minutes of practice, then instead of 20 children responding, 30 would have. / Coach: Absolutely. / Teacher: So the practice time should have been a bit longer. If I had got up and written on the board too, there would have been more. / Coach: Absolutely, absolutely. OK, about the lesson plan: if I ask, in the group or guided practice, what task had the plan set for the children?", "why": "The teacher names a precise growth area with a measure of success (from 20 to 30 children responding). The coach says 'absolutely' and switches to quizzing the lesson plan, then gives a three-minute talk on fidelity and 'zero credit'. The teacher's idea never comes back.", "better_move": "Stay on the teacher's idea: 'You've just named it yourself: more practice time, so 30 children answer instead of 20. Let's make that the step. In tomorrow's lesson, what will the children do in those extra minutes, and how will you get the quiet ones to answer?'", "better_move_local": "آپ نے خود ہی بات پکڑ لی ہے: پریکٹس کا وقت زیادہ ہو تاکہ 20 کی بجائے 30 بچے جواب دیں۔ یہی ہمارا اگلا قدم بنا لیتے ہیں۔ کل کے لیسن میں ان اضافی منٹوں میں بچے کیا کریں گے، اور خاموش بچوں سے جواب کیسے لیا جائے گا؟", "lang": "ur", "rtl": true}, {"key": "ddb0eb9fecc_ict3_10", "file": "clips/ddb0eb9fecc_ict3_10.mp3", "dur": 17.4, "kind": "missed_opportunity", "dimension": "purpose_and_relationship_opening", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 40", "title": "An opening about the teacher's temper", "quote_original": "کوچ: السلام علیکم، السلام علیکم۔ یہ دیکھیں، آپ کی— میرے خیال سے آپ کی انرجی جو ہے، یہاں تک پہنچتے پہنچتے ڈرین ہو جاتی ہے۔ آپ کے— آپ کے اس بولنے کے اسٹائل سے پتہ چل رہا تھا کہ آپ کی بس ہو چکی ہے۔ ابھی کوئی سامنے آئے تو آپ رک کے لگا دیں گی۔ کیا انرجی بہت زیادہ لگ گئی ہے آج؟", "quote_en": "Coach: Peace be upon you. Look, I think your energy gets drained by the time you get here. From the way you were speaking I could tell you'd had enough. If someone came in front of you right now, you'd stop and hit them. Has a lot of energy gone today?", "why": "Meant as sympathy, but the first thing the teacher hears is a comment on their mood and temper. A minute later the teacher is defending themself ('I don't hit, ask the children'). The lesson has not been mentioned yet.", "better_move": "Open with thanks and purpose, and keep the empathy about the workload, not the person: 'Thank you for having me. I know a double period is tiring. I'm here so we can look at the lesson together and pick one thing that will help. How did you feel it went?'", "better_move_local": "السلام علیکم۔ کلاس میں آنے دینے کا بہت شکریہ، پتا ہے ڈبل پیریڈ تھکا دیتا ہے۔ یہ ملاقات اس لیے ہے کہ مل کر لیسن کو دیکھیں اور ایک ایسی چیز چنیں جو کام آئے۔ آپ کو خود کیسا لگا، کلاس کیسی گئی؟", "lang": "ur", "rtl": true}, {"key": "ddff5fefa78_ict3_11", "file": "clips/ddff5fefa78_ict3_11.mp3", "dur": 34.9, "kind": "missed_opportunity", "dimension": "concrete_action_step", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 09", "title": "'I'll see, God willing' accepted as a plan", "quote_original": "ٹیچر: اس میں، آہ، میرے خیال سے کچھ ایک دو activities skip ہوئی ہیں۔ آہ، یعنی، یعنی اس میں جو میں نے generate کیا اس سے related مجھے کمی جو لگ رہی ہے کہ آپ نے۔ / کوچ: Lesson plan جب ہم لوگ کرواتے ہیں نا تو جیسے کہ lesson start کرواتے ہیں، explanation start کرواتے ہیں، اس کے بعد والے steps۔ / ٹیچر: Because I was not prepared. / کوچ: تو اب کیا کریں گے؟ Next میں کیسے لے کے چلیں گے؟ / ٹیچر: ہاں، next ان شاء اللہ۔ وہ مجھے پتا ہے، آپ نے پہلے بھی مجھے observe کرتی رہی ہیں، SLO وغیرہ۔ دیکھوں گی، ان شاء اللہ۔ So ایک وہ break آیا ہوا تھا نا، تو that's why۔", "quote_en": "Teacher: I think one or two activities were skipped, compared with what I generated. / Coach: When we run a lesson plan, we start the lesson, start the explanation, then the steps after that. / Teacher: Because I was not prepared. / Coach: So what will we do now? How will you take it forward next time? / Teacher: Next time, God willing. I know, you've observed me before, the SLO and so on. I'll see, God willing. There was a break, that's why.", "why": "The teacher owns the gap and the coach asks the right question ('how will you take it forward?'), but 'I'll see' is accepted. Nobody names which activity, when, or how anyone will know; the debrief ends seconds later.", "better_move": "Push gently for one specific: 'Which one of those skipped activities matters most for this topic? Let's make sure that one happens tomorrow. At what point in the lesson will you do it, and what will you say to start it?'", "better_move_local": "جو ایکٹیویٹیز رہ گئیں ان میں سے اس ٹاپک کے لیے سب سے ضروری کون سی ہے؟ وہ ایک کل پکی کر لیتے ہیں۔ لیسن کے کس حصے میں کروائی جائے گی، اور شروع کرتے وقت بچوں سے کیا کہا جائے گا؟", "lang": "ur", "rtl": true}, {"key": "d4b1ffa7e7b_ict3_12", "file": "clips/d4b1ffa7e7b_ict3_12.mp3", "dur": 34.1, "kind": "missed_opportunity", "dimension": "practice_or_modelling", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 36", "title": "A working routine, sent elsewhere", "quote_original": "ٹیچر: یہ ٹو میں ایسے، ٹو والا ایسے کرتے ہیں۔ ان کو جیسے ہی میں دونوں ہاتھ یوں کرتی ہوں نا، وہ سب پین کلک، ٹھیک؟ ان کو میں نے پریکٹس کروائی ہوئی ہے۔ اور ٹو والے بچے تھوڑے چھوٹے ہیں، وہ شرارتیں تھوڑی کم کرتے ہیں۔ ان کو بھی۔ بس وہاں پہ میں جیسے ہی دونوں ہینڈز ایسے ایسے کرتی ہوں، تو سب مجھے دیکھتے ہیں، اور پینسل یا پین جو بھی ان کے ہاتھ میں ہوتا ہے، وہ پکڑ لیتے ہیں۔ / کوچ: یہاں پہ شروع کریں۔ اپنے ساتھ جو اور ٹیچرز پڑھا رہی ہیں نا، ان کو بھی لگائیں، یا ان سے پوچھیں کہ آپ بچوں کو اٹینٹو کرنے کے لیے کیا کرتی ہیں؟ پھر کوئی ایک ہی طریقہ سارے رکھ لیں جو یوز کریں، تاکہ یہ عادی ہو جائیں۔ باقی یہ چل لیں گے۔", "quote_en": "Teacher: In Class 2 we do it like this. As soon as I put both hands up like this, they all click their pens, right? I've practised it with them. The Class 2 children are younger, a bit less naughty. As soon as I do both hands like this, they all look at me and hold whatever pencil or pen is in their hand. / Coach: Start it here. Get the other teachers who teach with you involved too, or ask them what they do to get attention. Then all of you keep one method, so the children get used to it. The rest will follow.", "why": "After a long list of advice, the teacher offers an attention signal that already works in another class. The coach says 'start it here' but sends the teacher to consult colleagues instead of rehearsing the signal and fixing a day to start it with this class.", "better_move": "Use what the teacher already has: 'That's a routine that works for you. Show me exactly what you do and say with Class 2. Good. Now do it as if you're starting tomorrow's Class 3 period. What will you do the first time some children don't respond?'", "better_move_local": "یہ تو آپ کا آزمایا ہوا طریقہ ہے۔ مجھے بالکل ویسے کر کے دکھائیں جیسے کلاس ٹو میں کیا جاتا ہے، اور جو بولا جاتا ہے وہ بھی۔ بہت اچھا۔ اب ایسے کریں جیسے کل کلاس تھری کا پیریڈ شروع ہو رہا ہے۔ اگر پہلی بار کچھ بچے نہ رکیں تو کیا کیا جائے گا؟", "lang": "ur", "rtl": true}, {"key": "dfc4e261a67_ict3_13", "file": "clips/dfc4e261a67_ict3_13.mp3", "dur": 29.5, "kind": "missed_opportunity", "dimension": "commitment_and_follow_up", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 52", "title": "The coach makes the promise for the teacher", "quote_original": "کوچ: ایکزیکٹلی، اس طرح سے کوشش ہوتی ہے کہ بچے اس طرح سیکھیں زیادہ۔ چلیں میم، ان شاء اللہ نیکسٹ کلاس میں ایک انڈیویجول پریکٹس کو بھی ہم ایڈ کریں گے۔ جیسے آپ نے کہا کہ آپ کو لگا کہ آج کی کلاس میں میرے بچوں کی انڈیویجول پریکٹس نہیں تھی، تو میں بس نیکسٹ ٹائم اب یہ ٹرائی کروں گی کہ میرے بچوں کی انڈیویجول پریکٹس بھی ہے۔ سو، اوور آل، اٹس ا گڈ ایکسپیرینس، یور ٹیچنگ میتھڈالوجی از گڈ، بٹ یہ جو ایک چھوٹا سا پارٹ رہ گیا، ان شاء اللہ نیکسٹ میں ہم اس کو بھی دیکھیں گے۔ بہت شکریہ، اور نیکسٹ ٹائم ہمیں اور زیادہ بہترین لگے گا یہ سب کچھ۔", "quote_en": "Coach: Exactly, the aim is that children learn more this way. OK ma'am, God willing, in the next class we will add individual practice too. As you said, you felt there was no individual practice for your children today, so 'next time I will try to make sure my children have individual practice too.' So overall it's a good experience and your teaching method is good, but this small part that was left, God willing we'll look at it next time. Thank you very much.", "why": "The teacher had named the gap themself (no written work in copies, parents complaining). At the close the coach speaks the commitment in the teacher's voice, with no task, no point in the lesson and no way to check, and the teacher never says it.", "better_move": "Hand the close to the teacher: 'You named this yourself. In tomorrow's lesson, after you explain, what exactly will each child write in their copy, and for how many minutes? Say it in your words. On my next visit we'll look at five copies together.'", "better_move_local": "یہ بات آپ نے خود پکڑی ہے۔ کل کے لیسن میں سمجھانے کے بعد ہر بچہ اپنی کاپی میں بالکل کیا لکھے گا، اور کتنے منٹ کے لیے؟ اپنے الفاظ میں بتائیں۔ اگلی وزٹ پر ہم مل کر پانچ بچوں کی کاپیاں دیکھیں گے۔", "lang": "ur", "rtl": true}, {"key": "d83f9073ff7_ict3_14", "file": "clips/d83f9073ff7_ict3_14.mp3", "dur": 33.4, "kind": "missed_opportunity", "dimension": "focus_on_one_growth_area", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 16", "title": "Four faults in one breath", "quote_original": "کوچ: اگر آپ کو ہم نے کونسیپٹ دے دیا، ایک چھوٹا سا کونسیپٹ دے دیا، پھر ان کو سمجھانے میں جو جو چیزیں آپ کر رہی ہیں، وہ پیئر ورک ہے، وہ بک کھولنا ہے، وہ مٹیریل کو دینا، مٹیریل کو ڈسٹریبیوٹ کرنا، اس کا استعمال کرنا، وہ ایز ا فیسلیٹیٹر آپ نے یوز کرنا ہوگا۔ ٹھیک ہے؟ تو یہ چیز ہے کہ ایک تو مینجمنٹ پہ بہت کام کریں۔ صفائی اس میں بھی آتی ہے۔ صفائی بہت آج میں دیکھ رہی تھی میتھس تھا کلاس میں۔ اور دوسرا یہ تھا کہ بچے توجہ سے بات نہیں آپ کی سن رہے تھے، اور آپ آدھے پڑھ رہے تھے، آدھے نہیں پڑھ رہے تھے۔ تو پہلے تو ان کو نا رولز ان کے ساتھ سیٹ کریں۔ / ٹیچر: انشاءاللہ میم۔", "quote_en": "Coach: Once we've given a small concept, the things you do to explain it, pair work, opening books, giving out and using the material, you'll have to manage as a facilitator. Right? So first, work a lot on management. Cleanliness comes into it too; I saw a lot of mess in today's maths class. And second, the children weren't listening to you attentively, and half of them were working and half weren't. So first, set rules with them. / Teacher: God willing, ma'am.", "why": "Facilitation, management, cleanliness, attention and rules arrive in one turn, after the teacher had named their own goal (children solving problems in groups). The only reply possible is 'God willing'. Three areas end up as the 'plan'.", "better_move": "Choose one visible thing and ask before telling: 'I noticed about half the books were still closed when you began explaining. What did you notice? What one routine could you use in the first two minutes tomorrow so every book is open before you start?'", "better_move_local": "میں نے دیکھا کہ جب سمجھانا شروع ہوا تو تقریباً آدھے بچوں کی کتابیں بند تھیں۔ آپ نے کیا دیکھا؟ کل پہلے دو منٹ میں کون سا ایک معمول رکھیں کہ سمجھانے سے پہلے ہر بچے کی کتاب کھلی ہو؟", "lang": "ur", "rtl": true}, {"key": "d37fedf8e7a_ict3_15", "file": "clips/d37fedf8e7a_ict3_15.mp3", "dur": 31.9, "kind": "missed_opportunity", "dimension": "tone_and_psychological_safety", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 44", "title": "A real constraint answered with an order", "quote_original": "ٹیچر: اس کلاس میں ایکچولی وہ ہمارے جو گائے تھے نا، اس میں پہلے ٹیسٹ تھے، ڈسلیکسیا کے، ہاں، ہماری ہاف کلاس اسی کلاس میں پڑھتی تھی، اسی کلاس میں پڑھتی تھی، اسی لیے، اس وجہ سے ان بچوں کے ساتھ بہت ورک کرنا پڑتا ہے، ان کو آگے لانا پڑتا ہے۔ زیادہ تر ہم نے دیکھا آئی سائیڈ ٹھیک ہے، ان کی تو وہ سیٹس۔ / کوچ: لیکن ان بچوں کو پھر بھی انگیج کرنا ہے، کرو گے تو نہیں۔ / ٹیچر: اس لحاظ سے ان کو کرنا پڑتا ہے۔ اس لیے نا، ہمارا اکثر لیسن، جو ایل پیز ہم نے نکالے بھی ہوتے ہیں، ان سے ہم پیچھے رہ جاتے ہیں، کیونکہ وہ کم کرتے ہیں۔", "quote_en": "Teacher: Actually, in this class there were earlier tests for dyslexia; half our class studies in this class, so we have to do a lot of work with these children and bring them forward. / Coach: But you still have to engage these children. / Teacher: That's why we have to. And that's why we often fall behind the lesson plans we've prepared, because they do less.", "why": "The teacher explains a serious constraint (many children with reading difficulties, falling behind the plan). The coach replies with a one-line instruction and moves to their own advice, so the step that follows ignores the children the teacher is most worried about.", "better_move": "Acknowledge it and get curious: 'That's a real challenge, half the class needing extra support. What do those children do during the practice part? So what small thing could they do on their own at the end, even one line, with your help nearby?'", "better_move_local": "یہ واقعی بڑا چیلنج ہے کہ آدھی کلاس کو زیادہ مدد چاہیے۔ پریکٹس کے وقت وہ بچے کیا کر رہے ہوتے ہیں؟ تو آخر میں وہ اپنے طور پر کون سا چھوٹا سا کام کر سکتے ہیں، چاہے ایک ہی لائن ہو، اور مدد پاس ہی موجود ہو؟", "lang": "ur", "rtl": true}, {"key": "d2c1c935ce8_ict4_00", "file": "clips/d2c1c935ce8_ict4_00.mp3", "dur": 42.0, "kind": "strength", "dimension": "teacher_self_reflection", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 16", "title": "Teacher names the gap and scripts the fix", "quote_original": "اس میں یہ ہوا تھا نا کہ اس میں ہم نے یہ بار ماڈل جو ہے نا، وہ بھی کروائے تھے نا آج۔ تو بار ماڈل میں یہ تھا کہ میں نے بک سے کروائے تھے، مطلب جو میٹیریل، وہ میں نے اس طرح نہیں، جس طرح اب ٹیڈی بیئر تھا، تو اس پہ وہ قیمت لگائی تھی نا بک میں۔ تو میرے ذہن میں یہ نا، مطلب اگر میں next کرنا چاہوں گی تو میں باقاعدہ اس طرح میٹیریل لا کے نا، اس پہ قیمت لگاؤں گی کہ for example یہ چیز جو ہے 10 روپے کی ہے، اور دوسری چیز جو ہے وہ 20 روپے کی ہے۔ تو اگر آپ دونوں چیزیں لینا چاہیں گے تو مطلب یہ کتنے کے ہوں گے؟ / یہ lesson plan کے کس حصے میں تھا؟ یہ آپ کا گروپ ورک تھا یا آپ کا individual work تھا جو آپ نہیں کروا سکے؟", "quote_en": "Teacher: We also did the bar model today, but I did it from the book, where the teddy bear had a price on it. Next time I will bring real objects and put prices on them: this one is 10 rupees, the other is 20, so if you want both, how much will they be? Coach: Which part of the lesson plan was this? Your group work or your individual work that you could not do?", "why": "Asked what was missing, the teacher names the gap, proposes real priced objects and even says the exact question they would ask the class; the coach follows with a probing question instead of taking over. This is what reflection that leads to a step sounds like.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "ddc24ed0179_ict4_02", "file": "clips/ddc24ed0179_ict4_02.mp3", "dur": 28.9, "kind": "strength", "dimension": "concrete_action_step", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 28", "title": "Teacher proposes tomorrow's fix, coach builds", "quote_original": "وہ پیچھے والی رو جو ہے نا وہ ہے ہی شرارتیوں کی رو وہ میرے ذہن میں آیا کہ کل میں ان کو آگے بٹھاؤں گی اور جو تھوڑے سے ایسے تیز ایکٹیو بچے ہیں نا ان کو تھوڑا سا اس رو میں میں۔ / عام طور پہ آپ جو ہے روز وغیرہ چینج کرتی ہیں یا۔ / ہاں جی میں روزانہ میں تو پریپ کلاس کی بھی سیٹیں روزانہ چینج کر رہی ہوتی ہوں ان کو ایک جگہ سے دوسری جگہ۔ / اور اگر پیئرز وغیرہ بنے آپ وہ بھی چینج کر سکتی ہیں اگر آپ کو لگتا ہے اور اگر وہ سلو لرنرز ہیں اگر آپ کو لگ رہا ہے ان کو مکس اینڈ میچ کر کے بٹھا دیں تھوڑے فاسٹ لرنرز کو۔", "quote_en": "Teacher: That back row is the naughty row; it came to me that tomorrow I will seat them in front and put some of the quick, active children in that row. Coach: Do you usually change rows? Teacher: Yes, I change seats daily, even in the Prep class. Coach: And if you make pairs you can change those too: mix and match slow learners with faster ones.", "why": "After the coach points to the distracted back rows, the teacher offers their own concrete fix with a day attached, and the coach asks one short question and adds to it rather than replacing it. A teacher-generated step is far more likely to be used.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "d6f88e7cf24_ict4_03", "file": "clips/d6f88e7cf24_ict4_03.mp3", "dur": 22.1, "kind": "strength", "dimension": "evidence_from_the_lesson", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 42", "title": "Praise a student behaviour, then hand over", "quote_original": "اچھا سر، آج کی کلاس میں مجھے جو سب سے اچھی چیز لگی وہ یہ تھی کہ بچوں کو ایپریشیٹ بہت زیادہ کیا جا رہا تھا۔ یعنی بچے بار بار تالیاں بجا کے اپنے ساتھیوں کو ایپریشیٹ کر رہے تھے، اور یہ کلچر مجھے کلاس کا بڑا اچھا لگا۔ آپ کو مزید کلاس میں آج کون کون سی چیزیں اچھی لگیں؟ اپنی ٹیچنگ سے ریلیٹڈ، بچوں نے جو چیزیں کیں اس سے ریلیٹڈ، یا بچوں کی جو انڈرسٹینڈنگ تھی اس سے ریلیٹڈ؟", "quote_en": "Coach: The best thing I saw today was how much the children were appreciated: they kept clapping for their classmates, and I really liked that classroom culture. What else did you like in today's class? About your teaching, about what the children did, or about what they understood?", "why": "One strength, described as something students actually did, then an open question that offers the teacher three ways in. Short, specific and it gives the floor straight back.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "d5ae4182ac9_ict4_04", "file": "clips/d5ae4182ac9_ict4_04.mp3", "dur": 21.8, "kind": "strength", "dimension": "purpose_and_relationship_opening", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 12", "title": "Linking back to last visit's goal", "quote_original": "بالکل۔ اچھا میم، کوئی ایسی— جیسے لاسٹ ہماری میٹنگ ہوئی تھی، ہم نے اس پہ ڈسکس کیا تھا، کچھ آپ کو یاد ہے کہ— / جی، کیسے، ہاں جی۔ / ہاں، کہ ہم نے اوپن اینڈڈ کوئسچن کرنے ہیں، کیوں اور کیسے، اور وہ آپ نے بہت اچھے سے کیا، آج تو وہ بھی بہت پازیٹو لگا مجھے کہ آپ نے پوچھا کہ کیوں، ایسے کیوں ہے۔ تو اس میں بچے کچھ الگ ہی بتائے تھے، تو ان کو کلیرٹی۔ / میں یہی کہتی ہوں، میں تو ہمیشہ غلط بتاؤں، لیکن کچھ تو پتا تو چلے نا کہ کلاس میں موجود ہے۔", "quote_en": "Coach: Like in our last meeting, we discussed something, do you remember? Teacher: Yes. Coach: That we would ask open-ended why and how questions, and you did it very well. Today you asked 'why is it like this?' and the children said something different, so they got clarity. Teacher: That is what I do, I even say something wrong on purpose, so at least I know who is following.", "why": "Only 12 of 62 openings link to earlier work or frame a support purpose. Here the coach recalls the goal agreed last time and names the exact moment it showed up today, which tells the teacher the coaching is a continuing thread and not a one-off inspection.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "d1e217fce8d_ict4_05", "file": "clips/d1e217fce8d_ict4_05.mp3", "dur": 40.5, "kind": "strength", "dimension": "tone_and_psychological_safety", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 36", "title": "Normalising a self-critical teacher", "quote_original": "انسان، کچھ انسان ہوتے ہیں بہت critical اپنے بارے میں، ہونا بھی چاہیے، پر اپنے آپ میں جو اچھی چیزیں ہیں وہ بھی پتہ ہونی چاہییں، میرے خیال میں وہ ضروری ہوتی ہیں۔ کیونکہ آپ کو ایک life گزارنی ہے، and it's very important to stay happy, to know about yourself, and also کہ اچھا بہتر کیا ہو سکتا ہے، اس کے بارے میں۔ / جو weaknesses پتہ ہوں گی تو اس کو ہم overcome کرنے کی کوشش کریں گے۔ / لیکن پھر ہم کچھ روز اچھا بھی کر رہے ہوتے ہیں، وہ بھی ہمیں پتہ ہونا چاہیے، اور اس کے بارے میں ہمیں vocal بھی ہونا چاہیے کہ ہے اچھا تو ہے۔ اس میں flex کی کوئی بات نہیں ہے، جو اچھا ہے وہ ہے۔", "quote_en": "Coach: Some people are very critical of themselves, and that is fine, but you should also know your good things; that matters. Teacher: If we know our weaknesses we can try to overcome them. Coach: But we also do well some days, and we should know that and say it. There is no showing off in that; what is good is good.", "why": "The teacher has just said they see nothing good in their lesson. The coach treats that as normal, does not argue, and widens the view, which keeps a discouraged teacher open for the feedback that follows.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "d8e9f467ac6_ict4_06", "file": "clips/d8e9f467ac6_ict4_06.mp3", "dur": 22.6, "kind": "strength", "dimension": "commitment_and_follow_up", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 52", "title": "Teacher states next class's plan", "quote_original": "جی جی۔ سو اور کچھ سر کہنا چاہیں گے کہ نیکسٹ آپ کی جو کلاس ہے اس میں آپ یہ چیزیں— / بالکل میں ایڈ کروں گا انشاءاللہ۔ / اپنے لیکچر کے ریکوائرمنٹ کے اکارڈنگ جو بھی آپ اس میں بچوں کو دے سکتے ہیں۔ / بالکل انشاءاللہ نیکسٹ کلاس میں میں جو چارٹ وغیرہ ہیں یا فلیش کارڈ کا جو بھی ہوگا انشاءاللہ میں اس کو استعمال کر کے زیادہ وسیع اوپن اینڈڈ کوسچنز جو ہے نا میں اس کو اپلائی کروں گا انشاءاللہ۔", "quote_en": "Coach: Would you like to say what, in your next class, you will... Teacher: Of course, I will add it, God willing. Coach: Whatever fits your lesson. Teacher: In the next class I will use the chart or flashcard and apply wider open-ended questions with it.", "why": "Instead of ending on thanks, the coach leaves a gap for the teacher to say what they will do, and the teacher names when (next class), what (chart or flashcard) and how (wider open questions). Adding a date for the coach to see it would make this a 3.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "ddbaa7d68e2_ict4_07", "file": "clips/ddbaa7d68e2_ict4_07.mp3", "dur": 38.5, "kind": "strength", "dimension": "coach_questioning_and_dialogue", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 03", "title": "Paraphrasing the teacher's own concern", "quote_original": "یعنی آج اردو کا تھا، نیکسٹ آپ آئیں گی تو پھر میں میتھ کا بھی دوں گا، کیونکہ میں میتھ نہیں پڑھ سکتا، میں اردو پڑھا رہا ہوں۔ تو اس میں، ام، ایک تو یہ تھا کہ بچے تھوڑے ہچکچا رہے تھے۔ یعنی یہ مزید میں اس میں گنجائش ہے کہ بچوں کو جو چیز، ام، اس طرح میں آپ کے سامنے پکچرائز کراؤں، بچے اس میں سنسیئر ہوں اور حقیقی رنگ دیں، دیں آپ کو۔ یعنی صحیح بات بتائیں، یعنی پتہ چلے کہ— / اعتماد ان میں زیادہ ہو۔ / اعتماد زیادہ ہو۔ / یعنی جس طرح آج کانفیڈنس تھوڑا سا بچے ہیزیٹیٹ کر رہے تھے، اس میں آپ چاہ رہے ہیں بہتری ہو۔ تو یہ آپ کو کمی لگ رہی ہے۔ / جی۔", "quote_en": "Teacher: Today it was Urdu... the children were a bit hesitant; there is room for them to take part sincerely and bring it to life. Coach: More confidence in them. Teacher: More confidence. Coach: So today the children hesitated, and you want their confidence to improve; that is the gap you see. Teacher: Yes.", "why": "The teacher struggles to put the gap into words; the coach offers one word, then paraphrases the whole point back and checks it. The rest of the debrief builds on the teacher's goal, not the coach's. Paraphrase is rare in this group.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "d3b7ba94851_ict4_08", "file": "clips/d3b7ba94851_ict4_08.mp3", "dur": 34.6, "kind": "missed_opportunity", "dimension": "coach_questioning_and_dialogue", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 04", "title": "Asked twice, then moved on", "quote_original": "مطلب بچوں کو ایجنسی پسند ہے، ظاہر ہے وہ اپنی وائس کو پہنچانا چاہتے ہیں، کوشش کرتے ہیں اس چیز کو۔ اچھا، کوئی چیز ایسی، سر، جو آج آپ کلاس میں کروانا چاہ رہے ہوں اور نہیں کروا سکے، یا آپ دیکھتے ہیں کہ اگر آپ وہ چیز آج کلاس میں کرواتے تو لرننگ آؤٹ کمز بہتر ہو سکتے تھے؟ / نہیں، لیسن پلان کو ہی فالو کیا، اور اسی پہ ہی بچوں کو صحیح ہو گیا۔ / کوئی ایسی چیز نہیں ہے آپ کو لگتا کہ آپ اس میں آج لیک کر گئے، یا کروانا چاہ رہے تھے، یا اس کو مزید کسی اور طریقے سے، سٹریٹجی سے بہتر کیا جا سکتا تھا؟ / نہیں، بس ٹھیک ہو کر گیا۔ اور پریکٹس اب بھی بچے کریں گے گھر پہ، ان شاء اللہ تو اور ان کا اچھا امپروو ہو جائے گا۔", "quote_en": "Coach: Is there anything you wanted to do today and could not, which would have improved learning? Teacher: No, I followed the lesson plan and the children got it. Coach: Nothing you feel fell short, or could have been done better with another strategy? Teacher: No, it went fine. The children will practise at home, God willing.", "why": "The teacher closes the door twice and the coach then delivers a long list of improvements alone. When a cold open question gets 'nothing', the rubric's context notes say to scaffold: point to a moment the coach saw.", "better_move": "Do not repeat the same question. Point to one moment and ask about the students: 'When you asked what D stands for and a student said division, what do you think that student understood about the order of steps? What could you have asked next?'", "better_move_local": "ایک ہی سوال دوبارہ نہ پوچھیں، کسی ایک لمحے کی طرف اشارہ کریں: 'جب پوچھا گیا کہ ڈی کا مطلب کیا ہے اور ایک بچے نے کہا ڈویژن، تو آپ کے خیال میں اس بچے کو سٹیپس کی ترتیب کی کتنی سمجھ تھی؟ اس کے بعد اس سے کیا پوچھا جا سکتا تھا؟'", "lang": "ur", "rtl": true}, {"key": "d1e8db497be_ict4_09", "file": "clips/d1e8db497be_ict4_09.mp3", "dur": 37.9, "kind": "missed_opportunity", "dimension": "tone_and_psychological_safety", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 44", "title": "A quiz that felt like judgement", "quote_original": "Yes، میں آپ سے نا تھوڑا سا lesson plan کے متعلق پوچھوں گا، آپ کا کوئی تعارف ہے اس متعلق کہ اس میں کیا کیا حصے ہوتے ہیں، کون کون سی چیزیں، جب recording ہو بھی رہی ہو، teacher خود بھی کر رہے ہوں اور جو observer بھی آ کے دیکھتا ہے، تو اس میں کیا کیا دیکھا جا رہا ہوتا ہے؟ تھوڑا تو کوئی idea وغیرہ نہیں تو میں excuse کرتا ہوں۔ / بس آپ نے تو مجھے ہی دیکھا کہ بھئی میں کس طرح پڑھا رہی ہوں ان کو۔ یہ آپ نے زیادہ judgement کی ہو رہی ہے۔ دوسری بات یہ ہے کہ بچوں کا بھی دیکھا آپ نے، کیونکہ میں نے کوئی اشارہ نہیں کیا، کوئی کچھ نہیں کہا، وہ خود ہاتھ کھڑا کر رہے تھے کہ ہم آئے، ہم مطلب پوری کلاس ہی تیار تھی لکھنے کے لیے۔ ظاہر ہے کوئی پوری کلاس کو تو بندہ بلا نہیں سکتا، چند ایک کو ہی بندہ بلا سکتا ہے۔", "quote_en": "Coach: Let me ask about the lesson plan: do you know what parts it has, and what the recording and the observer are looking at? If you have no idea, excuse me. Teacher: You only looked at how I was teaching; this is more judgement. You also saw the children: I gave no signal, they raised their hands themselves, the whole class was ready to write. Obviously you cannot call the whole class, only a few.", "why": "A test question about lesson-plan parts makes the teacher feel judged, and they say so. The coach moves on to how the AI score counts words, so the teacher's reaction and their good point about eager students are lost.", "better_move": "Stop and respond to what the teacher said before going on: 'You are right, I was watching the children too, and almost every hand went up. That is exactly what I want to think about with you: when only a few can come to the board, how could every child show you their sentence?'", "better_move_local": "آگے بڑھنے سے پہلے رکیں اور ٹیچر کی بات کا جواب دیں: 'آپ کی بات بالکل ٹھیک ہے، بچوں پر بھی نظر تھی، تقریباً سب کے ہاتھ اٹھے ہوئے تھے۔ آپ کے ساتھ یہی سوچنا ہے: جب بورڈ پر صرف چند بچے آ سکتے ہیں تو ہر بچہ اپنا جملہ آپ کو کیسے دکھا سکتا ہے؟'", "lang": "ur", "rtl": true}, {"key": "d2149d4dbfc_ict4_11", "file": "clips/d2149d4dbfc_ict4_11.mp3", "dur": 29.2, "kind": "missed_opportunity", "dimension": "practice_or_modelling", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 13", "title": "New strategy, never tried aloud", "quote_original": "Exactly، exactly۔ ٹھیک ہے، that's، that's great۔ اور ایک ہمارے پاس strategy تھی، اس کو ہم کہتے ہیں all student check for understanding۔ / Okay۔ / All student check for understanding کا مطلب یہ ہے کہ جس طرح آپ نے independent task دیا ہے، and if you have a big class where آپ ہر بچے سے answer نہیں لے سکتے، time لگتا ہے، تو آپ یوں کر سکتے ہیں کہ آپ نے few volunteers سے، جس طرح آپ نے بچوں سے سوال کیا۔ / Yes, monitors۔ / ہاں، ان سے آپ نے جواب لیا، اس کے بعد ان کو آپ نے بولا کہ آپ اپنے آگے اور پیچھے والے بچوں کے answers چیک کر لو۔ / جی۔ / Right؟ یعنی just to confirm۔ / Exactly۔ مجھے کبھی اس میں یہ activity نہیں کروائی۔", "quote_en": "Coach: We have a strategy called all-student check for understanding. In a big class where you cannot take every child's answer, you take a few volunteers' answers, then tell them to check the answers of the children in front of and behind them, just to confirm. Teacher: Exactly. I have never done this activity.", "why": "The teacher says plainly that the strategy is new to them. That is the moment the rubric's ideal arc calls for modelling and rehearsal, but the coach adds a second strategy instead. 43 of 62 debriefs have no modelling or rehearsal.", "better_move": "'You have never done this, so let's try it now. I am your class and the four minutes are up. What exactly will you say?' Let the teacher say it, give one quick tip (for example, name who checks whom), and ask them to say it once more.", "better_move_local": "'آپ نے یہ پہلے کبھی نہیں کروایا، تو چلیں ابھی آزما کر دیکھتے ہیں۔ فرض کریں میں آپ کی کلاس ہوں اور چار منٹ پورے ہو گئے ہیں۔ اب بچوں سے بالکل کیا کہا جائے گا؟' ٹیچر کو کہنے دیں، پھر ایک چھوٹا سا مشورہ دیں، جیسے کون کس کی کاپی چیک کرے گا، اور کہیں کہ ایک بار پھر کہہ کر دکھائیں۔", "lang": "ur", "rtl": true}, {"key": "d2419018929_ict4_12", "file": "clips/d2419018929_ict4_12.mp3", "dur": 41.0, "kind": "missed_opportunity", "dimension": "purpose_and_relationship_opening", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 57", "title": "Framing the visit as app-checking", "quote_original": "ठीक, ठीक, ठीक। तो पहले आपके observation नहीं हुई ना, तो मैं आपको इसका वो बता देता हूँ, इसका format basically ये है, आप लोग अभी अपना DC कर रहे हो ना, Digital Coaching Website, तो इस तरह जब coaches आते हैं, observe करते हैं, तो उसका primarily मकसद ये होता है कि अगर उसमें कोई issue हो ना, अगर app में कोई issue आ रहा है, और automatically वो आपके कुछ चीज़ों को ठीक से mark नहीं कर रहा, तो फिर human coaches उसको देखते हैं, क्योंकि हम बैठे होते हैं, तो हम देखते हैं कि क्या वाकई वो चीज़ हुई कि नहीं हुई। Maybe ऐसी कुछ चीज़ें हो रही हों, लेकिन जाहिर सी बात है, वो आवाज़ से पता नहीं चलता, ठीक? तो then we—", "quote_en": "Coach: Since this is your first observation, let me explain the format. You are doing your digital coaching, so when coaches come and observe, the main purpose is that if the app has an issue and is not marking some things correctly, human coaches check whether it really happened, because we are sitting there. Some things cannot be known from the voice, right?", "why": "For a teacher's first ever observation, the coach explains the visit as checking the app's marking. That frames the coach as an auditor before a word about the lesson; later in the debrief the coach asks for the teacher's scores. Score or app talk appears in 6 of 62 debriefs.", "better_move": "'This visit is for you, not for the app. I am here to help with your teaching, and together we will pick one thing for you to try. Before I say anything, how did the lesson feel to you?'", "better_move_local": "'یہ وزٹ آپ کے لیے ہے، ایپ کے لیے نہیں۔ یہ آپ کی ٹیچنگ میں مدد کے لیے ہے، اور ہم مل کر ایک ایسی چیز چنیں گے جسے آزمایا جائے۔ میرے کچھ کہنے سے پہلے بتائیں، آج کا سبق آپ کو کیسا لگا؟'", "lang": "ur", "rtl": true}, {"key": "d82e7e79cba_ict4_13", "file": "clips/d82e7e79cba_ict4_13.mp3", "dur": 40.4, "kind": "missed_opportunity", "dimension": "concrete_action_step", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 58", "title": "Dropping the teacher's own diagnosis", "quote_original": "زبردست۔ اچھا میم، اس کے علاوہ میں جو ہے، آپ، میرا جو آپ کے لیے فیڈبیک ہے، وہ یہی ہے۔ میں آپ کو یہی کہوں گی کہ آپ نے لیسن پلان کو، سب کو، سارے جو کمپوننٹس ہیں نا لیسن پلان کے، آپ نے کوشش کرنی ہے آپ نے ان کو فالو کرنا ہے اپنی کلاس میں۔ لیسن پلان کا کوئی بھی کمپوننٹ مس نہیں ہونا چاہیے۔ تو تاکہ آپ کی اسکورنگ بھی امپروو ہو، اور ساتھ ساتھ بچوں کی جو لرننگ ہے وہ بھی امپروو ہو۔ سو میرا آپ کے لیے یہی فیڈبیک ہے کہ آپ نے اگلی کلاس میں لیسن پلان کو فالو کرنا ہے۔ جیسے آج آپ نے گائیڈڈ پریکٹس کرائی، لیکن انڈیپینڈنٹ پریکٹس مس ہو گئی تھی۔ تو اگلی کلاس میں اب آپ نے کوشش کرنی ہے کہ آپ نے انڈیپینڈنٹ پریکٹس بھی بچوں کو کرانی ہے، تاکہ بچے خود سے کام کو اکیلے کر سکیں، تاکہ پھر وہ بچوں کی پریشر مت لیں۔", "quote_en": "Coach: Great. My feedback for you is this: try to follow all the components of the lesson plan in your class. No component should be missed, so that your scoring improves and the children's learning improves too. Today you did guided practice but independent practice was missed, so in the next class try to have the children do independent practice too, so they can work alone.", "why": "Moments earlier the teacher explained the real problem: 58 very young children, a brand-new concept, restlessness. The coach sets that aside and issues a general 'follow every component', tied first to the teacher's score. The step is right in direction but not built for this class.", "better_move": "Build on what the teacher just said: 'You told me there are 58 small children and the topic was new. With that many, what is one short task each child could do alone for three minutes after guided practice? What will you say to start it?' Then have the teacher say it aloud.", "better_move_local": "ٹیچر کی ابھی کہی ہوئی بات سے آگے بڑھیں: 'آپ نے بتایا کہ 58 چھوٹے بچے ہیں اور سبق نیا تھا۔ اتنے بچوں کے ساتھ، گائیڈڈ پریکٹس کے بعد ایسا کون سا چھوٹا کام ہے جو ہر بچہ تین منٹ اکیلے کر سکے؟ شروع کرتے وقت بچوں سے کیا کہا جائے گا؟' پھر ٹیچر سے کہیں کہ بول کر سنائیں۔", "lang": "ur", "rtl": true}, {"key": "d186e35c273_ict4_14", "file": "clips/d186e35c273_ict4_14.mp3", "dur": 23.3, "kind": "missed_opportunity", "dimension": "commitment_and_follow_up", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 24", "title": "A good target, left unfixed", "quote_original": "So next اس میں ہمارا target کیا ہوگا کہ؟ / ہم نے مطلب اس میں دونوں کو جو task دینا ہے نا، تھوڑا سا opposite دے کے، تو پھر ہم نے جو ہے وہ کرنا ہے۔ اگر میرا topic ایسا ہے تو اس میں میں تھوڑی activity کو ایسا بناؤں کہ جو کہ میرا اس میں ٹھیک ہے، ہر گروپ کو میں ایک الگ دے دوں، اس سے ان کی learning بھی ہو گی، اور پھر مجھے بھی یہ ہو جائے گا کہ واقعی مجھے سمجھ آ گئی۔ / ایسا ہی ہے۔ / ٹھیک ہے۔", "quote_en": "Coach: So next, what will our target be? Teacher: We have to give the two neighbours slightly opposite tasks. If my topic allows, I will make the activity so each group gets a different one; they will learn, and I will know they really understood. Coach: That's right. Teacher: OK.", "why": "The coach asks exactly the right question and the teacher answers with their own idea, which is better than most closes in this group. But it stops at 'that's right': no lesson, no day, no exact words, and no plan to look at the result. 59 of 62 debriefs set no follow-up.", "better_move": "'Good, that is your target. Which lesson this week will you try it in? Say to me exactly what you will tell the two children sitting together. I will come next Thursday and we will look at their notebooks together.'", "better_move_local": "'بہت اچھا، یہی آپ کا ٹارگٹ ہے۔ اس ہفتے کس سبق میں یہ آزمایا جائے گا؟ ساتھ بیٹھے دو بچوں سے جو بات کہی جائے گی، وہ بالکل ویسے ہی مجھے کہہ کر سنائیں۔ اگلی جمعرات ملاقات ہوگی اور ہم مل کر ان کی کاپیاں دیکھیں گے۔'", "lang": "ur", "rtl": true}, {"key": "db5cf992bf3_ict4_15", "file": "clips/db5cf992bf3_ict4_15.mp3", "dur": 39.8, "kind": "missed_opportunity", "dimension": "focus_on_one_growth_area", "programme": "ict", "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 16", "title": "A new priority in the last minute", "quote_original": "ابھی فی الحال فوکس صفائی پہ کریں۔ ان کو یہ چیز اس پہ لائیں کہ آپ نے زمین پہ گند بالکل نہیں گرانا۔ / بالکل۔ / وہ صرف آپ کے پیریڈ میں نہیں، ان کی اتنی ہیبٹ بنوا دیں کہ یہ ہر پیریڈ کو فالو کریں۔ اور پھر آپ نے اس چیز کو بھی دیکھنا ہے کہ جو جو ٹیچرز کلاس میں جا رہی ہیں، اور اگر وہاں اس میں یہ نہیں کر رہے تو آپ نے ان کو بات ضرور کرنی ہے۔ ٹیچر سے بھی بات کرنی ہے، بچوں سے بھی بات کرنی ہے کہ میری ٹیچر میں، میرے پیریڈ میں تو آپ نے اتنا اچھا بیہیو کیا، تو اس میں کیا ہو گیا؟ اس میں تو آپ کے نمبر کٹ گئے، آپ کے پیچھے چلے گئے۔ تو اب میں سب، سب پیریڈ میں دیکھوں گی۔ جب بھی آؤں گی کلاس میں دیکھوں گی کس کے ٹیبل کے نیچے، ڈیسک کے نیچے گند پڑا ہوا ہے۔ تو اس چیز پہ تھوڑا سا ورکنگ کریں، تھوڑا ایپریشیٹ زیادہ کریں، تو یہ چیز بھی ان شاء اللہ ٹھیک ہو جائے گی ان کی۔ ٹھیک ہے؟ / ٹھیک ہے جی۔", "quote_en": "Coach: For now, focus on cleanliness: get them to never drop litter on the floor. Teacher: Of course. Coach: Not only in your period; build the habit so they follow it in every period. And check the other teachers who come into the class; if it is not happening there, talk to them, and to the children: in my period you behaved so well, what happened here? Your marks were cut. I will check every period; whenever I come I will look under the desks for litter. Work on this a little, appreciate more, and it will be fine. OK? Teacher: OK.", "why": "The debrief had built one good step (rewards and named praise for four inattentive boys). In the final minute the coach switches the focus to cleanliness and adds monitoring other teachers, so the teacher leaves with three jobs and no single one rehearsed or committed to.", "better_move": "Close on the step already agreed and leave cleanliness for another visit: 'So our one thing is the four boys. Tomorrow, when they sit and listen, you name them and give a small reward. What will you say to them at the start of the period? That is what I will look for next time.'", "better_move_local": "اسی ایک قدم پر بات ختم کریں جو طے ہو چکا، صفائی کسی اور وزٹ کے لیے رکھیں: 'تو ہماری ایک بات وہ چار بچے ہیں۔ کل جب وہ بیٹھ کر سنیں تو ان کا نام لے کر تعریف کریں اور چھوٹا سا انعام دیں۔ پیریڈ کے شروع میں ان سے کیا کہا جائے گا؟ اگلی بار یہی دیکھا جائے گا۔'", "lang": "ur", "rtl": true}, {"key": "d2d711b9318_punjab_00", "file": "clips/d2d711b9318_punjab_00.mp3", "dur": 33.5, "kind": "strength", "dimension": "teacher_self_reflection", "programme": "punjab", "programme_label": "Punjab", "coach": "PB Coach 29", "title": "Your view first, then my feedback", "quote_original": "کوچ: اچھا میم، آپ کا لیسن میں نے آبزرو کیا ہے۔ بہت اچھی کلاس تھی آپ کی۔ اپنا فیڈبیک دینے سے پہلے، لیکن میں آپ سے دو سوال پوچھنا چاہتی ہوں۔ میں چاہتی ہوں آپ ان کا جواب دے دیں پہلے، پھر میں اپنا فیڈبیک دوں گی۔ اچھا، ایک تو یہ مجھے آپ بتائیں کہ آج کا جو آپ کا لیسن تھا، اس میں آپ کیا سمجھتی ہیں کہ سب سے اچھی بات کیا تھی آپ کے لیسن میں؟ / استاد: میڈم، آج کے لیسن میں یہ چیز اچھی تھی کہ بچے نے فیڈبیک اچھا دیا ہے، ساتھ ساتھ اس کا رسپانس بھی اچھا تھا۔ اور جو علامہ اقبال کے بارے میں بتایا تھا، وہ بھی بچے کو بہت اچھی طرح سے سمجھ آ گئی ہے، اور مشاعر کی مثال سے اس کو سمجھ آ گئی ہے۔", "quote_en": "Coach: I observed your lesson; it was a very good class. Before I give my feedback I want to ask you two questions. I'd like you to answer them first, then I'll give mine. Tell me, what do you think was the best thing in today's lesson? / Teacher: In today's lesson the children gave good feedback and responded well. And what I taught about Allama Iqbal, the children understood it very well through the mushaira example.", "why": "The coach says out loud that the teacher will speak first and then keeps that promise. The teacher answers with a real example from the lesson. This simple opening is used by one coach in 4 of 4 debriefs and by nobody else.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "da05b46d35e_punjab_01", "file": "clips/da05b46d35e_punjab_01.mp3", "dur": 24.1, "kind": "strength", "dimension": "tone_and_psychological_safety", "programme": "punjab", "programme_label": "Punjab", "coach": "PB Coach 29", "title": "Making 'what could be better' safe", "quote_original": "کوچ: بالکل ٹھیک ہے۔ اچھا، ایک چیز اور، اگر آپ سمجھتی ہیں کہ کوئی ایسی چیز جو— ہوتا ہے نا، کبھی کبھار ہم بعد میں ذہن میں آتی ہے ٹیچر کے— کہ اچھا اس چیز کو ایسے نہیں، ایسے کروا لیتے تو وہ زیادہ بہتر ہو سکتا تھا۔ کبھی بعد میں آتی ہے دماغ میں، انسان ہے، ظاہر ہے اس وقت سکپ ہو جاتی ہے۔ آپ سمجھتی ہیں کہ آج کے لیسن کے اندر کوئی بھی ایسی چیز— اگر آپ سمجھتی ہیں تو— کوئی ایسی چیز تھی جو آپ سمجھتی ہیں مزید بہتر ہو سکتی تھی؟", "quote_en": "Coach: Right. One more thing. It happens, doesn't it, that sometimes a thought comes to a teacher afterwards: if I had done this differently it would have been better. It comes to mind later; we're human, of course it gets missed in the moment. Do you think there was anything in today's lesson that could have been better?", "why": "Before asking about weaknesses, the coach says that every teacher has second thoughts afterwards. That makes it easy for the teacher to admit something without losing face, which matters where visits are often read as inspection.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "d2298b95102_punjab_02", "file": "clips/d2298b95102_punjab_02.mp3", "dur": 33.5, "kind": "strength", "dimension": "evidence_from_the_lesson", "programme": "punjab", "programme_label": "Punjab", "coach": "PB Coach 30", "title": "Asking why the class said 'yes'", "quote_original": "کوچ: ٹھیک ہے۔ اچھا میم، مجھے یہ بتائیے گا کہ جب کلاس کے دوران آپ نے بچوں سے سوال کیا، اور وہ سوال یہ تھا کہ دوسروں کا، دوسرے کی پسند کا خیال رکھنا کیوں ضروری ہے، اور یا پھر اس طرح ہوا کہ جب آپ نے کیوں پوچھا، کہ مطلب کیوں یہ ضروری کیوں ہے، یا اس طرح کے جو آپ سوال کرتے ہیں، تو بچوں نے ایک ساتھ جواب دیا جی ہاں۔ تو آپ نے، لائک، اس ٹائم کیا سوچا تھا، یا آپ کو کیا لگ رہا ہے کہ بچوں نے جی ہاں کا جواب دیا، یہ کیوں دیا، ان کو انڈرسٹینڈنگ تھی اس بات کی، یا انہوں نے ویسے ہی کہہ دیا تھا؟", "quote_en": "Coach: OK. Ma'am, tell me: during the class you asked the children 'why is it important to care about what others like?', and when you asked 'why', the children all answered together 'yes'. What did you think at that moment? Why do you think they said 'yes'? Did they understand it, or did they just say it?", "why": "The coach replays one exact moment, including what the children said, and asks the teacher to interpret it instead of giving a verdict. The teacher then works out the problem themself (the children gave no reasons).", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "d19409cb26d_punjab_03", "file": "clips/d19409cb26d_punjab_03.mp3", "dur": 26.8, "kind": "strength", "dimension": "tone_and_psychological_safety", "programme": "punjab", "programme_label": "Punjab", "coach": "PB Coach 32", "title": "Normalising a teacher's own mistake", "quote_original": "کوچ: اتنا سا ہم ان کو margin دے دیتے ہیں۔ Because ہم اتنے بڑے ہیں، being an adult، but still we get confused and nervous اگر کوئی ہمیں observe کرے۔ / استاد: اور باقی یہ ہے کہ تھوڑا سا، ہاں، میں خود بھی بعض اوقات confuse ہو جاتی ہوں۔ کہیں پہ، جیسے شروع میں میں نے یہاں پہ sign ہی غلط لگا دیا تھا۔ / کوچ: لیکن which is good کہ آپ نے خود ہی سے اپنی mistake بھی recognized— / استاد: ہاں، لیکن وہ میں نے فوراً realize کیا کہ میں نے sign— لیکن وہ بچوں کے لیے confusing ہوتا ہے۔ / کوچ: Exactly۔", "quote_en": "Coach: We give them that much margin, because even as adults we get confused and nervous if someone observes us. / Teacher: And also, yes, sometimes I get confused myself. For example, at the start I put the wrong sign here. / Coach: But it's good that you recognised your own mistake. / Teacher: Yes, I realised straight away, but it is confusing for the children. / Coach: Exactly.", "why": "The coach treats nerves under observation as normal, and the teacher then admits a real error without being asked. The coach credits the self-correction, and the teacher links it to the children's confusion. This is what a safe debrief sounds like.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "dc32e19f830_punjab_04", "file": "clips/dc32e19f830_punjab_04.mp3", "dur": 21.4, "kind": "strength", "dimension": "coach_questioning_and_dialogue", "programme": "punjab", "programme_label": "Punjab", "coach": "PB Coach 32", "title": "A two-word probe: 'In what way?'", "quote_original": "استاد: आज का लेसन ये है कि बच्चे सारे cooperate थे, ना? सारे बच्चे बीच में, सारे— / کوچ: सबकी participation थी, exactly. और इसको मजीद, आपको लगता है कि बेहतर बनाया जा सकता था किसी? / استاد: Yes. / کوچ: किस तरह से? / استاد: मजीद ये है कि बच्चे जितना खुद से, अंदर से निकालेंगे, ना? अभी तो ये टाइम थोड़ा सा, बच्चे को सोचने की टाइमिंग जब ज़्यादा दी जाती है, तो ज़्यादा चीज़ें उसके दिमाग से निकलती हैं।", "quote_en": "Teacher: In today's lesson all the children cooperated, didn't they? All the children... / Coach: Everyone participated, exactly. And do you think it could have been made better in any way? / Teacher: Yes. / Coach: In what way? / Teacher: The more children bring out from within themselves... when a child is given more time to think, more comes out of their mind.", "why": "When the teacher answers only 'yes', the coach asks one short follow-up instead of filling the gap. The teacher then names their own growth area (more thinking time). Play on to 01:06.5 to hear the cost: the coach says 'sahi, bilkul' and switches to their own topic, and the thinking-time idea is never used.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "d2a770ca16b_punjab_05", "file": "clips/d2a770ca16b_punjab_05.mp3", "dur": 35.0, "kind": "strength", "dimension": "evidence_from_the_lesson", "programme": "punjab", "programme_label": "Punjab", "coach": "PB Coach 23", "title": "Linking grouping to one child's struggle", "quote_original": "استاد: تو پھر میں جب دیکھتی ہوں نا کہ کتنی انڈرسٹینڈنگ کس کس کی ہو رہی ہے، تو پھر آپ— میں گروپس بنا دیتی ہوں، مجھے پتہ ہوتا ہے کہ اس کو بہت اچھا آ رہا ہے، اس کو تھوڑا آ رہا ہے۔ لیکن نا، ہم نے تو صرف زیادہ اچھے والوں کو ہی ملا دیتی ہوں۔ یہ گروپ بھی بہت اچھے ہوتے ہیں۔ / کوچ: ہمم۔ / استاد: اب جیسے یہ ون، ٹو، تھری، فور، وہ لاسٹ ٹو اور یہ ٹو بچیاں۔ یہ چار بچیاں جو ہیں نا، ان کے ساتھ چار بچیاں میں اور بٹھاتی ہوں۔ / کوچ: پرفیکٹ ہے۔ یہ گروپس بھی بہت اچھے ہیں، کہ کسی کو نہیں آتا ہے، کسی کو آتا ہے۔ آپ نے دیکھا، اس بچی کو فائیو کا ٹیبل نہیں آتا تھا جب آپ نے پوچھا۔ آپ گروپ ورک کرواتی ہیں تو شاید جو اس کے ساتھ بیٹھی ہے نا، وہ اس کو کرواتی تو اس کو آ جاتا۔ یہ ہو سکتا ہے۔", "quote_en": "Teacher: When I see how much each child understands, I make groups; I know this one is doing very well, this one a little. These groups work well too. / Coach: Hmm. / Teacher: Like these: one, two, three, four, the last two and these two girls. With these four girls I seat four more. / Coach: Perfect. These groups are good, where someone knows and someone doesn't. You saw that girl did not know the 5 times table when you asked. If you do group work, maybe the girl sitting next to that girl would have helped, and that girl would have got it.", "why": "The coach listens to the teacher's reasons for grouping and then ties them to one observed moment: a located child who could not say the 5 times table. A general idea ('group work helps') becomes something the teacher saw happen.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "d0e3a0ed8b8_punjab_06", "file": "clips/d0e3a0ed8b8_punjab_06.mp3", "dur": 45.6, "kind": "strength", "dimension": "coach_questioning_and_dialogue", "programme": "punjab", "programme_label": "Punjab", "coach": "PB Coach 04", "title": "Saying the teacher's idea back first", "quote_original": "استاد: گروپنگ میں بچوں سے کوئسچنز زیادہ سے زیادہ کیے جا سکتے ہیں۔ گروپس میں بچوں کو کوئسچنز آج اگر ٹائم کم تھا، پیریڈ آف ہو گیا تھا، اینڈ میں کیا گیا یہ کام۔ تو اگر اسٹارٹ میں کیا جائے تو بچے خود ڈسکس کریں گے آپس میں، اور اس کے بعد مل کر گروپ سے بات کر کے، اور پھر مجھے میری بات کا جواب دیں گے، تو وہ زیادہ اچھا ہوگا۔ اس سے انہیں خود جو چیزیں سمجھنے میں زیادہ آسانی ہوگی۔ / کوچ: ٹھیک ہے، بہت اچھی بات کی ہے آپ نے۔ اور میرا خیال ہے کہ، جیسا آپ بتا رہی ہیں، کہ لیکچر کے اسٹارٹ میں ہمیں یہ کرنا چاہیے تاکہ بچوں کو زیادہ سے زیادہ ٹائم ملے۔ اس کے علاوہ، اگر ہم سبق کو کسی ایکٹیویٹی میں تبدیل کریں تاکہ بچوں کا انٹرسٹ بڑھے، تو وہ کیسا رہے گا؟", "quote_en": "Teacher: More questions can be given to children in groups. Today time was short and the period ended, so this was done at the end. If it is done at the start, the children will discuss among themselves, talk it over in the group and then answer me, which would be better. It will be easier for them to understand things themselves. / Coach: OK, you made a very good point. And I think, as you are saying, we should do this at the start of the lesson so children get as much time as possible. Besides that, if we turned the lesson into an activity to raise interest, how would that be?", "why": "The teacher names a specific change rooted in what happened (group questions came too late because the period ended). The coach restates it in their own words before adding anything. Paraphrasing like this was rare in the group; the next step would have been to make the teacher's idea the agreed step.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "d983d6de6b8_punjab_07", "file": "clips/d983d6de6b8_punjab_07.mp3", "dur": 30.1, "kind": "strength", "dimension": "concrete_action_step", "programme": "punjab", "programme_label": "Punjab", "coach": "PB Coach 26", "title": "A precise fix tied to one example", "quote_original": "کوچ: اچھا، آپ کا نا، میں پہلے لیسن پلان کی بات کروں۔ لیسن اچھا تھا آپ کا، لیکن اس میں ایک جو چیز تھی نا، وہ یہ تھی کہ آپ جو ایگزیمپل دے رہے ہیں نا، جیسے آپ نے ٹیبل کے لیے بلایا ان کو، \"بہائنڈ دی ٹیبل\"، تو پہلے ان کو یہ چیز تھوڑا سا گائیڈ کر لیں کہ آپ نے اس ٹیبل کے ریفرنس سے ہی جواب دینا ہے۔ / استاد: صحیح۔ / کوچ: کبھی آگے کھڑا کریں ٹیبل کے، کبھی پیچھے، کبھی دائیں، کبھی بائیں۔ تو پھر تاکہ ان کو پتہ— ہاں، تاکہ ان کو پتہ ہو کہ کس سیناریو میں پوچھ رہے ہیں۔ ایسے تو وہ \"آن دا گراؤنڈ\" بھی کہہ سکتے ہیں نا۔", "quote_en": "Coach: Let me start with the lesson plan. Your lesson was good, but there was one thing: in the example where you called children up for 'behind the table', first guide them that they must answer with reference to the table. / Teacher: Right. / Coach: Sometimes stand it in front of the table, sometimes behind, right, left, so they know which situation you are asking about. Otherwise they could just as well say 'on the ground'.", "why": "The step is small, visible and tied to the exact example used in class. The coach also explains why it matters: the children's 'wrong' answer ('on the ground') was a reasonable answer to an unclear question. A coach could check it in the next lesson at a glance.", "better_move": null, "better_move_local": null, "lang": "ur", "rtl": true}, {"key": "d4ee681d251_punjab_08", "file": "clips/d4ee681d251_punjab_08.mp3", "dur": 20.4, "kind": "missed_opportunity", "dimension": "purpose_and_relationship_opening", "programme": "punjab", "programme_label": "Punjab", "coach": "PB Coach 26", "title": "Opening with a verdict and a label", "quote_original": "کوچ: لیسن اچھا تھا، ٹاپک بھی ایسا تھا جس میں تمام سٹوڈنٹس ایکٹیولی پارٹیسپیٹ کرتے ہیں۔ لیکن کلاس جو ہے نا، ٹوٹلی ان ڈسپلن تھی۔ یہ لڑکوں کی تو مجھے سمجھ ہی نہیں آئی، پوری کلاس میں کیا کر رہے ہیں۔ اتنے بلنٹ فیسز انہوں نے اپنے بنائے ہوئے ہیں، کوئی موٹیویشن، کوئی فریش چہرہ نظر نہیں آ رہا تھا۔ ان کو ذرا جگاتی رہا کرو۔", "quote_en": "Coach: The lesson was good, and the topic is one where all students actively take part. But the class was totally undisciplined. I couldn't understand what these boys were doing in the whole class. They had such blank faces; no motivation, not one fresh face. Keep waking them up.", "why": "The first thing the teacher hears is a label ('totally undisciplined') and an order, with no greeting, no purpose and no question. The teacher spends the rest of the debrief defending themself (weak reading, gate duties) and no step is agreed.", "better_move": "Open with thanks and a purpose, then ask before judging: 'Thank you for letting me sit in. I'm here to help, not to check up on you. Before I say anything, how did today's lesson feel to you? What did you notice about the boys at the back?' Then give one observed fact instead of a label: 'I saw about six students standing or walking during the reading. What do you think was going on for them?'", "better_move_local": "کلاس میں بیٹھنے دینے کا شکریہ۔ میں آپ کی مدد کے لیے یہاں ہوں، جانچ کے لیے نہیں۔ کچھ کہنے سے پہلے آپ بتائیں، آج کا سبق آپ کو کیسا لگا؟ پیچھے بیٹھے لڑکوں کے بارے میں آپ نے کیا محسوس کیا؟ میں نے دیکھا کہ ریڈنگ کے دوران پانچ چھ بچے کھڑے ہو رہے تھے یا چل پھر رہے تھے۔ آپ کے خیال میں ان کے ساتھ کیا ہو رہا تھا؟", "lang": "ur", "rtl": true}, {"key": "d6ce26f84ed_punjab_09", "file": "clips/d6ce26f84ed_punjab_09.mp3", "dur": 20.1, "kind": "missed_opportunity", "dimension": "teacher_self_reflection", "programme": "punjab", "programme_label": "Punjab", "coach": "PB Coach 29", "title": "The teacher names the fix; coach moves on", "quote_original": "استاد: ام، یہ کہ میں نے ٹاپک، مطلب، ایک دم سے میرے مینٹل، مطلب، آ کے بتا دیا نا۔ لیکن میں پہلے ایسے، جیسے ایکٹیویٹی میں نے لاسٹ میں کی ہے نا، تو بچوں کو پہلے ایکٹیویٹی میں جب بتا دیتی ہوں، میں کہتی ہوں، آپ اس کو کیسے بتا سکتے ہو کہ یہ بڑا ہے، یہ چھوٹا ہے، اس طرح؟ / کوچ: بالکل صحیح ہے، بالکل صحیح ہے۔ کچھ اور ایڈ کرنا چاہتی ہیں؟", "quote_en": "Teacher: Um, that I told them the topic all at once. But usually, like the activity I did at the end, when I start with the activity first, I ask them: how can you tell that this one is big and this one is small? / Coach: Quite right, quite right. Anything else you'd like to add?", "why": "The teacher identifies their own growth area and even gives the question they would use, which is exactly what the rubric hopes for. The coach says 'quite right' and later gives a different, more general step ('ask open-ended questions'). This happened in 11 of 26 debriefs.", "better_move": "Take the teacher's idea and make it the step: 'You just put your finger on it. You'd rather start with a question like \"how can you tell this one is bigger?\" before telling them. Let's make that our one thing. What exact question will you ask in the first five minutes tomorrow? Say it to me as if I'm the class.'", "better_move_local": "آپ نے ابھی خود اصل بات پکڑ لی۔ آپ کا خیال ہے کہ ٹاپک بتانے سے پہلے سوال پوچھا جائے، جیسے 'کیسے پتہ چلے گا کہ یہ بڑا ہے؟'۔ چلیں یہی ہمارا ایک قدم ہے۔ کل پہلے پانچ منٹ میں بالکل کون سا سوال پوچھا جائے گا؟ مجھے ایسے بول کر سنائیں جیسے میں آپ کی کلاس ہوں۔", "lang": "ur", "rtl": true}, {"key": "dcf9ada74fc_punjab_10", "file": "clips/dcf9ada74fc_punjab_10.mp3", "dur": 19.6, "kind": "missed_opportunity", "dimension": "focus_on_one_growth_area", "programme": "punjab", "programme_label": "Punjab", "coach": "PB Coach 30", "title": "A real student concern left on the table", "quote_original": "استاد: سر، بچوں کی participation، بچے وہ جیسے آپ observe کے لیے بیٹھے تھے، تو وہ شاید fail کر رہے تھے، حالانکہ بچی کو آتا تھا، وہ منہ میں بڑبڑا رہی ہے، لیکن وہ اونچی آواز میں نہیں بول رہی۔ / کوچ: ٹھیک ہے۔ / استاد: تو بس میں یہی چاہتی ہوں کہ بچے تھوڑے confident ہو جائیں جب میرے سامنے وہ صحیح response دیتے ہیں، لیکن جب کوئی نیا بندہ آتا ہے تو وہ confuse ہو جاتے ہیں تھوڑے سے۔", "quote_en": "Teacher: Sir, the children's participation: with you sitting there to observe, they perhaps froze. The girl knew the answer, the girl was mumbling it, but the girl wouldn't say it out loud. / Coach: OK. / Teacher: So I just want the children to be a bit more confident. In front of me they give the right answer, but when someone new comes they get a little confused.", "why": "The teacher describes a specific student and a specific problem (knows the answer, will not say it aloud). The coach says 'OK' and, two minutes later, picks a different growth area (open-ended questions). This is the best debrief in the group, and it still misses this.", "better_move": "Stay with the teacher's concern: 'You've noticed something important. The girl knew it but only mumbled. What usually helps a shy child say an answer out loud in your class? What if every child first whispers the answer to a partner, and then you ask one pair to say it together?' Then agree that as the one step.", "better_move_local": "آپ نے بہت اہم بات نوٹ کی ہے۔ بچی کو جواب آتا تھا مگر وہ منہ میں بڑبڑا رہی تھی۔ آپ کی کلاس میں جھجکنے والا بچہ عام طور پر اونچی آواز میں کب بولتا ہے؟ اگر پہلے ہر بچہ اپنے ساتھی کو آہستہ سے جواب بتائے، پھر ایک جوڑی سے کہا جائے کہ مل کر بتائیں، تو کیسا رہے گا؟ چلیں یہی ہمارا اگلا قدم رکھتے ہیں۔", "lang": "ur", "rtl": true}, {"key": "d8f4d96ceac_punjab_11", "file": "clips/d8f4d96ceac_punjab_11.mp3", "dur": 29.2, "kind": "missed_opportunity", "dimension": "concrete_action_step", "programme": "punjab", "programme_label": "Punjab", "coach": "PB Coach 04", "title": "A ready-made step, waved goodbye", "quote_original": "استاد: بہت اچھا رہے گا۔ اس کے لیے ہم بچوں کو، اگر بورڈ پر ہم کوئسچن کرتے ہیں تو صرف ہم کوئسچن لکھ دیں گے، اور بچوں کو ایک ایک کر کے بلا لیں گے کہ آپ لوگ باری باری آ کے اس سوال کو حل کر دیں۔ تو اس طرح بچوں کو بولنے کا بھی، اور مطلب، کچھ کرنے کا بھی موقع مل جائے گا۔ / کوچ: چلیں، ویری گڈ۔ ٹھیک ہے، امید کرتا ہوں کہ آپ نیکسٹ لیکچر جو ہے بہت اچھا کریں گی۔ ان شاء اللہ ملتے ہیں نیکسٹ ویک۔", "quote_en": "Teacher: That would be very good. For that, when we do a question on the board, we'll just write the question and call the children one by one to come and solve it in turn. That way children get a chance to speak and to do something. / Coach: All right, very good. OK, I hope you'll do the next lesson very well. God willing, see you next week.", "why": "The teacher offers a concrete, observable move. The coach answers 'very good, see you next week', so it never becomes the agreed step: no lesson, no question chosen, nothing for the coach to look for next time.", "better_move": "Turn the teacher's idea into the step before closing: 'That's a clear step. So in tomorrow's maths lesson you'll write one question on the board and call children up one at a time. Which question will you write? How will you choose who comes up, so it isn't only the quick ones? On Thursday we'll look at how many different children came to the board.'", "better_move_local": "یہ بہت واضح قدم ہے۔ تو کل میتھ کے پیریڈ میں بورڈ پر ایک سوال لکھا جائے گا اور بچوں کو باری باری بلایا جائے گا۔ کون سا سوال لکھا جائے گا؟ اور کیسے چنا جائے گا کہ صرف تیز بچے ہی نہ آئیں؟ جمعرات کو ہم مل کر دیکھیں گے کہ کتنے مختلف بچے بورڈ پر آئے۔", "lang": "ur", "rtl": true}, {"key": "daea32a1fee_punjab_12", "file": "clips/daea32a1fee_punjab_12.mp3", "dur": 27.1, "kind": "missed_opportunity", "dimension": "evidence_from_the_lesson", "programme": "punjab", "programme_label": "Punjab", "coach": "PB Coach 32", "title": "'Involve the children more', but where?", "quote_original": "کوچ: ٹھیک ہے، آپ— مجھے لگ رہا ہے کہ آپ بہت زیادہ انرجی ابھی لگا رہی تھیں، بچوں کو اب زیادہ انوالو کریں۔ بچوں کی طرف سے زیادہ کریں، اور اپنے اوپر سے برڈن جو ہے نا، وہ کم کریں۔ بیکاز آپ کنٹینیوسلی— آپ کی جو، مطلب، آپ کی انرجی بہت اچھی تھی، بہت ہائی تھی، لیکن بچوں کی— مطلب، زیادہ ہم چاہتے ہیں کہ وہ چلیں، اور آپ کی اس ریسپانسبیلٹی کم ہو جائے۔ ہم نے آہستہ آہستہ شفٹ کرنی ہے ریسپانسبیلٹیز۔ سو یہ ساری چیزیں ہم بچوں سے بورڈ پہ لکھوا لیتی ہیں، بچوں سے آپس میں کروا لیتی ہیں کہ چلو دو منٹ میں— / استاد: میم، فرسٹ لیسن پہ ایسا جو میں نے وہ کی ہے۔", "quote_en": "Coach: OK, you... I feel you were putting in a lot of energy; now involve the children more. Let more come from the children's side and take the burden off yourself. Because you continuously... your energy was very good, very high, but we want the children to carry it and your share to go down. We have to shift responsibility gradually. So we have children write all this on the board, have them do it among themselves, 'go, in two minutes'... / Teacher: Ma'am, I did it that way in the first lesson.", "why": "The advice could fit any lesson: it names no moment and nothing students did. The teacher's interruption ('I did it that way in the first lesson') is a sign they feel misjudged, and the coach closes without asking about it.", "better_move": "Point to one moment and offer one small change: 'When the sentences went up on the board, you did all the writing yourself. In the next lesson, try one thing: call two children to write the answers while the rest check them. How would that work with this class?' Then follow up on the interruption: 'You said you did this in the first lesson. What happened then?'", "better_move_local": "جب بورڈ پر جملے لکھے جا رہے تھے تو سارا لکھنے کا کام آپ ہی کے ہاتھ سے ہو رہا تھا۔ اگلے سبق میں ایک چیز آزمائیں: دو بچوں کو بورڈ پر بلا کر جواب لکھوائیں اور باقی بچے چیک کریں۔ آپ کے خیال میں یہ اس کلاس میں کیسے چلے گا؟ اور آپ نے کہا پہلے سبق میں ایسا کیا تھا، تب کیا ہوا تھا؟", "lang": "ur", "rtl": true}, {"key": "dc87b97ef32_punjab_13", "file": "clips/dc87b97ef32_punjab_13.mp3", "dur": 27.2, "kind": "missed_opportunity", "dimension": "tone_and_psychological_safety", "programme": "punjab", "programme_label": "Punjab", "coach": "PB Coach 40", "title": "'No' to a real classroom constraint", "quote_original": "کوچ: ٹھیک ہے۔ پھر آپ نے جب کروا لیا، پھر آپ جب کارڈز پہ گئیں، ٹھیک ہے، وہ تھوڑی سی مجھے اس ایکٹیویٹی کی سمجھ نہیں آئی۔ میں اپنا پرسنلی بتاؤں نا؟ آپ نے بچوں کو ارینج کیا، کارڈز... اب وہ ایکٹیویٹی اگر بچے کر کے اگر خود ارینج ہو رہے ہوتے تو وہ زیادہ سوٹیبل ہوتا۔ / استاد: ہائیٹ کا ایشو آ رہا تھا، تو میں نے کہا تھا آپ کارڈ بورڈ کی اپنی ہائیٹ کے حساب سے کارڈ لے لیں۔ وہ اس وجہ سے۔ / کوچ: نہیں، اس میں مجھے یہ تھا کہ وہ بچے خود پک کرتے کارڈز۔ آپ کارڈز رکھتی۔ / استاد: ٹیبل پر رکھے تھے، میں نے...", "quote_en": "Coach: OK. Then, after that, when you went to the cards, I didn't quite understand that activity. Shall I tell you personally? You arranged the children, the cards... if the children had arranged themselves in that activity, it would have been more suitable. / Teacher: There was a height problem, so I told them to take a card according to their height. That's why. / Coach: No, what I meant was the children pick the cards themselves. You put the cards out. / Teacher: I had put them on the table...", "why": "The teacher gives a practical reason (the children's height) and the coach answers 'no' and repeats the point. In this debrief the teacher explains or defends a choice five or six times across six separate critiques, and the call ends with 'hope next time is better'.", "better_move": "Acknowledge the constraint, then solve it together: 'The height problem is real, thank you for explaining. How could the children still choose their own cards? What if the cards are on a low table, each child picks one, and the group decides who stands where?' Then make that the one step for the next lesson and drop the other five points.", "better_move_local": "قد والا مسئلہ واقعی ہوتا ہے، بتانے کا شکریہ۔ پھر بھی بچے خود کارڈ کیسے چن سکتے ہیں؟ اگر کارڈ نیچی میز پر رکھ دیں، ہر بچہ خود ایک کارڈ اٹھائے، اور گروپ مل کر طے کرے کہ کون کہاں کھڑا ہوگا، تو کیسا رہے گا؟ اگلے سبق کے لیے بس یہی ایک چیز رکھتے ہیں۔", "lang": "ur", "rtl": true}, {"key": "dfd81c4ee28_punjab_14", "file": "clips/dfd81c4ee28_punjab_14.mp3", "dur": 15.1, "kind": "missed_opportunity", "dimension": "commitment_and_follow_up", "programme": "punjab", "programme_label": "Punjab", "coach": "PB Coach 04", "title": "'Will you improve it?' 'Ji sir.'", "quote_original": "کوچ: ٹھیک ہو گیا۔ مطلب اب مزید آپ اس کو بہتر کرنے کے لیے کیا کریں گے؟ نیکسٹ ویک اگر میں دوبارہ آتا ہوں آپ کے پاس تو آپ اس کو مزید بہتر بنائیں گے، اپنے لیکچر کو؟ / استاد: جی سر۔ / کوچ: چلیں ٹھیک ہے، ان شاء اللہ ملتے ہیں اگلے ویک۔ Thank you so much.", "quote_en": "Coach: All right. So what will you do now to improve it further? Next week, if I come to you again, will you have improved it, your lesson? / Teacher: Yes sir. / Coach: OK then, God willing, see you next week. Thank you so much.", "why": "The coach starts with the right open question ('what will you do?') and then swaps it for a yes/no one. The teacher says only 'ji sir', so the debrief ends with no step, day or sign of success. Bare assent like this closed 6 of 26 debriefs.", "better_move": "Ask the open question and wait for the answer: 'Before I go, tell me in your own words: in which class and on which day will you try an activity, and what will the children be doing with their hands?' After the teacher answers: 'Good. Next Tuesday I'll come in that period, and we'll look at whether most children took part.'", "better_move_local": "جانے سے پہلے اپنے الفاظ میں بتائیں: کس کلاس میں اور کس دن ایکٹیویٹی کروائی جائے گی، اور اس میں بچے خود ہاتھ سے کیا کر رہے ہوں گے؟ ... بہت اچھا۔ اگلے منگل کو اسی پیریڈ میں ملتے ہیں، اور مل کر دیکھیں گے کہ کیا زیادہ تر بچوں نے حصہ لیا۔", "lang": "ur", "rtl": true}, {"key": "dc1905799d1_punjab_15", "file": "clips/dc1905799d1_punjab_15.mp3", "dur": 14.9, "kind": "missed_opportunity", "dimension": "practice_or_modelling", "programme": "punjab", "programme_label": "Punjab", "coach": "PB Coach 01", "title": "The step is dictated, never tried", "quote_original": "استاد: بچے خود آ کر بلیک بورڈ میں جوڑ دیں۔ / کوچ: بورڈ کے اوپر آ کے بچے لکھیں۔ نہیں، پہلے آپ لکھیں۔ / استاد: ہاں، پہلے بچے لکھیں۔ / کوچ: دو تین الفاظ آپ لکھیں، ان پہ توڑ کروائیں۔ / استاد: جی جی۔ / کوچ: ٹھیک ہے؟ بچے پڑھیں، پیچھے آپ کے۔ ٹھیک ہے؟ اس کے بعد بچوں سے پریکٹس، انڈیویجول پریکٹس۔", "quote_en": "Teacher: The children come and join the words on the blackboard themselves. / Coach: The children come and write on the board. No, you write first. / Teacher: Yes, children write first. / Coach: You write two or three words and have them break them up. / Teacher: Yes, yes. / Coach: OK? The children read after you. OK? After that, practice by the children, individual practice.", "why": "The teacher has a good idea. The coach corrects it ('no, you write first') and dictates the sequence with 'theek hai?' tags while the teacher says 'ji ji'. Nobody tries the first two minutes of that lesson, which is the knowing-doing gap the practice dimension is about. No teacher rehearsed a step in any of the 26 debriefs.", "better_move": "Build on the teacher's idea, then rehearse it on the spot: 'Good idea, children at the board. Let's try it now. Pretend I'm your class. Show me the first two minutes: which two words will you write, what will you say, and how will you call up the first child?' Give one tip (for example, 'say the child's name before the word, not after') and ask the teacher to try it once more.", "better_move_local": "اچھا خیال ہے، بچے خود بورڈ پر آئیں۔ چلیں ابھی آزما کر دیکھتے ہیں۔ فرض کریں میں آپ کی کلاس ہوں۔ پہلے دو منٹ کر کے دکھائیں: کون سے دو لفظ لکھے جائیں گے، کیا بولا جائے گا، اور پہلے بچے کو کیسے بلایا جائے گا؟ ... اچھا، ایک چھوٹی سی بات: لفظ سے پہلے بچے کا نام لیں۔ چلیں ایک بار پھر کر کے دیکھیں۔", "lang": "ur", "rtl": true}, {"key": "da47434283f_tanzania_00", "file": "clips/da47434283f_tanzania_00.mp3", "dur": 11.6, "kind": "strength", "dimension": "purpose_and_relationship_opening", "programme": "tanzania", "programme_label": "Tanzania", "coach": "TZ Coach 39", "title": "Not here to criticise, here to help", "quote_original": "[name], nashukuru kwa kunikaribisha darasani kwako. Lengo letu siyo kukosoa; lengo letu ni kusaidiana katika ufundishaji. Unafikiri ni sehemu gani katika somo lako umeifanya vizuri?", "quote_en": "[name], thank you for welcoming me to your classroom. Our aim is not to criticise; our aim is to help each other in teaching. Which part of your lesson do you think you did well?", "why": "In 11 seconds the coach says out loud that this is not an inspection and hands the first judgement of the lesson to the teacher. Only 6 of 58 teachers speak first; this is how it starts.", "better_move": null, "better_move_local": null, "lang": "sw", "rtl": false}, {"key": "df3c6cb5241_tanzania_01", "file": "clips/df3c6cb5241_tanzania_01.mp3", "dur": 28.4, "kind": "strength", "dimension": "evidence_from_the_lesson", "programme": "tanzania", "programme_label": "Tanzania", "coach": "TZ Coach 41", "title": "Praise that names group 7's sentence", "quote_original": "Mwalimu, nakushukuru kwa kukaribisha darasani. Asante kwa kunikaribisha. Lengo langu la kuja darasani ni tusaidiane kwa ajili ya hawa watoto. Nilipenda Mwalimu kunirejea kwa kazi ya kundi la 7, walipowasilisha sentensi: \"Bahari yetu ni shwari\" kabla ya kuendelea na shughuli mpya. Hali hiyo nilipenda sana. Sasa, ningependa nikuulize swali moja.", "quote_en": "Teacher, thank you for welcoming me to the class. My purpose in coming is that we support each other for the sake of these children. I liked that you went back to group 7's work, when they presented the sentence 'Our sea is calm', before moving on to the new activity. I liked that a lot. Now I would like to ask you one question.", "why": "The praise names the group, the exact sentence pupils produced and the teacher's move, so the teacher knows precisely what to repeat.", "better_move": null, "better_move_local": null, "lang": "sw", "rtl": false}, {"key": "d69f6fd2bc8_tanzania_02", "file": "clips/d69f6fd2bc8_tanzania_02.mp3", "dur": 31.4, "kind": "strength", "dimension": "coach_questioning_and_dialogue", "programme": "tanzania", "programme_label": "Tanzania", "coach": "TZ Coach 14", "title": "How many, exactly? A probe that works", "quote_original": "Kabla sijasema ni kina nani walikuwa wanaunda maneno vizuri, nirudi hapo uliposema kwamba walikuwa wanarudia. Kuna neno kama \"si\", walikuwa wengi wanashindwa wakasema \"sikia\". Na ndiyo hilo ambalo lilikuwa liliwashinda wengi. Lakini pia wapo ambao waliweza kulitamka. Sasa, ambao sijui unataka niwataje kwa majina? / Sio lazima, ni wangapi hasa? / Ni wanafunzi kama walioweza kulisoma vizuri. Wako kama 6, 7 hivi.", "quote_en": "Before I say who formed words well, let me go back to what you said about them repeating. There is a word like 'si'; many failed and said 'sikia'. That is what beat many of them. But some could pronounce it. Now, do you want me to name them? / Not necessary, how many exactly? / The pupils who could read it well are about 6 or 7.", "why": "A two-word probe turns a vague impression into a count and a named error, and the coach keeps pupils unnamed. This is the follow-up question missing from most debriefs.", "better_move": null, "better_move_local": null, "lang": "sw", "rtl": false}, {"key": "d0918aacc75_tanzania_03", "file": "clips/d0918aacc75_tanzania_03.mp3", "dur": 44.6, "kind": "strength", "dimension": "teacher_self_reflection", "programme": "tanzania", "programme_label": "Tanzania", "coach": "TZ Coach 17", "title": "Teacher corrects the coach with pupil evidence", "quote_original": "Ndiyo, walikuwa hawarudii sentensi, bali nilichokiona walikuwa wanarudia baadhi ya pronouns na objects walizokuwa wanazitumia kutunga majina. Kwa mfano, mmoja anaweza akasema, \"She has a book.\" Mwingine akarudia tena, \"She has a ruler.\" Au mwingine akasema, \"He has a book.\" Yaani, wanachokibadilisha, aidha wanabadilisha pronoun au wanabadilisha object. Niliwaelekeza, nikawaambia, tunga kwa kutumia pronouns, ziko nyingi, lakini objects za kutumia pia ziko nyingi, na ninaona nilivyowarekebisha hivyo, walifanya marekebisho na wakaanza kutumia pronouns na objects tofauti na mwenzake.", "quote_en": "Yes, they were not repeating sentences; what I saw was them repeating some of the pronouns and objects. For example, one says 'She has a book.' Another says 'She has a ruler.' Or 'He has a book.' So they change either the pronoun or the object. I told them there are many pronouns and many objects to use, and when I corrected them they started using different pronouns and objects from their partner.", "why": "Asked about a specific moment, the teacher feels safe to disagree and backs it with what pupils actually said; the coach then accepts it ('Ni kweli, nami nilishuhudia hayo').", "better_move": null, "better_move_local": null, "lang": "sw", "rtl": false}, {"key": "de70486f450_tanzania_04", "file": "clips/de70486f450_tanzania_04.mp3", "dur": 37.6, "kind": "strength", "dimension": "tone_and_psychological_safety", "programme": "tanzania", "programme_label": "Tanzania", "coach": "TZ Coach 46", "title": "A safe question, an honest answer", "quote_original": "Na katika somo lako, wapi umeona kuna changamoto? / Changamoto niliyoiona ni pale kwa watoto, yaani ku- ku- watoto fiki, yaani fikira za watoto, kila mmoja anafikiria nini kuhusu walichojifunza. Mimi naona ndiyo changamoto: kila mtoto anaweza kufikiria tofauti na somo, au akaenda vizuri na somo au tulivyojifunza. Kwa hiyo changamoto niliyopo ni kufikiri somo kuhusianisha fikira zake na somo tulilojifunza.", "quote_en": "And in your lesson, where did you see a challenge? / The challenge I saw is the children's thinking, what each one thinks about what they learned. Each child may think differently from the lesson, or may go along well with what we learned. So my challenge is connecting the child's thinking with the lesson we learned.", "why": "A short, neutral question gets the teacher to name a real difficulty in their own words, with no defensiveness. This is the raw material for a growth area (the coach then did not use it).", "better_move": null, "better_move_local": null, "lang": "sw", "rtl": false}, {"key": "d7d8f0cf16b_tanzania_05", "file": "clips/d7d8f0cf16b_tanzania_05.mp3", "dur": 40.5, "kind": "strength", "dimension": "concrete_action_step", "programme": "tanzania", "programme_label": "Tanzania", "coach": "TZ Coach 40", "title": "Turning the teacher's own plan into one step", "quote_original": "Okay. Kwa hiyo ina maana, sasa hivi kwenye hii hapa inabidi walengwa wako sasa, hata wale, yaani hata wakiwa pale kwenye vikundi, yule ambaye unamlenga ndio itabidi yeye ndio aongoze mjadala. Kwa mfano, yule ambaye kabisa unaona kama hivi kwenye somo la leo, wale ambao ulikuwa ukiwauliza maswali wanakuwa wanakosea. Wakikaa kwenye vile vikundi, wao ndio wawe walengwa wako pale. Yaani, yeye ndio anakuwa anaongoza mjadala. Ina maana yeye akiongoza mjadala, hata kama atakuwa anafanya makosa, lakini wenzake wakawa wanamrekebisha, itamsaidia pia kujenga kumbukumbu. Kwa sababu hii dhana, kwa sababu ya uzito wake, inabidi mwanafunzi yeye mwenyewe ndio awe anajiongoza ili baadaye aweze kwenda kufanyaje? Kukumbuka.", "quote_en": "OK. So that means your target pupils, even in the groups, the one you are targeting should lead the discussion. For example, those you asked questions today who were making mistakes. In the groups, they should lead. If they lead, even if they make mistakes, their peers correct them, and that helps build memory. Because this concept is hard, the pupil needs to lead themselves so that later they can remember.", "why": "The coach takes the teacher's mixed-group idea, sharpens it into one observable action (pupils who erred today lead the group) and says why it helps learning.", "better_move": null, "better_move_local": null, "lang": "sw", "rtl": false}, {"key": "d6f5f7a48fe_tanzania_06", "file": "clips/d6f5f7a48fe_tanzania_06.mp3", "dur": 25.8, "kind": "strength", "dimension": "commitment_and_follow_up", "programme": "tanzania", "programme_label": "Tanzania", "coach": "TZ Coach 04", "title": "Which period, which day, when we meet", "quote_original": "Ninapokea ushauri na nitaufanyia kazi. / Asante. Kwa hiyo, utaufanyia wakati gani zaidi? / Kipindi kitakachofuata. / Siku gani? / Siku ya kesho nitafanya hivyo. / Asante mwalimu. / Asante. / Tukutane tena wiki hii, tuone pamoja siku gani inakufaa? / Itakuwa ni kesho. Kesho asubuhi. / Kesho? Kesho asubuhi? / Ndiyo.", "quote_en": "I receive the advice and I will work on it. / Thank you. So when will you do it? / The next period. / Which day? / Tomorrow I will do it. / Thank you, teacher. / Thank you. / Let us meet again this week; which day suits you? / Tomorrow. Tomorrow morning. / Tomorrow? Tomorrow morning? / Yes.", "why": "The coach does not stop at 'I will work on it': two short questions pin down when the teacher will try it and when they will look at it together.", "better_move": null, "better_move_local": null, "lang": "sw", "rtl": false}, {"key": "d26abc0cd5e_tanzania_07", "file": "clips/d26abc0cd5e_tanzania_07.mp3", "dur": 37.0, "kind": "strength", "dimension": "coach_questioning_and_dialogue", "programme": "tanzania", "programme_label": "Tanzania", "coach": "TZ Coach 22", "title": "What made the group work click?", "quote_original": "Asante kwa somo lako vizuri, umefanya vizuri sana. Nilikuwa natamani. Ulipokuwa unawashirikisha watoto wako kwenye groupu, zile discussion, kwenye majadiliano ya vizuizi, ni kitu gani ambacho ulihisi wao kimewafanya waelewe somo lako? / Sawa. Nime- nimeweza kuelewa kwamba hiki kitu kinaweza kikawasaidia watoto wakaelewa, kwa sababu cha kwanza mtoto anaanza kufikiria kwanza, halafu akishafikiria wanashirikiana. Watoto wenyewe kwa wenyewe, lakini baada ya kushirikiana, wanaweza kujadili na kutoa majibu ambayo ni ya pamoja.", "quote_en": "Thank you for your lesson, you did very well. When you involved your children in group discussions, what was it that you felt made them understand your lesson? / I came to understand this can help the children, because first the child thinks alone, then once they have thought they work together, and after working together they can discuss and give joint answers.", "why": "An open question about a specific activity and its effect on pupils, asked before any suggestion, gets the teacher to explain the reasoning behind their own method.", "better_move": null, "better_move_local": null, "lang": "sw", "rtl": false}, {"key": "dd9cdf4257c_tanzania_08", "file": "clips/dd9cdf4257c_tanzania_08.mp3", "dur": 14.7, "kind": "missed_opportunity", "dimension": "concrete_action_step", "programme": "tanzania", "programme_label": "Tanzania", "coach": "TZ Coach 29", "title": "'Teach them more' accepted as the plan", "quote_original": "Na umejipangaje kwenye kipindi kijacho sasa? / Nitajitahidi kuhakikisha kwamba nawaelimisha zaidi kuhusu matumizi ya she na kuadi \"s\" kwenye verb. / Hongera sana, na kila la heri. / Asante sana.", "quote_en": "And how have you planned for the next period now? / I will try to make sure I teach them more about using 'she' and adding 's' to the verb. / Congratulations, and all the best. / Thank you.", "why": "Seconds earlier the teacher pinpointed the exact moment pupils struggled (changing the song from 'I wash my face' to 'She washes her face'). The coach accepts a vague 'teach them more' and closes, so nothing observable is agreed.", "better_move": "You already found the moment: the song line where 'I wash my face' becomes 'She washes her face'. Tomorrow, when you reach that line, what exactly will you do? Let's try it now. I'll be a pupil and you lead me through the line. Good. Which day can I come and see it?", "better_move_local": "Umeshaiona sehemu yenyewe: pale kwenye wimbo mnapobadilisha 'I wash my face' kuwa 'She washes her face'. Kesho ukifika mstari huo, utafanya nini hasa? Haya, tujaribu sasa hivi. Mimi niwe mwanafunzi, wewe niongoze kwenye mstari huo. Safi sana. Nije siku gani kuona inavyokwenda?", "lang": "sw", "rtl": false}, {"key": "d1771c37a36_tanzania_09", "file": "clips/d1771c37a36_tanzania_09.mp3", "dur": 21.9, "kind": "missed_opportunity", "dimension": "focus_on_one_growth_area", "programme": "tanzania", "programme_label": "Tanzania", "coach": "TZ Coach 21", "title": "Exact misconception named, then goodbye", "quote_original": "Changamoto ni kwenye ukopaji. Mmh, anapokuwa pamoja, hachukulii kwamba yale ni moja; yale ni kama 10, kwamba ni makumi. Yaani, anachukulia moja kama moja. Lakini nimerekebisha, na wameelewa. / Haya, Madam, asante. Nikutakie majukumu mema. / Asante.", "quote_en": "The challenge is in borrowing. The pupil does not see that the borrowed one is really 10, a ten. The pupil takes one as one. But I corrected it, and they understood. / OK, Madam, thank you. I wish you good work. / Thank you.", "why": "After three questions the teacher names the precise pupil misconception, which is the ideal growth area. The coach thanks the teacher and ends the conversation with no focus, step or follow-up.", "better_move": "That is exactly the thing to work on: pupils treat the borrowed one as a one, not a ten. How did you correct it, and how do you know it stuck? Let's make that our one focus. In tomorrow's lesson, what will you show them so they see one ten turning into ten ones?", "better_move_local": "Hilo ndilo hasa la kufanyia kazi: mwanafunzi anachukulia ile moja aliyokopa kama moja, si kumi. Ulirekebishaje, na unajuaje kwamba wameshika? Tulifanye hilo kuwa jambo letu moja. Kesho utawaonyesha nini ili waone kumi moja ikigeuka kuwa mamoja kumi?", "lang": "sw", "rtl": false}, {"key": "d2dbe1f9f25_tanzania_10", "file": "clips/d2dbe1f9f25_tanzania_10.mp3", "dur": 34.6, "kind": "missed_opportunity", "dimension": "teacher_self_reflection", "programme": "tanzania", "programme_label": "Tanzania", "coach": "TZ Coach 05", "title": "Teacher names the problem; coach says 'Mm'", "quote_original": "Somo langu nimeliona limeenda vizuri, lakini watoto wanashindwa sana sana kubain zile nafasi za namba. / Mh. / Ndiyo. Kwa hiyo katika kipindi kijacho, nitajitahidi kusisitiza katika kipindi kijacho waweze kujua kwanza kubain zile nafasi za namba na vile vitengo. Watakiwa kwamba kama ni kutoa, waanze kutoa senti, ndipo waanze kutoa shilingi. / Asante mwalimu. Nakushukuru. / Asante. / Dosari ndogo ndogo zisizoonekana, naona tunaomba kwenye kipindi kijacho tuweze kufanyia marekebisho. Nakutakia kazi njema.", "quote_en": "I saw my lesson as having gone well, but the children really struggle to tell the place values apart. / Mm. / Yes. So next lesson I will stress that they first identify the place values and units. When subtracting, they should start with the cents, then the shillings. / Thank you, teacher. / Thank you. / Small unseen flaws, I think we ask that next lesson we correct them. I wish you good work.", "why": "After 75 seconds of coach praise, the teacher self-identifies the key difficulty and a concrete fix. The coach answers 'Mm', then closes with an unexplained 'small unseen flaws'.", "better_move": "You've spotted the key problem: pupils can't tell the place values apart. What did you see them do when that happened? Your idea of cents before shillings is a good step. Show me how you'll say it to the class tomorrow, as if I'm a pupil. Then let's agree a day for me to come and see it.", "better_move_local": "Umeliona tatizo kubwa: watoto hawatofautishi nafasi za namba. Uliwaona wakifanya nini hasa hilo lilipotokea? Wazo lako la kuanza na senti kabla ya shilingi ni hatua nzuri. Nionyeshe utakavyowaambia wanafunzi kesho, kana kwamba mimi ni mwanafunzi. Kisha tukubaliane siku nije kuona.", "lang": "sw", "rtl": false}, {"key": "d4d7079706d_tanzania_11", "file": "clips/d4d7079706d_tanzania_11.mp3", "dur": 18.6, "kind": "missed_opportunity", "dimension": "tone_and_psychological_safety", "programme": "tanzania", "programme_label": "Tanzania", "coach": "TZ Coach 31", "title": "Teacher pushes back; coach just says 'Okay'", "quote_original": "Okay. / Ndiyo. / Sawa. Nashukuru mwalimu kwa kunikaribisha. Hongera kwa kazi nzuri. / Asante. / Lakini pia nikutie moyo, uendelee tu kupambana, ili tuweze kuwasaidia watoto wakafanya vizuri.", "quote_en": "Okay. / Yes. / OK. Thank you, teacher, for welcoming me. Congratulations on good work. / Thank you. / But let me also encourage you, just keep struggling on, so that we can help the children do well.", "why": "Just before this, the teacher argued that pupils this young cannot do group discussion ('itakuwa fujo'). The coach says 'Okay', offers general encouragement and ends, so the real concern is ignored and no step is agreed.", "better_move": "That's a fair worry; young children do need structure. Could we try something very small? Tomorrow, for one question only, each child turns to their neighbour for 20 seconds, then you pick two to answer. What could go wrong, and how would you handle it?", "better_move_local": "Hiyo ni hoja ya msingi; watoto wadogo wanahitaji utaratibu. Je, tujaribu kitu kidogo sana? Kesho, kwa swali moja tu, kila mtoto amgeukie jirani yake kwa sekunde 20, kisha wewe uchague wawili wajibu. Unaona nini kinaweza kwenda vibaya, na utakabilianaje nacho?", "lang": "sw", "rtl": false}, {"key": "d1d6ededdfc_tanzania_12", "file": "clips/d1d6ededdfc_tanzania_12.mp3", "dur": 25.2, "kind": "missed_opportunity", "dimension": "coach_questioning_and_dialogue", "programme": "tanzania", "programme_label": "Tanzania", "coach": "TZ Coach 18", "title": "'Sawa', then straight to the guide's step", "quote_original": "Nilikuwa napima uelewa wao katika silabi. / Sawa. Vipi kesho ukijaribu hili: wakati wanafunzi wanatunga sentensi, waombe wawili wawili wasisitize kwa nini walichagua neno hilo. Kisha mwalimu uchague majibu mawili au matatu, na kuzungumza kwa wanafunzi ili kuzungumza kwa dakika 1 kila mmoja. / Sawa, nitafanya hivyo kwa kipindi kijacho.", "quote_en": "I was checking their understanding of the syllables. / OK. How about trying this tomorrow: when pupils compose sentences, ask them in pairs to say why they chose that word. Then pick two or three answers and have those pupils speak for 1 minute each. / OK, I will do that in the next lesson.", "why": "The teacher gives a reason; the coach says 'Sawa' and reads out a ready-made step. The teacher never thinks about it and agrees in one line. This is the pattern in 35 of 58 debriefs.", "better_move": "You were checking their understanding. When you asked them why, what did they actually say? ... How could you hear from more of them? What would you ask them tomorrow?", "better_move_local": "Ulikuwa unapima uelewa wao. Ulipowauliza 'kwa nini', walisema nini hasa? ... Ungefanyaje ili usikie kutoka kwa wanafunzi wengi zaidi? Kesho ungewauliza nini?", "lang": "sw", "rtl": false}, {"key": "d718a5a3fdb_tanzania_13", "file": "clips/d718a5a3fdb_tanzania_13.mp3", "dur": 27.2, "kind": "missed_opportunity", "dimension": "coach_questioning_and_dialogue", "programme": "tanzania", "programme_label": "Tanzania", "coach": "TZ Coach 32", "title": "Reading the guide's question, fault included", "quote_original": "Na sasa tuna swali ambalo Rumi anauliza kwamba: ulipoona wanafunzi wakijibu kwa sauti, nini kilikufanya usiweze kusikia jibu la kila mwanafunzi mmoja mmoja? / Kilichonifanya nisitake kusikia jibu la mwanafunzi mmoja mmoja ni kwamba wanafunzi walikuwa wameshaelewa, na wakati mwingine muda ulikuwa hautoshi.", "quote_en": "And now we have a question that Rumi asks: when you saw pupils answering aloud, what made you not able to hear each pupil's answer one by one? / What made me not want to hear each pupil's answer is that the pupils had already understood, and sometimes there was not enough time.", "why": "The coach reads the app's question aloud, attributes it to the app and keeps its built-in assumption that the teacher failed. The teacher defends the choice (pupils understood, no time), and the coach goes on to the next scripted step.", "better_move": "Ask in your own words, without the blame: 'When the class answered together, how did you know who had understood and who hadn't?' Then wait, and follow up on what the teacher says.", "better_move_local": "Uliza kwa maneno yako bila kulaumu: 'Darasa lilipojibu kwa pamoja, ulijuaje ni nani ameelewa na nani bado?' Kisha subiri, na ufuatilie anachokisema mwalimu.", "lang": "sw", "rtl": false}, {"key": "d58fe74588b_tanzania_14", "file": "clips/d58fe74588b_tanzania_14.mp3", "dur": 31.6, "kind": "missed_opportunity", "dimension": "practice_or_modelling", "programme": "tanzania", "programme_label": "Tanzania", "coach": "TZ Coach 44", "title": "A good step, never tried out loud", "quote_original": "Aha, vizuri mwalimu. Lakini kwa kuongezea, vipi kesho ukajaribu kama wataingia baada ya taratibu za kutoa, uwaulize wanafunzi wawili wajenge tatizo la kwa kutumia ile ma moja na makumi, na kisha wafanye jozi, wajaribu kutatua, na kuelezea kwa nini walichagua njia hiyo? / Nitafanya hivyo.", "quote_en": "Aha, good, teacher. But in addition, how about trying tomorrow, after the subtraction procedure, asking two pupils to build a problem using the ones and tens, then putting them in pairs to solve it and explain why they chose that method? / I will do that.", "why": "The step is clear and observable, but the teacher's only words are 'Nitafanya hivyo'. No one practises what the teacher will say to the pupils, which is the case in all 58 debriefs.", "better_move": "Let's try it now. I'll be one of your pupils. Say exactly what you'll say after the subtraction routine to get two pupils building their own problem. Good. Now once more, and this time also ask them 'Why did you choose that way?'", "better_move_local": "Haya, tujaribu sasa hivi. Mimi niwe mmoja wa wanafunzi wako. Niambie maneno yale yale utakayosema baada ya kutoa, ili wanafunzi wawili watunge tatizo lao wenyewe. Vizuri. Sasa jaribu tena, safari hii uwaulize pia 'Kwa nini mmechagua njia hiyo?'", "lang": "sw", "rtl": false}, {"key": "da8918cdc35_tanzania_15", "file": "clips/da8918cdc35_tanzania_15.mp3", "dur": 16.3, "kind": "missed_opportunity", "dimension": "commitment_and_follow_up", "programme": "tanzania", "programme_label": "Tanzania", "coach": "TZ Coach 28", "title": "'I think I'll try' accepted as a plan", "quote_original": "Naweza jema, nafikiri nitajaribu. / Utajaribu lini sasa? / Um, nafikiri kwenye kipindi kijacho. / Basi tutakutana wiki ijayo. Utapitia. Asante.", "quote_en": "I think I will try. / When will you try, then? / Um, I think in the next period. / Then we will meet next week. You will review. Thank you.", "why": "The coach rightly asks 'when?', but accepts two hedged 'I think' answers, sets 'next week' with no day, and never hears the teacher say the step or agree how they will know it worked.", "better_move": "Which class and which day is the next period? Tell me in your own words the thinking question you'll ask after the first example. I'll come on that day, and we'll know it worked if at least two groups explain a second way to get the answer.", "better_move_local": "Kipindi kijacho ni darasa gani, na siku gani? Niambie kwa maneno yako swali la kufikiri utakalouliza baada ya mfano wa kwanza. Nitakuja siku hiyo, na tutajua imefanikiwa kama angalau vikundi viwili vitaeleza njia nyingine ya kupata jibu.", "lang": "sw", "rtl": false}], "conversations": [{"id": "d400c6a08ca", "tab": "ICT: a strong debrief", "title": "A strong debrief", "why": "Six minutes, clean speaker turns, and the closest to the ideal arc in this group (overall 68, second highest; the highest another debrief has swapped speaker labels for two minutes). Support-framed opening with specific praise; the teacher reflects; one growth area (why and how questions) made concrete with a sentence the teacher wrote in this lesson; the coach asks where the teacher would use it; the teacher names the next reading lesson and scripts the exact question. It still lacks a follow-up date and a second rehearsal round, which is a useful discussion point for trainers.", "audio": "full/d400c6a08ca.mp3", "duration": 371.6, "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 12", "lines": [{"t": 0.8, "who": "coach", "text": "Teacher, ma'am, so thank you so much. پہلے تو کلاس آبزرویشن کے لیے allow کرنے کے لیے، ma'am، اور دوسرا یہ کہ آپ سے میں نے just short-short سی discussion کرنی ہے، جو آج ہماری کلاس جیسی رہی ہے، اس پہ آپ کا کیسا experience رہا؟ میرا as an observation، میں نے کیا observe کیں، وہ چیزیں ہم اس پہ تھوڑا سا discuss کریں گے، short سا۔ So پہلے میرے سے start کرتے ہیں۔", "en": "Teacher, ma'am, so thank you so much. First, for allowing the class observation, ma'am, and second, I just want to have a short, short discussion with you about how our class went today and how your experience of it was. My observation, what I observed, we'll discuss those things a little, just briefly. So let's start with me."}, {"t": 18.2, "who": "coach", "text": "تو میں نے دیکھا، ma'am، throughout جو مجھے بہت اچھا لگا وہ یہ تھا کہ آپ کے جو students ہیں وہ کافی زیادہ interact کر رہے تھے، کوشش کر رہے تھے، مطلب like آپ sentence بھی دے رہی ہیں، چاہے وہ language barrier بھی آ رہا ہے، but وہ try کر رہے تھے کہ وہ کریں۔ تو وہ آپ کی بدولت ہی ہے کہ آپ نے ان کو اتنے اچھے سے شروع میں بتا دی چیزیں کہ ان کو اب idea تھا کہ انہوں نے sentence بنانا ہے، confusion نہیں تھی ان کو۔ So ma'am، آپ سے start کرتے ہیں، آپ کا experience کیسا رہا؟ مطلب like آپ کو کون سی strategy آج کی بہت اچھی لگی، اور جس سے آپ کو لگا کہ بچے سیکھ پائے جو آپ سکھانا چاہ رہی تھیں؟", "en": "So what I saw, ma'am, what I really liked throughout was that your students were interacting a lot and making an effort. I mean, you were giving them sentences too, and even though the language barrier was there, they were trying to do it. It's thanks to you that you explained things to them so well at the start that they had an idea they had to make a sentence, and they weren't confused. So ma'am, let's start with you: how was your experience? I mean, which strategy from today did you like a lot, and which one made you feel the children were able to learn what you wanted to teach?"}, {"t": 49.0, "who": "teacher", "text": "اس میں ایک چیز تو مجھے difference جو لگا، اپنی teaching میں اور آپ لوگوں نے جو بتایا، اس میں مجھے تو ایک اچھا لگا۔ اور میں just، اگر ہم جب start کرتے ہیں تو ہم previous knowledge کا ساتھ relate نہیں کرتے، بس سیدھا آئے اور اپنا topic بتائیں۔ یہ topic آج complete ہو گیا lesson، اب ہم next lesson شروع کرتے ہیں۔ Reading کراتی ہوں، اور پھر اس میں سے words جو difficult ہوتے ہیں میں ان کو underline کراتی ہوں، پھر ان کے meanings بتاتی ہوں، کیونکہ میں صرف وہ والے words نہیں جو اوپر ہوتے ہیں، میں ساری book میں سے جو ان کے words difficult ہوتے ہیں ان کو underline کرا کے ان کے meanings ان کو اردو میں بتا دیتی ہوں، تاکہ ان کو English translation جو ہے وہ اچھی طرح یاد ہو جائے۔", "en": "One thing I noticed as a difference between my own teaching and what you people showed, and I liked it. When we start, we don't relate to previous knowledge, we just come in and state our topic. This lesson is finished today, now we start the next lesson. I have them read, and then I have them underline the difficult words in it, then I tell them the meanings. And it's not just the words listed at the top; from the whole book I have them underline whatever words are difficult for them and tell them the meanings in Urdu, so that they remember the English translation well."}, {"t": 88.5, "who": "teacher", "text": "Lesson آتا ہوگا تو یہ activities کرانی پڑتی ہیں۔ بالکل۔ تو اس میں یہ ہے کہ ذرا آسانی لگتی ہے آپ کے والے lesson plan سے۔", "en": "When a lesson comes up, you have to do these activities. Absolutely. So with this, it seems a little easier with your lesson plan."}, {"t": 98.3, "who": "coach", "text": "جی، وہ to the point—", "en": "Yes, it's to the point—"}, {"t": 99.3, "who": "teacher", "text": "اور teacher کے لیے تھوڑا سا آسان ہے کہ وہ to the point، ان کو اگر vocabulary کا ہم نے topic شروع کیا ہے تو وہی ان کو اچھی طرح تیار کرانا ہے۔", "en": "And it's a little easier for the teacher because it's to the point: if we've started a vocabulary topic, then that's what we have to get them well prepared on."}, {"t": 107.2, "who": "coach", "text": "بالکل۔", "en": "Absolutely."}, {"t": 108.0, "who": "teacher", "text": "Next topic پہ جلدی جلدی نہیں جانا۔", "en": "You don't rush on to the next topic."}, {"t": 110.2, "who": "coach", "text": "بالکل۔", "en": "Absolutely."}, {"t": 110.7, "who": "teacher", "text": "یہ چیز اچھی ہے۔", "en": "This is a good thing."}, {"t": 111.8, "who": "coach", "text": "ٹھیک ہے، تو آپ کو بھی یہ اچھا لگا کہ جو words used ہوئے وہی throughout lesson آپ نے different طریقے سے استعمال کیے؟", "en": "Okay, so you also liked that the same words that were used, you used them throughout the lesson in different ways?"}, {"t": 118.4, "who": "teacher", "text": "اور ابھی تک مجھے sentence دکھا رہے ہیں کہ ہم نے یہ بنایا، دیکھیں، میں نے وہ یہ بنایا۔", "en": "And even now they're showing me sentences, saying, we made this, look, I made this."}, {"t": 122.3, "who": "coach", "text": "That's so positive، ma'am۔ یہی ہمارا main goal تھا کہ ہم creativity کو بھی بچوں کی لے کر آئیں، teacher کے اوپر صرف بچہ نہ dependent ہو کہ وہی جو پڑھائیں گے ہم نے بس وہی کرنا ہے۔ So اس میں یہ کیا، آپ کو بھی نظر آیا ہوگا، بہت بچوں کی creativity نظر آئی ہوگی کہ آپ کچھ بچے خود سے کر سکتے ہیں۔", "en": "That's so positive, ma'am. That was our main goal, to bring out the children's creativity too, so that the child isn't only dependent on the teacher, thinking we only have to do whatever they teach. So in this, you must have seen it too, you must have seen a lot of the children's creativity, that some children can do things on their own."}, {"t": 136.2, "who": "teacher", "text": "وہ ان کو یاد رہ جاتا ہے۔", "en": "They remember it."}, {"t": 136.9, "who": "coach", "text": "بالکل، تو وہ ان کو یاد رہ جاتا ہے topic۔ وہ رٹا نہیں لگتا، مطلب وہ ایک ان کی اپنی ہو جاتی ہے۔ بالکل۔ اچھا ma'am، کوئی ایسی چیز جو آپ کی teaching میں obviously آپ ایسے use کرتی ہوں گی، اور آج شاید نہ کر پائی ہوں practice، جس سے مزید بھی lesson بہتر ہو سکتا تھا؟ کچھ ایسا؟", "en": "Absolutely, so they remember the topic. It doesn't feel like rote learning, I mean it becomes their own. Absolutely. Okay ma'am, is there anything that you obviously use in your teaching, and maybe couldn't practise today, with which the lesson could have been even better? Something like that?"}, {"t": 156.0, "who": "teacher", "text": "آپ تو اس کا نہیں، کچھ ایسا feel نہیں ہوا۔", "en": "Not that, I didn't really feel anything like that."}, {"t": 159.9, "who": "coach", "text": "جی۔", "en": "Yes."}, {"t": 160.9, "who": "teacher", "text": "ابھی جیسے ایک vocabulary کا تھا نا، وہی topic رہا، اور اسی کو ہم نے continue رکھا۔", "en": "Like just now, it was a vocabulary topic, right? That stayed the topic, and we continued with that."}, {"t": 165.9, "who": "coach", "text": "بالکل۔", "en": "Absolutely."}, {"t": 166.7, "who": "teacher", "text": "تو جب ہم اپنا lesson کرتے ہیں تو اس میں جیسے words، meanings، اس میں English to English ان کو پڑھانا پڑتا ہے، اور جب ہم paper میں دیتے ہیں تو English to English meanings دینے پڑتے ہیں۔ اور میں نے آپ سے یہ بھی پوچھنا تھا کہ اگر جب ہم ابھی assessment ہونی ہے ان کی، تو اس میں ہم ان کے جو words ہیں نا، اس میں اردو میں یہ meaning لکھ سکتے ہیں؟", "en": "So when we do our lesson, with words and meanings, we have to teach them English to English, and when we give it in the paper we have to give English to English meanings. And I also wanted to ask you: when their assessment comes up, can we write the meanings of their words in Urdu?"}, {"t": 185.5, "who": "coach", "text": "نہیں ma'am، اصل میں یہ جو آج topic تھا نا، وہ آپ کا sentence making تھا۔ ٹھیک ہے، جب words meaning topic ہو گا نا تو وہ ظاہر ہے English to English ہی ہوں گے، اور ساتھ اردو ہوں گے۔ آج کا topic کیونکہ sentence making تھا، تو اس کی آسانی کے لیے word کے ساتھ English کے ساتھ ایک اردو کا word دے دیا تھا تاکہ بچوں کو concept آ جائے۔ اصل چیز تو sentence making تھی، وہ تو سب نے English میں ہی بنانے تھے نا۔ تو اس وجہ سے یہ difference آتا ہے کہ اگر word meaning کا topic ہوگا تو ظاہر ہے ہم اس میں پھر ہم English word پہ جا رہے ہوتے ہیں۔ کیونکہ آج کا topic sentence making تھا، تو sentence making کے اندر ہم word کو اردو میں بچوں کو بتا دیتے ہیں تاکہ sentence کے اندر استعمال کرنا easy ہو جائے۔ تو یہ difference ہے۔", "en": "No ma'am, actually today's topic was sentence making. Okay, when the topic is word meanings, then obviously they will be English to English, and Urdu alongside. Because today's topic was sentence making, to make it easier we gave an Urdu word along with the English word so that the children would get the concept. The real thing was sentence making, and everyone had to make those in English, right? So that's where this difference comes from: if the topic is word meaning, then obviously we're going by the English word. Because today's topic was sentence making, within sentence making we tell the children the word in Urdu so that using it in a sentence becomes easy. So that's the difference."}, {"t": 218.1, "who": "coach", "text": "اچھا تھوڑا بہت ma'am، اس میں میں یہ کہنا چاہوں گی کہ جیسے teachers questioning کرتے ہیں، like وہ پوچھتے ہیں کہ یہ کیوں ہے، یہ، یا یہ کیا ہے۔ زیادہ تر questioning میں ہم زیادہ دیکھتے ہیں teacher کو پوچھتے ہیں کہ اس کا کیا مطلب ہے، یہ word اس کا کیا مطلب ہے، یا یہ sentence لکھا تو یہ کیا ہے۔ ٹھیک ہے؟ So مجھے یہ لگا کہ اگر ایک اور چیز add ہم کر سکیں، کیوں اور کیسے۔ کہ یہ اگر لکھا تو اس کو کیوں ہم نے اس کے اندر استعمال کیا۔ مطلب آپ نے ایک sentence لکھ کے بتا دیا بچوں کو۔ جیسے آپ خود example دے سکتی ہیں، آج کا کوئی ایسا sentence ma'am آپ نے لکھا ہو، اور آپ اگر اس میں کوئی سوالات میں کیوں یا کیسے استعمال کر سکیں تو وہ کیا ہوگا؟", "en": "Okay, a little bit more, ma'am. What I'd like to say here is about how teachers do questioning, like they ask why this is, or what this is. Mostly in questioning we see teachers asking what something means, what this word means, or if a sentence is written, what this is. Okay? So I felt that if we could add one more thing, why and how: that if this was written, why did we use it in there. I mean, you wrote a sentence and told the children. For example, you can give an example yourself: some sentence from today that you wrote, and if you could use why or how in the questions about it, what would that be?"}, {"t": 253.6, "who": "teacher", "text": "Question answers میں یہ ہوتا ہے نا؟", "en": "That's in the question answers, isn't it?"}, {"t": 255.8, "who": "coach", "text": "نہیں نہیں، sentence میں ہی۔ Like جیسے آپ آج—", "en": "No, no, in the sentence itself. Like, as you today—"}, {"t": 258.3, "who": "teacher", "text": "Sentence میں جیسے ایک word، ہم نے sentence ان کو بنایا، vocabulary والا word تو خواہش، ان کو پتہ ہی نہیں۔ اور جیسے words ہوتے ہیں، جیسے ان کو جو flip find کا نہیں، میننگ آتا ہے، وہ بتا دیتی ہوں۔", "en": "In a sentence, like a word, we had them make a sentence, a vocabulary word, like \"wish\", they don't know it at all. And for words like that, whose meaning they don't get, I tell them."}, {"t": 273.9, "who": "coach", "text": "جیسے ma'am، آج آپ نے ایک sentence لکھوایا تھا نا علامہ اقبال کا ہی کہ اس کے اندر یہ تھا کہ پریشان ہو گئے۔ ٹھیک ہے؟ تو be without کا جو word آپ نے use کیا، تو آپ یہ پوچھ سکتے ہیں کہ ہم نے یہی word کیوں استعمال کیا، دوسرے کیوں نہیں کیے۔ تو اس میں differentiate بچے کر سکتے ہیں کہ کیونکہ اس میں پریشانی کا word استعمال ہوا ہے، حالانکہ آپ نے کیا تھا، لیکن آپ نے خود بتایا تھا۔", "en": "For example, ma'am, today you had them write a sentence about Allama Iqbal, in which it said they became worried. Okay? So the word \"be without\" that you used, you can ask why we used this word and why we didn't use others. Then the children can differentiate, because the word for worry was used in it, although you had done it, but you had told them yourself."}, {"t": 294.8, "who": "teacher", "text": "اور بچوں نے وہ بھی لکھا۔", "en": "And the children wrote that too."}, {"t": 297.6, "who": "coach", "text": "Be hold کو شامل کرنا۔ بالکل۔ تو آپ be without کا word آپ یہ پوچھ سکتی ہیں کہ ہم کیوں use کر رہے ہیں اس میں، دوسرے کیوں نہیں کر رہے۔ تو ایک چھوٹا سا سوال ہے جو کہ مزید clarity بچوں میں لا سکتا ہے۔ تو یا اگر ہم be without کا اس sentence کے اندر اگر ہم word use کریں گے تو کیسے کریں گے؟ تو کیوں اور کیسے کے سوالات کو ہم تھوڑا سا بیچ میں add کر سکتے ہیں۔", "en": "Including \"be hold\". Absolutely. So with the word \"be without\" you can ask why we are using it there and why we are not using others. It's a small question that can bring more clarity to the children. Or, if we use the word \"be without\" inside that sentence, how would we use it? So we can add why and how questions in the middle a little."}, {"t": 318.7, "who": "teacher", "text": "اور اس سے بچے میں ذرا اور creativity آ جائے۔", "en": "And with that the child gets a bit more creativity."}, {"t": 320.7, "who": "coach", "text": "جی۔ تو وہ پھر تھوڑا سا lesson سے ہٹ کے بھی ہو سکتا ہے۔ وہ آپ کی اپنی creativity ہے، teacher کس جگہ پہ اس کو use کرنا چاہے، کیوں اور کیسے کے سوالات ہم ان کو add کر سکتے ہیں۔ تو ma'am، ایسا کر سکتے ہیں؟ اگر next class اگر آپ کی کوئی بھی ہوتی ہے، اسی topic کی ہوتی ہے، تو آپ کیا سمجھتی ہیں، کہاں پر آپ اس طرح کے سوالات pinch کر سکتے ہیں؟ کوئی ایسی جگہ، کوئی شروع میں، درمیان میں، آخر میں، یا کہاں پر؟ Independent work کے دوران۔", "en": "Yes. So that can even be a little off the lesson. It's your own creativity, wherever the teacher wants to use it, we can add why and how questions. So ma'am, can we do that? If you have any next class, on the same topic, where do you think you could pinch in questions like this? Some place, at the start, in the middle, at the end, or where? During independent work."}, {"t": 343.6, "who": "teacher", "text": "اسی پہ، اسی اسی طرح کے topic پہ، یا like— جیسے ابھی میں نے ایک reading کرانی ہے۔", "en": "On the same, on a topic of the same kind, or like— for example, now I have to do a reading."}, {"t": 348.9, "who": "coach", "text": "جی، reading کرانی ہے۔", "en": "Yes, you have to do a reading."}, {"t": 349.8, "who": "teacher", "text": "بچوں کو reading کراتے ہوئے پھر میں کوئی سا بھی ان کو ایک paragraph، دو چار لائن کا دوں گی، اور وہ بچہ read کر رہا ہے۔", "en": "While having the children read, I'll give them any paragraph, two or four lines, and that child is reading."}, {"t": 358.3, "who": "coach", "text": "جی۔", "en": "Yes."}, {"t": 358.6, "who": "teacher", "text": "تو میں اس سے یہی پوچھوں گی کہ ہاں بتائیں کہ اس میں یہ والا sentence کیوں آیا۔", "en": "So I'll ask them this: yes, tell me, why did this sentence come up in it?"}, {"t": 363.3, "who": "coach", "text": "بالکل۔", "en": "Absolutely."}, {"t": 364.0, "who": "teacher", "text": "تو بچے نے جو بھی اس میں representing ہو گی۔", "en": "So whatever the child says is being represented in it."}, {"t": 367.6, "who": "coach", "text": "Perfect۔ تو مطلب ہم وہاں پہ کیوں یا کیسے کا word—", "en": "Perfect. So I mean, there we can use the word why or how—"}, {"t": 370.2, "who": "teacher", "text": "کیسے کا word use کر سکتے ہیں۔", "en": "We can use the word how."}, {"t": 371.0, "who": "coach", "text": "ٹھیک ہے، thank you۔", "en": "Okay, thank you."}], "phases": [{"name": "Thanks, purpose and first praise", "t": 0.8}, {"name": "Teacher reflection", "t": 49.0}, {"name": "Coach affirms creativity", "t": 122.0}, {"name": "Coach asks what could improve; teacher asks about assessment language", "t": 152.3}, {"name": "Coach answers, then introduces why/how questions", "t": 185.5}, {"name": "Example from the lesson", "t": 273.9}, {"name": "Teacher says where they will use it", "t": 320.7}], "notes": [{"line": 29, "kind": "strength", "dim": "concrete_action_step", "text": "The coach asks the teacher where they would use the new question type, and the teacher answers with a concrete place and the exact question.", "better": null}, {"line": 25, "kind": "strength", "dim": "evidence_from_the_lesson", "text": "The coach makes the abstract idea of 'why' questions concrete by using a sentence the teacher actually wrote in this lesson.", "better": null}, {"line": 14, "kind": "missed_opportunity", "dim": "teacher_self_reflection", "text": "When the teacher says they cannot think of anything to improve, the coach accepts it and moves on instead of helping them look back at the lesson.", "better": "Point to one moment: 'When the students wrote their sentences, what did you notice about why they chose a word?' so the teacher can find the gap in their own words."}, {"line": 32, "kind": "missed_opportunity", "dim": "commitment_and_follow_up", "text": "The teacher has just said what they will do, and the coach ends with 'thank you' without a follow-up, a wait-time tip or a sign of success.", "better": "Say: 'After you ask, wait a few seconds for the child to answer; I will look at how it went at my next visit, and a good sign is that a child gives a full sentence as a reason.'"}], "scores": {"purpose_and_relationship_opening": 2, "teacher_self_reflection": 1, "coach_questioning_and_dialogue": 2, "evidence_from_the_lesson": 2, "focus_on_one_growth_area": 3, "concrete_action_step": 2, "practice_or_modelling": 2, "commitment_and_follow_up": 2, "tone_and_psychological_safety": 2}, "overall": 68, "lang": "ur", "rtl": true}, {"id": "d9915299d52", "tab": "ICT: a typical debrief", "title": "A typical debrief", "why": "This is a 6.2-minute debrief scoring 41, almost exactly the group median (41.5), with a coach share of 0.70 (median 0.72). It follows the common arc. The coach thanks the teacher and asks for 'best practices'; the teacher gives a few points and admits that time ran out for practice. A good 'what is the reason?' probe follows. The coach then praises the class climate and, in a 104-second turn, raises three fixes (pacing, writing time before oral answers, peer swap of copies), and closes with 'these are two or three things... keep up the good work'. There is no single step, no rehearsal and no follow-up. The transcript has clean speaker turns.", "audio": "full/d9915299d52.mp3", "duration": 374.1, "programme_label": "ICT (Islamabad)", "coach": "ICT Coach 04", "lines": [{"t": 0.5, "who": "coach", "text": "السلام علیکم، میم۔ فرسٹ آف آل، تھینک یو سو مچ کہ آپ نے کلاس روم آبزرو کرنے کا موقع دیا۔ میں چاہوں گا کہ آپ اپنی آج کی کلاس کو دیکھیں اور آج آپ کو کلاس میں جو بیسٹ پریکٹسز لگی، جو چیزیں بہت اچھی لگیں، وہ مجھے بتائیں۔", "en": "Assalamu alaikum, ma'am. First of all, thank you so much for giving me the chance to observe your classroom. I'd like you to reflect on today's class and tell me which best practices you felt there were, the things that seemed really good to you."}, {"t": 11.7, "who": "teacher", "text": "بیسٹ پریکٹسز؟", "en": "Best practices?"}, {"t": 12.9, "who": "coach", "text": "یس، جو چیز آپ کو بہت اچھی لگی۔ کلاس میں وہ، ام، لیسن پلان سے ریلیٹڈ ہو سکتی ہیں، بچوں کی پارٹیسپیشن، کوئی بھی چیز جو آپ کو بہت اچھی لگی اپنی کلاس میں۔", "en": "Yes, whatever you felt was really good. In class, they could be related to the lesson plan, the children's participation, anything at all that you really liked in your class."}, {"t": 20.4, "who": "teacher", "text": "اچھا، اس میں یہ ہے کہ جو لیسن پلان میں انہوں نے روف عرفہ کا شرط و جزا کو جو ایکسپلین کیا نا، وہ بہت اچھا کیا ہوا تھا۔ ٹھیک ہے، اس سے جو بچوں کو ہیلپ ملی کہ وہ ان کو الگ الگ ڈفرنشییٹ کر سکتے ہیں۔ انہوں نے رفعت اف کو پہچان لیا۔ شرط و جزا میں ہمیں تھوڑا سا ٹائم ابھی لگے گا اس کو پہچاننے میں اور ان کو ڈفرنشییٹ کرنے میں۔ اس کے لیے ایک لیسن اور ہونا چاہیے، شرط و جزا کے لیے نا، الگ سے۔", "en": "Okay, well, in the lesson plan, the way the particles of conjunction and the condition-and-consequence were explained was done very well. Right, it helped the children to differentiate between them. They recognised the conjunction particles. With condition-and-consequence we'll still need a bit more time to recognise it and to differentiate them. There should be one more lesson for that, separately, for condition-and-consequence."}, {"t": 41.2, "who": "coach", "text": "Mm-hmm. But the participation of the students was good.", "en": "Mm-hmm. But the participation of the students was good."}, {"t": 43.1, "who": "teacher", "text": "ہاں، پارٹیسپیشن واز گڈ۔ اور بچوں نے، مطلب، بہت اچھا پارٹیسپیٹ کیا انہوں نے، میری ایکسپیکٹیشن سے زیادہ۔ انہوں نے جملے بھی بڑے اچھے بنائے۔", "en": "Yes, participation was good. And the children, I mean, participated very well, more than I expected. They made very good sentences too."}, {"t": 50.8, "who": "coach", "text": "کیا ریزن لگتی ہے آپ کو کہ کس وجہ سے انہوں نے بہت اچھے طریقے سے پارٹیسپیٹ کیا؟", "en": "What do you think the reason is, why did they participate so well?"}, {"t": 53.9, "who": "teacher", "text": "اس- اس لیے پارٹیسپیٹ کیا نا، ان کو اب سمجھ آ گئی ہے رفعت اف کیا ہوتے ہیں۔", "en": "Th-they participated because they now understand what the conjunction particles are."}, {"t": 57.1, "who": "coach", "text": "It's mean کہ it credits goes to the you کہ آپ نے اس کو اتنے ڈیٹیل میں ایکسپلین کیا۔ And your explanation was good کہ آپ نے اس کو سٹیپ بائی سٹیپ کروایا۔ میرا خیال ہے تو اگر ایک ٹیچر پراپرلی لیسن پلان کو امپلیمنٹ کر رہی ہیں کلاسز میں، تو ڈیفینیٹلی اس میں لرننگ آؤٹ کمز بہتر ہو جائیں گے۔", "en": "It means the credit goes to you, that you explained it in so much detail. And your explanation was good, in that you took them through it step by step. I think if a teacher is properly implementing the lesson plan in their classes, then the learning outcomes will definitely get better."}, {"t": 72.8, "who": "teacher", "text": "ان شاء اللہ۔", "en": "God willing."}, {"t": 73.2, "who": "coach", "text": "اور اگر آپ شاید یہ اسے بورڈ پہ جا کے حروف علت کی ڈیفینیشن لکھیں، عطف کی ڈیفینیشن لکھیں، اور بچوں کو کہتی ہیں نوٹ ڈاؤن کر لیں، تو میرا خیال ہے ان کا لرننگ لیول اتنا—", "en": "And if perhaps you go to the board and write the definition of the cause particles, write the definition of conjunction, and tell the children to note it down, then I think their learning level would be so—"}, {"t": 82.3, "who": "teacher", "text": "ہاں، وہ لرننگ جو ہے، وہ ان کی فرم ہو جاتی ہے نا۔ ابھی فرم لرننگ نہیں ہے۔ انہوں نے کر تو لی، لیکن جو روٹ لرننگ ہے وہ بہت ضروری ہے۔ اگر وہ لکھ کے اس کو یاد کریں گے نا، وہ فرم ہو جائے گی ان کی لرننگ، اور پھر نیکسٹ ٹائم وہ اس کو اچھی طرح سے کمپریہینڈ کر سکیں گے۔", "en": "Yes, that learning becomes firm for them. Right now the learning isn't firm. They did learn it, but rote learning is very necessary. If they write it down and memorise it, their learning will become firm, and then next time they'll be able to comprehend it well."}, {"t": 94.9, "who": "coach", "text": "لیکن پارٹیسپیشن اسی لیول پہ اچھی تھی کہ بچے خود سے کچھ نہ کچھ اس میں ایکسپلور کر رہے تھے۔", "en": "But participation was good at that same level, in that the children were exploring something in it on their own."}, {"t": 98.6, "who": "teacher", "text": "ہاں، کر رہے تھے۔", "en": "Yes, they were."}, {"t": 99.1, "who": "coach", "text": "They are participating. اور کیا چیز آپ کو کلاس میں میم بہت اچھی لگی؟", "en": "They are participating. And what else did you like a lot in the class, ma'am?"}, {"t": 102.0, "who": "teacher", "text": "ام، اس کے علاوہ یہ ہے کہ کلاس نے بہت اچھا بیہیو بھی بہت اچھا کیا۔ انہوں نے بیہیویر واز گڈ، سٹوڈنٹ کا بیہیویر بہت اچھا تھا۔ انہوں نے پارٹیسپیٹ کرنے میں خود کو پیش پیش کیا۔ دوسری بات یہ ہے کہ سٹوڈنٹس چاہتے ہیں کہ وہ سیکھیں۔ ٹھیک ہے، لیکن سب سے جو مین پوائنٹ ہے کہ ان کو سیکھنے کے لیے ہم دیتے تو ہیں روم کہ وہ سیکھیں، لیکن اس کو جو ان کی فوکس آف اٹینشن ہے نا، جو ان کا سپین آف اٹینشن ہے، وہ سپین آف اٹینشن ان کا فوراً ڈائیورٹ ہو جاتا ہے۔ جیسے ہم نے حروف عطف کیا تو ایک بچہ حروفِ حروفِ شرط و جزا کو پڑھنا شروع ہو گیا کہ وہ تو ہم نے اب کر لیا، ٹھیک ہے، فٹافٹ وہ آگے جانے کی کرتے ہیں۔", "en": "Umm, apart from that, the class behaved very well too. Behaviour was good, the students' behaviour was very good. They put themselves forward to participate. Another thing is that students want to learn. Okay, but the main point is that we do give them room to learn, but their focus of attention, their span of attention, gets diverted right away. For example, when we did the conjunction particles, one child started reading the condition-and-consequence particles, saying we've already done that, okay, and they quickly try to move ahead."}, {"t": 139.6, "who": "coach", "text": "بالکل سپیڈ اپ۔", "en": "Exactly, speed up."}, {"t": 140.2, "who": "teacher", "text": "اس کو ہاں، سپیڈ اپ کرنے کی کوشش کرتے ہیں۔ وہ ان کی ہوتی ہے کہ بس یہ گزر گیا، اب اس کو آگے چلیں ہم۔", "en": "Yes, they try to speed it up. Their attitude is, that's done, now let's move on."}, {"t": 145.9, "who": "coach", "text": "اچھا، کوئی چیز آپ کو ایسی لگتی ہے کلاس میں جو آج آپ نہیں کروا سکیں یا کروانا چاہ رہے تھے؟", "en": "Okay, is there anything you feel you couldn't get done in class today, or wanted to get done?"}, {"t": 150.2, "who": "teacher", "text": "ہاں، اب میں ان کو پریکٹس کرانا چاہ رہی تھی نا، عطف اور شرط جزا کے جملے وہ الگ الگ بنا کے اس کو ڈفرنشییٹ کرتے ہیں۔ اس کے لیے مجھے ٹائم نہیں ملا نا، کیونکہ حروف عطف اور شرط جزا اکٹھے چلتے ہیں نا، تو ان کو پتہ چلتا کہ حروف عطف جو ہیں وہ الگ دو جملوں کو جوڑتے ہیں۔ اور شرط و جزا میں دو حرف ہیں، الگ الگ دو حرف، ان دونوں حرفوں کا ہونا ضروری ہے۔ یہ ابھی رہ گیا۔", "en": "Yes, I wanted to give them practice, making separate sentences with conjunction and with condition-and-consequence and differentiating between them. I didn't get time for that, because the conjunction particles and condition-and-consequence go together, so they would have found out that conjunction particles join two separate sentences, and that condition-and-consequence has two particles, two separate particles, and both of them have to be present. That is what's left."}, {"t": 168.5, "who": "coach", "text": "اچھا، آج کی کلاس میں ہم تھوڑا سا اس ٹائم پہ، تھوڑا سا کم ٹائم لگاتے تو ہم اس کو زیادہ اچھے طریقے سے الائن کر سکتے تھے۔", "en": "Okay, in today's class, if we had spent a little less time on that, we could have aligned it better."}, {"t": 173.7, "who": "teacher", "text": "وہ جو ہم نے کیا ہے نا، سٹارٹ والا۔", "en": "The one we did, at the start."}, {"t": 176.9, "who": "coach", "text": "یس۔", "en": "Yes."}, {"t": 177.3, "who": "teacher", "text": "کمری حروف اور کمری شمسی حروف، جو ہم پہلے کر چکے تھے، اس کو ہم نے زیادہ ٹائم دے دیا۔", "en": "The lunar letters and solar letters, which we had already done before, we gave that too much time."}, {"t": 182.1, "who": "coach", "text": "یس۔ میرا خیال ہے کہ اگر آپ وہاں پہ تھوڑا سا اس کو کرتے کم، تو آٹومیٹکلی یہاں پہ آپ کر سکتے تھے۔ فرسٹ آف آل تو میم، تھینک یو سو مچ کہ آپ کی چھٹی ہو چکی ہے اور آپ مجھے ٹائم دے رہے ہیں۔ ریلی، ریلی آنر فار می۔ تھینک یو سو مچ ونس اگین۔ میم، کلاس واز ویری انگیجنگ، سپورٹیو لرننگ انوائرمنٹ آپ نے کلاس میں بنایا ہوا تھا۔ اور فیڈ بیک واز ویری گڈ کہ آپ بچے کو اس کی پرابلمز اور اس کی مس انڈرسٹینڈنگ کو انڈرسٹینڈنگ میں کنورٹ کر رہے تھے، اس کی سکسیس میں کنورٹ کر رہے تھے۔ یہ بہت اچھی چیز تھی۔ آپ صرف جنیرک کویسچن نہیں پوچھ رہے تھے، آپ اوپن اینڈڈ کویسچن کی طرف بچوں کو لے کے آ رہے تھے، جو کہ ایک بڑی اچھی سٹریٹجی ہوتی ہے۔ وائس بچوں کی سنی جا رہی تھی، بچوں کو ایجنسی دی جا رہی تھی کہ وہ اپنی رائے کا اظہار کریں۔ یہ بہت اچھی تھی آپ کی کلاس میں۔ اور پازیٹو لرننگ انوائرمنٹ تھا، پیئر لرننگ، کولیبریشن کا جو ہے وہ آپ نے انوائرمنٹ کریئیٹ کیا ہوا تھا۔", "en": "Yes. I think if you had spent a little less on that part, you could automatically have done this here. First of all, ma'am, thank you so much that your school day is over and you are still giving me time. It's a real, real honour for me. Thank you so much once again. Ma'am, the class was very engaging; you had created a supportive learning environment in the class. And the feedback was very good, in that you were converting the child's problems and misunderstanding into understanding, converting them into success. That was a very good thing. You weren't only asking generic questions, you were leading the children towards open-ended questions, which is a very good strategy. The children's voices were being heard, the children were being given agency to express their opinions. That was very good in your class. And it was a positive learning environment; you had created an environment of peer learning and collaboration."}, {"t": 216.0, "who": "coach", "text": "اور نو ڈاؤٹ کہ کچھ چیزیں آپ نے بڑی اچھی آئیڈینٹیفائی کیں۔ خود سے سیلف ریفلیکشن از ویری امپورٹنٹ۔ جہاں پہ آپ نے انڈیپنڈنٹ ٹاسک کی بات کی، تو آئی وڈ آلویز سجیسٹ کہ آپ اسی فائیو سٹیپ میں اپنے انڈیپنڈنٹ ٹاسک کو رٹن میں بھی کنورٹ کر سکتے ہیں۔ جیسے آپ نے انڈیپنڈنٹ ٹاسک لکھنے کے لیے دیا تھا، لیکن ماشاءاللہ ایک چیز آپ نے آبزرو کی کہ بچوں کے اندر ماشاءاللہ پاور اور تھنکنگ پاور بہت زیادہ ہے۔ وہ سیکنڈز میں کھڑے کھڑے آپ کو ریپلائی دینا شروع کر دیتے ہیں۔ تو اٹس مین کہ ہمیں اس کو اس کے مائنڈ سیٹ کے ساتھ تھوڑا سا سوئپ کرنا ہے۔ ہمیں کوئی ایسی سٹریٹجی یوز کرنی ہے جس میں آپ نے ایک ٹاسک ان کو دیا تھا انڈیپنڈنٹ کرنے کے لیے، یو ہیو ٹو رائٹ فائیو سنٹنسز۔ لیکن لکھے کسی بچے نے نہیں، لیکن انہوں نے وربلی لکھے۔ یس۔", "en": "And no doubt, you identified some things very well on your own. Self-reflection is very important. Where you spoke about the independent task, I would always suggest that within the same five steps you can also convert your independent task into written form. Like, you gave the independent task to be written, but, masha'Allah, one thing you observed is that the children have a lot of power and thinking power. Within seconds, standing right there, they start replying to you. So it means we need to swap this around a bit, given their mindset. We need to use a strategy where, say, you gave them a task to do independently, you have to write five sentences. But no child wrote them; they gave them verbally. Yes."}, {"t": 251.0, "who": "coach", "text": "تو آپ اس میں یہ سٹریٹجی رکھیں کہ آپ مانیٹرنگ کریں کلاس کی، اور گیو دیم سم ٹائم کہ وہ جب تک لکھیں گے نہیں تو آپ ان سے پوچھیں گے نہیں۔ اس میں یہ ہوگا کہ جب ظاہر ہے ہم کاپی ورک بھی کروانا چاہتے ہیں، اکثر ہمارا کاپی ورک اس وجہ سے رہ جاتا ہے کہ ہم صرف وہ وربلی یا اورلی رسپانسز پہ کام کر رہے ہوتے ہیں۔ تو میں یہ سجیسٹ کروں گا جہاں پہ آپ کو ایکسپلینیشن پارٹ بہت پرولانگ تھا، آپ وہاں پہ اس میں سے، جیسے آپ نے اس میں سے بھی کہا تھا کہ حروف لکھیں۔", "en": "So in that, make this your strategy: monitor the class, and give them some time, so that until they have written, you won't ask them. What will happen is that, obviously, we also want to get copy work done, and often our copy work gets left out because we are only working on verbal or oral responses. So I would suggest that where the explanation part was very prolonged, there, from that, like you also said in it, to write the letters."}, {"t": 286.5, "who": "teacher", "text": "ہاں۔", "en": "Yes."}, {"t": 286.7, "who": "coach", "text": "تو میرا خیال ہے یہ جب کل چیز گزر چکی تو اس کو صرف ری کال تک ہی رکھنا ہے۔", "en": "So I think, once everything from yesterday has passed, you should keep it only to recall."}, {"t": 289.7, "who": "teacher", "text": "ری کال تک۔", "en": "Only to recall."}, {"t": 290.5, "who": "coach", "text": "پھر ری کال کر کے آپ ان کو پوچھتے ہیں اور پوائنٹس نکلتے ہیں۔ ہم نے یہ پڑھا تھا کل۔ اور آج آپ اسی کو حروف عطف اور حروفِ شرط و جزا سے ریلیٹ کرتے۔ اور میرا خیال ہے جب آپ ان کے سنٹنسز دے رہے تھے تو کچھ بچوں نے سٹارٹ کیا، لیکن جب آپ نے اس کے رسپانسز دینا شروع کر دیے فوراً سے، تو ظاہر ہے وہ پھر سب بچوں نے رسپانسز وربلی دینا شروع کر دیے۔", "en": "Then, after recalling, you ask them and points come out. We studied this yesterday. And today you would relate that to the conjunction particles and the condition-and-consequence particles. And I think when you were giving them the sentences, some children started, but when you immediately started giving the responses, then naturally all the children started giving responses verbally."}, {"t": 308.7, "who": "teacher", "text": "دینا شروع کر دیے۔ انہوں نے رائٹنگ سٹاپ کر دی۔", "en": "Started giving them. They stopped writing."}, {"t": 310.5, "who": "coach", "text": "رائٹنگ سٹاپ کر دی۔ تو اس چیز کو میک شور کریں کہ انسٹرکشنز کے بعد کلیرٹی آپ نے ظاہر ہے دینی ہے کہ آپ اس چیز کو پھر ان کو دیں ٹائم کہ آپ نے لکھنا ہے، تب میں آپ سے رسپانسز لوں گی۔ ایک اس پہ تھوڑا سا ورک آؤٹ کریں۔ اور ایک میں چاہ رہا تھا چیز کہ جیسے پیئر سیلف اسیسمنٹ ہے۔ جیسے فار ایگزامپل ایک بچے پانچ سنٹنسز لکھی ہیں انہوں نے۔ آپ ان کی کاپیز کو سوئپ کر دیں۔ کہ آپس میں کہہ دیں کہ بیٹا آپ اس کی کاپی چیک کریں۔", "en": "They stopped writing. So make sure that after the instructions you obviously give clarity, and then give them time, saying you have to write, then I will take responses from you. Work out something on that. And one more thing I wanted, like peer self-assessment. For example, a child has written five sentences. You have them swap their copies, tell them among themselves, 'dear, you check this one's copy.'"}, {"t": 331.4, "who": "teacher", "text": "اچھا۔", "en": "Okay."}, {"t": 331.6, "who": "coach", "text": "آپ اس کی کاپی چیک کریں۔ تو یہ آپ کے پاس ہوگا کہ چیک کریں گے وہ ایک دوسرے کی کاپیز پہ۔ اس پہ نا وہ انگیج رہیں گے۔", "en": "You check their copy. So you'll have this: they will check each other's copies. They will stay engaged in that."}, {"t": 337.5, "who": "teacher", "text": "اچھا۔", "en": "Okay."}, {"t": 337.8, "who": "coach", "text": "اصل میں ان کی انگیجمنٹ سٹریٹجی پہ کام کرنے کی ضرورت ہے، بیکاز دے آر ویری ہائیلی ایکٹو۔ تو جب آپ ان کو ایکٹو رکھیں گے تو میرا خیال ہے انگیج رکھیں گے تو آپ کی کلاس میں ڈسٹربنس کم ہو گی۔ وہ انگیج ہو جائیں گے ایک دوسرے کی کاپی چیکنگ میں۔ وہ انگیج ہو جائیں گے نئے لرننگ کے پوائنٹ آف ویو پر۔ دیکھیں، ہو سکتا ہے جو پانچ جملے اس نے لکھے ہیں وہ اس نے نہیں لکھے ہوں۔ لیکن جب وہ سوئپ کریں گے کاپیز تو وہ اس کے فائیو سنٹنسز پڑھ کے اس میں سے مسٹیک نکالے گا اور یہ بچہ جو ہے وہ اس کو نکالے گا۔ تو میرا خیال ہے وہ آپ کا ٹائم جو تھوڑا بہت جو ڈسٹربنس ہمیں لگ رہی ہوتی ہے وہ بھی آٹومیٹکلی اس میں کم ہو جائے گی۔", "en": "Actually, we need to work on their engagement strategy, because they are very highly active. So when you keep them active, I think when you keep them engaged, there will be less disturbance in your class. They'll be engaged in checking each other's copies. They'll be engaged from the point of view of new learning. See, it may be that the five sentences one child wrote, they didn't write them well. But when they swap copies, that child will read the other's five sentences and find the mistakes in them, and this child will find them in turn. So I think the bit of disturbance that we notice will also automatically reduce in your time."}, {"t": 363.9, "who": "teacher", "text": "ان شاء اللہ۔", "en": "God willing."}, {"t": 364.8, "who": "coach", "text": "تو یہ دو تین چیزیں ہیں۔ باقی وارم اپ ہر چیز آپ نے اکارڈنگ ٹو دا لیسن پلان کی۔ اور ونس اگین تھینک یو سو مچ فار یور ٹائم۔ اور ماشاءاللہ کیپ آپ دا گڈ ورک ڈون۔ تھینک یو سو مچ۔", "en": "So these are two or three things. Otherwise, the warm-up and everything else you did according to the lesson plan. And once again, thank you so much for your time. And masha'Allah, keep up the good work. Thank you so much."}, {"t": 373.7, "who": "teacher", "text": "تھینک یو۔", "en": "Thank you."}], "phases": [{"name": "Greeting and invitation to name best practices", "t": 0.5}, {"name": "Teacher reflects on strengths (coach prompts and credits)", "t": 20.4}, {"name": "Teacher names what they could not do (time)", "t": 145.9}, {"name": "Coach praise then growth: writing task and pacing", "t": 182.1}, {"name": "Coach elaborates: recall-only, writing time, peer swap", "t": 286.5}, {"name": "Close without agreed step", "t": 364.8}], "notes": [{"line": 6, "kind": "strength", "dim": "coach_questioning_and_dialogue", "text": "A 'why' question lets the teacher link their own explanation to student participation, and the coach then credits the cause.", "better": null}, {"line": 18, "kind": "strength", "dim": "teacher_self_reflection", "text": "An open invitation to name what was missed gets a specific, self-identified gap from the teacher.", "better": null}, {"line": 30, "kind": "missed_opportunity", "dim": "coach_questioning_and_dialogue", "text": "The teacher noticed the cause (children stopped writing) but the coach supplies both the diagnosis and the fixes, and adds a second fix, so the teacher never proposes their own change.", "better": "When the teacher says 'they stopped writing', ask 'What could you do at that moment so they keep writing?', let the teacher suggest a change, and then agree on just that one change."}, {"line": 38, "kind": "missed_opportunity", "dim": "commitment_and_follow_up", "text": "The meeting ends with 'two or three things' and thanks, with no single agreed step, no teacher restatement and no follow-up.", "better": "Ask the teacher 'Of these, which one will you try in your next lesson, and how will you do it?', let them say it in their own words, and agree when the coach will see it or what student writing to look at."}], "scores": {"purpose_and_relationship_opening": 1, "teacher_self_reflection": 2, "coach_questioning_and_dialogue": 2, "evidence_from_the_lesson": 2, "focus_on_one_growth_area": 1, "concrete_action_step": 1, "practice_or_modelling": 0, "commitment_and_follow_up": 1, "tone_and_psychological_safety": 2}, "overall": 41, "lang": "ur", "rtl": true}, {"id": "dcf9ada74fc", "tab": "Punjab: a strong debrief", "title": "A strong debrief", "why": "7.1 minutes with clean speaker turns, and the closest to the ideal arc in the group (overall 60, tied highest). The coach thanks the teacher and frames the visit as joint work for children's learning, gives specific praise (the word break-and-join method and the doubled-letter explanation, with why it helps children), and asks what went well and what could improve. The coach then names exactly one growth area ('one suggestion, one feedback, one improvement'), links it to the HOTS indicator and the printed lesson plan, gives sample questions, and the teacher restates the step in their own words. Use it to show the shape, and to show the three missing pieces: the teacher's own concern (a shy child mumbling) is dropped, nothing is rehearsed, and no day is set. The two coach turns of about 2.5 minutes each are also worth discussing.", "audio": "full/dcf9ada74fc.mp3", "duration": 425.2, "programme_label": "Punjab", "coach": "PB Coach 30", "lines": [{"t": 1.1, "who": "coach", "text": "Thank you so much, ma'am. First of all, تو آپ نے کلاس آبزرو کرنے کا موقع دیا مجھے، اور مجھے ویلکم کیا اپنی کلاس میں۔ This is too much اور اس کے لیے میں آپ کی appreciate بھی کرتا ہوں۔ Thank you so much. میم، ہمارا مقصد ہوتا ہے کہ ہم ساتھ مل کے بچوں کی بہتری کے لیے، بچوں کی understanding کے لیے، بچوں کا learning outcome جو ہے اس کو بہتر بنانے کے لیے، ہم مل کے جو ہے وہ بچوں کے لیے کام کریں۔ تو اس کے لیے جو ہے یہ observation لی گئی آپ کی کلاس کی۔", "en": "Thank you so much, ma'am. First of all, you gave me the chance to observe the class and welcomed me into your classroom. This is too much, and I appreciate you for it. Thank you so much. Ma'am, our aim is that together, for the betterment of the children, for the children's understanding, to improve the children's learning outcomes, we work together for the children. That is why this observation of your class was done."}, {"t": 36.0, "who": "coach", "text": "First of all تو میم، آپ نے بچوں کو جب توڑ پھوڑ، توڑ جوڑ کروائی، وہ بہت اچھے سے بچوں کو جو ہے وہ کلاس میں آپ نے اس کو model بھی کیا اور portray بھی کیا، وہ اس sense میں کہ ایک ایک word کو جو ہے آپ نے توڑ کے ان کو سمجھایا کہ آپ یہ والا word جو ہے آپ اس کو کس طرح توڑ سکتے ہیں۔", "en": "First of all, ma'am, when you had the children do the breaking and joining of words, you modelled and portrayed it very well in class, in the sense that you broke each word apart and explained to them how this word can be broken down."}, {"t": 59.2, "who": "coach", "text": "پھر آپ نے ایک word کا جس کا محلہ، I think so، وہی word تھا جس میں وہ شد کی آ رہی تھی، تو آپ نے وہ بہت اچھے سے سمجھایا کہ اب یہاں پہ لام کو ہم دو بار کیوں پڑھتے ہیں، کیونکہ اس پہ شد ہے۔ تو شد کے جو مشدد الفاظ ہوتے ہیں، ان کو ہم دو بار، دو بار جو ہے وہ ہم بولتے ہیں، کیونکہ ان پہ شد ہوتا ہے، اور اسی وجہ سے ہم دو بار جو ہے ان کو repeat کرتے ہیں۔ ایک ہ کے ساتھ مہا، ہ کے ساتھ لام پڑھتے ہیں، اور دوسرا جو ہے وہ لام دوسری بڑی ہ کے ساتھ لام پڑھتے ہیں۔", "en": "Then there was a word, \"mohalla\" I think, the word in which the shadda was coming up, and you explained very well why we read the laam twice here, because it has a shadda. Words with a shadda, the doubled letters, we say twice, because they carry a shadda, and that is why we repeat them twice. One laam is read with the first letter, and the other laam is read with the next letter."}, {"t": 94.1, "who": "coach", "text": "تو اس طرح کی جو آپ توڑ جوڑ یا اس طرح جو آپ سمجھاتے ہیں، تو بچوں کو ایک تو یہ confusion نہیں رہتی دو چیزوں میں کہ آپ for example اگر یہاں پہ شد ہے یا یہ جو ایک نقطہ سا آیا ہوا ہے، اس نقطے کا کیا مطلب ہے، یا یہ جو ایک sign بنا ہوا ہے شد کا، وہ ہے کیا چیز۔ بچوں کو اس سے بھی سمجھ آ جاتی ہے۔", "en": "So when you explain through this kind of breaking and joining, the children, first of all, don't stay confused about things, for example if there is a shadda here, or this little dot that has appeared, what does that dot mean, or this sign that is drawn for the shadda, what is it. The children understand that from this too."}, {"t": 121.5, "who": "coach", "text": "اور دوسرا یہ ان کو آ جاتی ہے کہ اب اگر کسی word پہ، کسی لفظ پہ شد ہو تو وہ کیوں دو بار پڑھی جاتی ہے، یا یہ محلہ میں لام کو ہم دو بار کیوں پڑھتے ہیں۔ تو آپ نے وہ بہت اچھے سے کیا، that was good، اور بچوں کو سمجھ بھی آ گئی تھی۔", "en": "And second, they come to understand that if a word has a shadda, why it is read twice, or why we read the laam twice in \"mohalla\". So you did that very well, that was good, and the children understood as well."}, {"t": 140.5, "who": "coach", "text": "اس کے علاوہ آپ مجھے بتائیے گا کہ آپ کی کلاس میں کیا اچھا رہا، اور کیا چیز آپ کو لگتا ہے کہ improve ہونی چاہیے؟", "en": "Apart from that, please tell me what went well in your class, and what you feel should be improved?"}, {"t": 148.4, "who": "teacher", "text": "سر، بچوں کی participation، بچے وہ جیسے آپ observe کے لیے بیٹھے تھے، تو وہ شاید fail کر رہے تھے، حالانکہ بچی کو آتا تھا، وہ منہ میں بڑبڑا رہی ہے، لیکن وہ اونچی آواز میں نہیں بول رہی۔", "en": "Sir, the children's participation. Since you were sitting there to observe, they were probably failing, even though the girl knew it. The child was mumbling it under their breath, but not saying it aloud."}, {"t": 159.2, "who": "coach", "text": "ٹھیک ہے۔", "en": "Okay."}, {"t": 159.6, "who": "teacher", "text": "تو بس میں یہی چاہتی ہوں کہ بچے تھوڑے confident ہو جائیں جب میرے سامنے وہ صحیح response دیتے ہیں، لیکن جب کوئی نیا بندہ آتا ہے تو وہ confuse ہو جاتے ہیں تھوڑے سے۔", "en": "So I just want the children to become a bit more confident. They give the right response in front of me, but when a new person comes they get a little confused."}, {"t": 167.5, "who": "coach", "text": "ٹھیک ہے۔", "en": "Okay."}, {"t": 167.9, "who": "teacher", "text": "اسی لیے وہ صحیح response نہیں دیتے، حالانکہ انہیں آتا ہوتا ہے۔", "en": "That is why they don't give the right response, even though they know it."}, {"t": 170.4, "who": "coach", "text": "ٹھیک ہے۔", "en": "Okay."}, {"t": 171.0, "who": "teacher", "text": "پڑھنا بھی آ رہا ہوتا ہے، انہیں اب انہیں act کرنا سب بچوں کو آتا ہے، لیکن وہ act نہیں کر رہے۔", "en": "They can read too, and all the children know how to act it out, but they are not acting."}, {"t": 175.8, "who": "coach", "text": "بالکل، تھوڑا سا وہ confidence میں وہ confusion ہوتی ہے۔", "en": "Exactly, there is a little confusion in their confidence."}, {"t": 180.3, "who": "teacher", "text": "Confusion ہوتی ہے بچوں کی طرف سے۔", "en": "There is confusion on the children's side."}, {"t": 181.3, "who": "coach", "text": "ٹھیک ہے۔ اور کیا، کیا اچھا رہا آپ کی کلاس میں آج کا؟ جو آپ سمجھتی ہیں کہ یہ بہت اچھا رہا، اور یہ یہ یہ aspect جو ہے وہ آپ میری کلاس کا بہت اچھا تھا۔ یہ تو آپ نے بتایا نا کہ یہ چیز ہونی چاہیے، یا یہ اچھی ہونی چاہیے کہ student تھوڑا سا confident ہو جائے۔ ایسی کیا چیز تھی جو آپ کو آج کی کلاس میں لگا کہ یہ بہت اچھا رہا، throughout the کلاس؟", "en": "Okay. And what else, what went well in your class today? What do you feel went very well, and which aspect of my class was very good? You told me what should happen, or what should be better, that the students become a bit more confident. What was it that you felt went very well in today's class, throughout the class?"}, {"t": 203.4, "who": "teacher", "text": "سر، جوڑ توڑ سے جو سکھایا ہے بچوں کو اردو پڑھنا، وہ بچوں نے بہت اچھا pick کر لیا۔ یہ بہت اچھا رہا آج۔", "en": "Sir, teaching the children to read Urdu through joining and breaking, the children picked that up very well. That went very well today."}, {"t": 209.7, "who": "coach", "text": "صحیح۔ صحیح۔", "en": "Right. Right."}, {"t": 210.6, "who": "teacher", "text": "میری کلاس میں۔", "en": "In my class."}, {"t": 211.6, "who": "coach", "text": "ٹھیک ہے۔", "en": "Okay."}, {"t": 212.2, "who": "teacher", "text": "اور بچے اچھا response کر رہے تھے، چیپٹر کی سمجھ آ گئی، سبق کی ساری۔", "en": "And the children were responding well, they understood the chapter, the whole lesson."}, {"t": 216.5, "who": "coach", "text": "ٹھیک ہے۔", "en": "Okay."}, {"t": 217.0, "who": "teacher", "text": "اسی لیے، کیونکہ یہ ایک تو topic جو real life سے related تھا آج کا، اس کی وجہ سے تو بچے تو کافی how now تھے اس topic میں۔", "en": "That is because today's topic was related to real life, so the children were quite [how now] in this topic."}, {"t": 224.3, "who": "coach", "text": "صحیح۔", "en": "Right."}, {"t": 224.6, "who": "teacher", "text": "جس کی وجہ سے ان کا response کافی اچھا تھا۔", "en": "Because of which their response was quite good."}, {"t": 226.5, "who": "coach", "text": "ٹھیک۔ ٹھیک۔ ٹھیک۔", "en": "Okay. Okay. Okay."}, {"t": 228.3, "who": "teacher", "text": "اس لیے کہ یہ بچوں کی real life سے تھوڑا وہ دیکھتے رہتے ہیں، پڑھائی میں کام کر رہا ہے، ڈاکٹر ہے وہ ہمارا علاج کرتا ہے۔", "en": "Because this is from the children's real life, they keep seeing it, someone doing a job, a doctor who treats us."}, {"t": 234.1, "who": "coach", "text": "صحیح۔", "en": "Right."}, {"t": 234.4, "who": "teacher", "text": "تو اس لیے response بچوں کا اچھا تھا۔ باقی وہ جو تھوڑے سے side effects ہیں، shyness وغیرہ، وہ تو ہے۔", "en": "So that is why the children's response was good. As for the rest, the few side effects like shyness, that is there."}, {"t": 240.4, "who": "coach", "text": "ہاں، وہ تو obviously آپ کی بات بھی ٹھیک ہے کہ کوئی نیا بندہ اگر آتا ہے تو ان کے لیے تھوڑا سا۔", "en": "Yes, obviously, you are right too, that if a new person comes, it is a bit..."}, {"t": 244.8, "who": "teacher", "text": "بچے shy feel کرتے ہیں۔", "en": "The children feel shy."}, {"t": 245.7, "who": "coach", "text": "ہاں، وہ ہوتے ہیں۔ میم، میں ایک ہی suggestion دوں گا آپ کو، ایک ہی فیڈبیک اور ایک ہی امپروومنٹ جو ہے ہم ابھی ان کلاس کے لیے وہ کریں گے۔ نیکسٹ کلاس میں جب بھی میں آؤں گا تو انشاءاللہ نیکسٹ بھی اس پہ فوکس کریں گے۔", "en": "Yes, they do. Ma'am, I will give you just one suggestion, one piece of feedback and one improvement that we will work on for this class. Whenever I come to the next class, God willing, we will focus on it next time too."}, {"t": 258.7, "who": "coach", "text": "وہ یہ ہوگی کہ آپ تھوڑا سا سٹوڈنٹس کو جو ہے موقع دیا کریں کہ وہ تھوڑا سا کریٹیکل تھنکنگ کی طرف چلے جائیں۔ وہ اس طرح کہ آپ ان سے اوپن اینڈڈ کویسچن کیا کریں۔", "en": "It is that you give the students a bit of a chance to move towards critical thinking. The way to do that is to ask them open-ended questions."}, {"t": 269.0, "who": "coach", "text": "اوپن اینڈڈ کویسچن کا یہ مطلب ہے کہ فار ایگزامپل اگر آپ نے ان کو سارے پروفیشنز پڑھائے ہیں، آپ نے کسان کا پڑھایا، آپ نے درزی کا پڑھایا، پائلٹ ہو گیا، فار ایگزامپل بڑھئی ہو گیا، ٹھیک ہے، ہاتھ روگ ہو گیا، تو جتنے بھی پروفیشن آپ نے پڑھائے، بچوں کو ہاں سمجھ آ گئی کہ یہ والا جو پروفیشن ہے، یہ یہ والا جو بندہ ہوتا ہے، یہ یہ کام کر رہا ہوتا ہے۔", "en": "An open-ended question means, for example, if you have taught them all the professions, you taught the farmer, you taught the tailor, the pilot, for example the carpenter, okay, and so on, then for all the professions you taught, the children understood that this profession is this kind of person who does this kind of work."}, {"t": 291.6, "who": "coach", "text": "اگر آپ ان سے اس طرح پوچھیں کہ اب فار ایگزامپل جو درزی ہے، کیا وہ جہاز چلا سکتا ہے؟ کیا درزی ہاتھ روگ ہو سکتا ہے؟ کیا ڈاکٹر جو ہے وہ درزی ہو سکتا ہے؟ تو وہ تھوڑا سا اس چیز کو سوچیں گے کہ اچھا اگر درزی ہے تو کیا وہ دوسرا کام کر سکتا ہے؟ یا وہ کسان ہو سکتا ہے؟ بالکل ہو سکتا ہے۔", "en": "If you ask them, for example, can the tailor fly a plane? Can a tailor be [a different profession]? Can a doctor be a tailor? Then they will think about it a little: okay, if they are a tailor, can they do other work? Can they be a farmer? Absolutely they can."}, {"t": 312.1, "who": "coach", "text": "کیونکہ آج کل مطلب کہ ہمارے گاؤں میں یا جو بھی اس طرح کے لوگ ہوتے ہیں، وہ ہر کام تقریباً کر رہے ہوتے ہیں۔ لیکن ان کو تھوڑا سا سوچنے کا موقع ملے گا کہ اچھا اگر کوئی درزی ہے تو وہ شاید کسان بھی ہو سکتا ہے، وہ جو ہے وہ کٹائی بھی کر سکتا ہے۔", "en": "Because these days, in our villages or wherever such people are, they do pretty much every kind of work. But they will get a chance to think a little: okay, if someone is a tailor, maybe they can be a farmer too, they can do the harvesting as well."}, {"t": 326.5, "who": "coach", "text": "تو اس طرح کے اوپن اینڈڈ کویسچن جو ہے آپ ان سے پوچھ سکتے ہیں۔ یا یہ بھی پوچھ سکتے ہیں کہ درزی کو ہم درزی کیوں کہتے ہیں؟ درزی کو ہم کچھ اور جہاز، فار ایگزامپل درزی کو ہم جو ہے وہ پائلٹ کیوں نہیں کہتے؟ تو اس طرح کے کویسچن ہوتے ہیں جو تھوڑا سا سٹوڈنٹس کو مجبور کرتے ہیں کہ وہ تھوڑا سا کریٹیکل تھنکنگ کی طرف چلے جائیں۔", "en": "So you can ask them open-ended questions like these. Or you can ask, why do we call a tailor a tailor? Why don't we call a tailor something else, a pilot for example? Questions like these push the students a little to move towards critical thinking."}, {"t": 349.1, "who": "coach", "text": "کیونکہ ہارٹس کے جو انڈیکیٹر ہیں، وہ بھی آج کل اسی پہ آ رہا ہے کہ سٹوڈنٹ کو کریٹیکل تھنکنگ کا جو ہے وہ آپ لوگ موقع دیا کریں۔ تو اس پہ آپ نیکسٹ ٹائم جو ہے وہ تھوڑا سا فوکس کر لیجیے گا اوپن اینڈڈ کویسچن کے لیے۔", "en": "Because the HARTS indicators are also coming to this these days, that you people should give students a chance for critical thinking. So next time, please focus a little on this, on open-ended questions."}, {"t": 362.8, "who": "coach", "text": "وہ آپ کے لیسن پلان میں بھی موجود ہوتے ہیں، اوپن اینڈڈ کویسچن جو آپ کے جو پرنٹڈ لیسن پلان ہے، اس میں موجود ہیں۔ آپ کے ایکٹیویٹیز ہیں، اوپن اینڈڈ کویسچنز ہیں، سب کچھ اسی میں ہے۔ آپ اس کو فالو کیا کریں، انشاءاللہ آپ کی وہ آئے گی۔", "en": "They are also present in your lesson plan: the open-ended questions are in your printed lesson plan. The activities, the open-ended questions, everything is in it. Please follow it, and God willing it will come to you."}, {"t": 378.6, "who": "coach", "text": "میم، لاسٹ میں مجھے آپ یہ بتائیے گا کہ آپ کیا ایک ایک ایسا پوائنٹ یا ایک ایسا اسپیکٹ کہ آپ کہتی ہیں کہ یہ والا جو ہے میں انشاءاللہ اس کو فالو کروں گی نیکسٹ ٹائم پہ، اور آئی پرومس کہ مطلب یا آپ ایک عہد کر لیتی ہیں کہ جو ہے میں اس کو امپروو بھی کریں گی اور انشاءاللہ کوشش بھی کروں گی اس کو۔", "en": "Ma'am, lastly, please tell me one point or one aspect that you say you will, God willing, follow next time, and I promise, I mean, you make a pledge that you will improve it and, God willing, will try."}, {"t": 395.7, "who": "teacher", "text": "یہی بات آپ کی والی اوپن اینڈڈ کویسچن۔ اس کو کریٹیکل تھنکنگ میں۔", "en": "This same point of yours, the open-ended questions. Into critical thinking."}, {"t": 400.2, "who": "coach", "text": "ٹھیک ہے۔", "en": "Okay."}, {"t": 400.5, "who": "teacher", "text": "پھر بچوں سے انہیں سوچنے پہ مجبور کرنا کہ میں نیکسٹ ٹائم انشاءاللہ ضرور کوشش کروں گی کہ یہ سوال امپروو کروں، تاکہ بچے اچھا سیکھیں۔", "en": "Then making the children think. Next time, God willing, I will definitely try to improve these questions so that the children learn well."}, {"t": 408.0, "who": "coach", "text": "ٹھیک۔", "en": "Okay."}, {"t": 408.8, "who": "teacher", "text": "ان کو سوچیں وہ۔", "en": "Let them think."}, {"t": 412.0, "who": "coach", "text": "ٹھیک ہے۔ ٹھیک ہے اوکے۔ تھینک یو سو مچ میم۔ ونس اگین، تھینک یو سو مچ فار آپ کی کلاس نے مجھے آنے دیا۔ اینڈ انشاءاللہ نیکسٹ ٹائم جو بھی ہماری انفارمیشن ہوگی تو اس پہ نیکسٹ، اس پہ انڈیکیٹرز پہ فوکس کریں گے۔ تھینک یو میم۔ اللہ حافظ۔", "en": "Okay. Okay, fine. Thank you so much, ma'am. Once again, thank you so much for letting me into your class. And God willing, next time, whatever information we have, we will focus on those indicators. Thank you, ma'am. Goodbye."}], "phases": [{"name": "Greeting, purpose and specific praise", "t": 1.1}, {"name": "Teacher reflection (strength and difficulty)", "t": 148.4}, {"name": "One growth area with sample questions", "t": 245.7}, {"name": "Teacher commitment", "t": 395.7}, {"name": "Close", "t": 412.0}], "notes": [{"line": 15, "kind": "strength", "dim": "coach_questioning_and_dialogue", "text": "The coach re-asks an open question to draw out the teacher's own view of what worked, and the teacher answers in their own words.", "better": null}, {"line": 6, "kind": "missed_opportunity", "dim": "focus_on_one_growth_area", "text": "The teacher names a specific, student-based difficulty that could have been the growth area, but the coach says 'OK' and later chooses a different area.", "better": "Ask what the teacher does to help a hesitant child speak up and build the next step from that (for example, think-pair-share before answering aloud), so the step answers the teacher's own concern."}, {"line": 40, "kind": "missed_opportunity", "dim": "commitment_and_follow_up", "text": "The teacher states the step in their own words, which is good, but there is no lesson, day or sign of success and the coach closes without a date or a check-in.", "better": "Ask the teacher which topic tomorrow they will use it in, have them say the exact question they will ask, and agree a date and a sign that it worked (for example, more children giving reasons)."}], "scores": {"purpose_and_relationship_opening": 2, "teacher_self_reflection": 2, "coach_questioning_and_dialogue": 2, "evidence_from_the_lesson": 2, "focus_on_one_growth_area": 3, "concrete_action_step": 2, "practice_or_modelling": 1, "commitment_and_follow_up": 1, "tone_and_psychological_safety": 2}, "overall": 60, "lang": "ur", "rtl": true}, {"id": "d0918aacc75", "tab": "Tanzania: a strong debrief", "title": "A strong debrief", "why": "The highest corrected score in the group (57) with clean speaker turns and a length of 4 min 6 s. It follows most of the ideal arc: greeting and a support purpose, praise that quotes the teacher's own opening question and pupils' answers, an open 'what made you' question about a specific moment, a long teacher answer with pupil examples that politely corrects the coach, a coach who accepts the correction, one step offered as an invitation ('Unalionaje, mwalimu?'), a 'when' question, and a teacher who invites the coach back the next day. It still lacks rehearsal and a success sign, which no debrief here has.", "audio": "full/d0918aacc75.mp3", "duration": 247.2, "programme_label": "Tanzania", "coach": "TZ Coach 17", "lines": [{"t": 0.8, "who": "teacher", "text": "Mhm.", "en": "Mhm."}, {"t": 1.8, "who": "coach", "text": "Halo, mwalimu [name].", "en": "Hello, teacher [name]."}, {"t": 4.1, "who": "teacher", "text": "Ndiyo.", "en": "Yes."}, {"t": 5.1, "who": "coach", "text": "Nakushukuru kwa kunikaribisha darasani kwako. Lengo letu ni kuwasaidia watoto wetu ili waweze kujifunza kwa ufasaha na waweze kufanya vizuri na kufikia ndoto zao. Ninakushukuru sana kwa jinsi ambavyo uliweza kuelezea lengo la somo la leo, kwamba ilikuwa ni kuunda sentensi kwa kutumia maneno \"has\" na \"have\".", "en": "Thank you for welcoming me into your classroom. Our aim is to help our children learn well, do well, and reach their dreams. Thank you very much for how you explained the objective of today's lesson, that it was to form sentences using the words \"has\" and \"have\"."}, {"t": 34.1, "who": "coach", "text": "Lakini pia, nilifurahishwa sana na somo lako la leo, kwani uliwaelezea wanafunzi mifano mbalimbali ya matumizi ya \"has\" na \"have\". Lakini pia kulikuwa na ufafanuzi wa kutosha wa pronoun zinazotumika na \"has\" na \"have\".", "en": "But I was also very pleased with your lesson today, because you explained various examples of how to use \"has\" and \"have\" to the students. There was also enough explanation of the pronouns used with \"has\" and \"have\"."}, {"t": 57.5, "who": "teacher", "text": "Ndiyo, mwalimu. Nilifanya hivyo ili kujua kama wanakumbuka tulichojifunza jana.", "en": "Yes, teacher. I did that to find out whether they remember what we learned yesterday."}, {"t": 64.0, "who": "coach", "text": "Asante, mwalimu. Lakini pia, nilifurahi pale ulipowauliza wanafunzi, kabla ya kuanza somo, uliwauliza kwamba \"Who can tell me what did we learn about yesterday?\" na nilipenda wanafunzi wote walivyojibu, kwamba somo lilikuwa ni matumizi ya \"has\" na \"have\", kwani wanafunzi walirudia kujibu eneo hilo.", "en": "Thank you, teacher. I was also glad when you asked the students, before starting the lesson, \"Who can tell me what did we learn about yesterday?\" and I liked how all the students answered that the lesson was the use of \"has\" and \"have\", since the students kept answering about that topic."}, {"t": 97.4, "who": "coach", "text": "Lakini pia, mwalimu, nina swali kidogo. Kwa mfano, wakati unafundisha, niliona wanafunzi wanarudia sentensi. Wewe ni nini kilikufanya usiwaambie aidha mmoja mmoja au wawili waunde sentensi zao wenyewe?", "en": "But teacher, I also have a small question. For example, while you were teaching, I saw the students repeating sentences. What made you not tell them, either one by one or in pairs, to make up their own sentences?"}, {"t": 120.3, "who": "teacher", "text": "Ndiyo, walikuwa hawarudii sentensi, bali nilichokiona walikuwa wanarudia baadhi ya pronouns na objects walizokuwa wanazitumia kutunga majina. Kwa mfano, mmoja anaweza akasema, \"She has a book.\" Mwingine akarudia tena, \"She has a ruler.\" Au mwingine akasema, \"He has a book.\" Yaani, wanachokibadilisha, aidha wanabadilisha pronoun au wanabadilisha object. Niliwaelekeza, nikawaambia, tunga kwa kutumia pronouns, ziko nyingi, lakini objects za kutumia pia ziko nyingi, na ninaona nilivyowarekebisha hivyo, walifanya marekebisho na wakaanza kutumia pronouns na objects tofauti na mwenzake.", "en": "Yes, they weren't repeating sentences; what I saw was that they were repeating some of the pronouns and objects they were using to compose sentences. For example, one might say, \"She has a book.\" Another repeats, \"She has a ruler.\" Or another says, \"He has a book.\" That is, what they change is either the pronoun or the object. I guided them, telling them, make sentences using pronouns, there are many, but there are also many objects to use, and I see that after I corrected them that way, they made adjustments and started using pronouns and objects different from their classmate's."}, {"t": 166.5, "who": "coach", "text": "Asante sana, mwalimu. Ni kweli, nami nilishuhudia hayo. Lakini vipi kuhusu, labda, ukijaribu katika kipindi kingine kuwaambia wanafunzi wakiwa wawili au zaidi, waombe watunge sentensi au habari kwa kutumia \"has\" na \"have\" na kuwataka wawasilishe hadithi hizo au habari hiyo mbele ya darasa? Na wewe ukiwepo ili kuweza kufanya marekebisho pale inapohitajika, na kuwapongeza pia kwa pale itakapohitajika. Unalionaje, mwalimu?", "en": "Thank you very much, teacher. That's true, I witnessed that too. But what about, perhaps, trying in another lesson to tell the students, in groups of two or more, to make up sentences or a short story using \"has\" and \"have\" and then have them present those stories or that information in front of the class? With you present to make corrections where needed, and to praise them where needed too. What do you think, teacher?"}, {"t": 204.3, "who": "teacher", "text": "Nashukuru kwa ushauri huo, mwalimu. Nitajitahidi kipindi kijacho nifuate kama ulivyonielekeza, ili tuweze kufanyia mazoezi hicho ulichonielekeza, na ninaamini tutafanikiwa.", "en": "Thank you for that advice, teacher. I will try in the next lesson to follow what you have guided me to do, so we can practise what you directed me to, and I believe we will succeed."}, {"t": 218.1, "who": "coach", "text": "Asante sana, mwalimu. Labda unadhani kwa kesho ni wakati gani unaweza ukalifanya hili?", "en": "Thank you very much, teacher. Perhaps when do you think you could do this tomorrow?"}, {"t": 223.8, "who": "teacher", "text": "Wakati wa kipindi cha Kiingereza kitakapofika.", "en": "When the English lesson comes."}, {"t": 227.6, "who": "coach", "text": "Asante sana. Basi, mwalimu, nikutakie majukumu mema katika kuhakikisha kwamba tunawasaidia watoto wetu ili waweze kufikia ndoto zao.", "en": "Thank you very much. Well then, teacher, I wish you well in your duties as we make sure we help our children reach their dreams."}, {"t": 237.5, "who": "teacher", "text": "Asante pia, mwalimu, na wewe kwa kunipa muda wako. Asante, na karibu tena katika kipindi changu siku ya kesho.", "en": "Thank you too, teacher, for giving me your time. Thank you, and you're welcome again in my lesson tomorrow."}, {"t": 245.0, "who": "coach", "text": "Asante sana, mwalimu.", "en": "Thank you very much, teacher."}], "phases": [{"name": "Greeting", "t": 0.8}, {"name": "Thanks, purpose and specific praise (lesson objective, examples, pronouns)", "t": 5.1}, {"name": "More praise and open question about students repeating sentences", "t": 64.0}, {"name": "Teacher explains what students did", "t": 120.3}, {"name": "Coach suggests pair/group sentence creation and asks view", "t": 166.5}, {"name": "Teacher accepts and commits", "t": 204.3}, {"name": "Close and invitation to next lesson", "t": 227.6}], "notes": [{"line": 8, "kind": "strength", "dim": "teacher_self_reflection", "text": "The teacher gives a specific, student-based account and shows the students were already composing, which is useful evidence for the coach to build on.", "better": null}, {"line": 9, "kind": "missed_opportunity", "dim": "coach_questioning_and_dialogue", "text": "The coach acknowledges the teacher's point but then supplies the whole step themselves instead of building on the teacher's observation.", "better": "Ask the teacher a follow-up such as 'You said students change the pronoun or object on their own; what could you ask them to do next so they build a whole sentence of their own?' and let the teacher shape the pair task."}, {"line": 10, "kind": "missed_opportunity", "dim": "practice_or_modelling", "text": "The teacher's commitment is hedged ('nitajitahidi') and the coach accepts a one-line 'when' without having the teacher say how they will give the instruction.", "better": "Ask the teacher to say aloud the exact instruction they will give the pairs ('what will you tell them?'), give quick feedback, and have them try once more before closing."}], "scores": {"purpose_and_relationship_opening": 2, "teacher_self_reflection": 2, "coach_questioning_and_dialogue": 2, "evidence_from_the_lesson": 2, "focus_on_one_growth_area": 2, "concrete_action_step": 2, "practice_or_modelling": 0, "commitment_and_follow_up": 2, "tone_and_psychological_safety": 2}, "overall": 57, "lang": "sw", "rtl": false}, {"id": "df3c6cb5241", "tab": "Tanzania: a typical debrief", "title": "A typical debrief", "why": "Clean speaker turns, 4 min 27 s, overall 46 (median for the group is 45), and it follows the guide line by line, as 26 of 58 do: support purpose and specific praise, one closed question ('walijibu kwa kina?'), a long teacher account that is not probed, the coach's ready-made pair-discussion step, teacher assent, 'when exactly?', and 'tukutane kesho'. Most debriefs follow the same sequence in under two minutes (median 97.5 s); this one is longer only because the teacher's answer is long.", "audio": "full/df3c6cb5241.mp3", "duration": 267.9, "programme_label": "Tanzania", "coach": "TZ Coach 41", "lines": [{"t": 2.9, "who": "coach", "text": "Mwalimu, nakushukuru kwa kukaribisha darasani. Asante kwa kunikaribisha. Lengo langu la kuja darasani ni tusaidiane kwa ajili ya hawa watoto. Nilipenda Mwalimu kunirejea kwa kazi ya kundi la 7, walipowasilisha sentensi: \"Bahari yetu ni shwari\" kabla ya kuendelea na shughuli mpya. Hali hiyo nilipenda sana. Sasa, ningependa nikuulize swali moja.", "en": "Teacher, thank you for welcoming me into the classroom. Thank you for having me. My purpose in coming to the classroom is for us to support each other for the sake of these children. Teacher, I liked how you went back to group 7's work, when they presented the sentence \"Our sea is calm\", before moving on to the new activity. I liked that a lot. Now, I would like to ask you one question."}, {"t": 31.0, "who": "teacher", "text": "Ndiyo, Mwalimu.", "en": "Yes, Teacher."}, {"t": 34.2, "who": "coach", "text": "Mwalimu, ulipouliza wanafunzi, walijibu kwa akina? Naomba nirudie swali: wanafunzi walipoulizwa, walitoa majibu kwa akina?", "en": "Teacher, when you asked the students, did they answer in depth? Let me repeat the question: when the students were asked, did they give answers in depth?"}, {"t": 80.0, "who": "teacher", "text": "Ndiyo, Mwalimu. Walijitahidi na walitoa majibu kwa kina. Mfano, Mwalimu, nilipoanza kuwauliza maswali ya kwamba kila kundi wameshaweza kusoma neno ambalo nimewagawia katika kila karatasi, kila kundi waliwasilisha kwa kusoma neno lao kwa usahihi.", "en": "Yes, Teacher. They did their best and gave answers in depth. For example, Teacher, when I started asking them whether each group had been able to read the word I gave them on each paper, each group presented by reading their word correctly."}, {"t": 114.0, "who": "teacher", "text": "Na baada ya hapo, Mwalimu, niliwaweka kwa muda mfupi katika makundi wajadiliane kwa lengo la kutunga sentensi 2 kwa kila neno lililokuwa katika karatasi kwenye kila kundi.", "en": "And after that, Teacher, I put them in groups for a short time to discuss, with the aim of composing 2 sentences for each word that was on the paper in each group."}, {"t": 143.0, "who": "teacher", "text": "Na baada ya muda huo, Mwalimu, niliwataka kila kundi kuwasilisha sentensi ambazo walikuwa wamezitunga kwa kuzisoma kwa sauti. Nilifanya mpango wa kusimamisha mwanafunzi mmoja katika kila kundi ambaye aliwasilisha kusoma sentensi ambazo walizitunga kwenye makundi yao, ambapo darasa zima walisikiliza sentensi za kila kundi.", "en": "And after that time, Teacher, I asked each group to present the sentences they had composed by reading them aloud. I arranged for one student in each group to stand and present by reading the sentences they had composed in their groups, while the whole class listened to each group's sentences."}, {"t": 201.5, "who": "coach", "text": "Nashukuru Mwalimu kwa majibu yako mazuri, lakini nilikuwa napendekeza: vipi kesho ukijaribu njia hii? Kwa mfano, baada ya kuandika sentensi 2, omba wanafunzi wawili wajadiliane kwa dakika kwa nini sentensi ni tofauti, kisha waulize wawili wawasilishe hoja zao kwa darasani.", "en": "Thank you, Teacher, for your good answers, but I was suggesting: how about trying this approach tomorrow? For example, after writing 2 sentences, ask two students to discuss for a minute why the sentences are different, then ask two of them to present their points to the class."}, {"t": 228.2, "who": "teacher", "text": "Sawa, Mwalimu. Nitajaribu, na nitaifanya maana hata hiyo njia inaonekana kuwa nzuri kwa uelewa wa wanafunzi zaidi.", "en": "Okay, Teacher. I will try it, and I will do it, because that approach also looks good for the students' understanding."}, {"t": 240.6, "who": "coach", "text": "Kesho wakati gani sana utautumia njia hii?", "en": "Tomorrow, at what time exactly will you use this approach?"}, {"t": 251.8, "who": "teacher", "text": "Kipindi kijacho, Mwalimu, nitaingia na kujaribu njia hiyo.", "en": "In the next lesson, Teacher, I will go in and try that approach."}, {"t": 258.4, "who": "coach", "text": "Asante sana. Tukutane kesho ili tuweze kushirikiana kwa pamoja kuona hii njia itakayofaa. Asante kwa ushirikiano wako.", "en": "Thank you very much. Let's meet tomorrow so we can work together to see which approach will work. Thank you for your cooperation."}], "phases": [{"name": "Thanks, purpose and specific praise", "t": 2.9}, {"name": "Coach question and teacher account of the lesson", "t": 34.2}, {"name": "Suggested step", "t": 201.5}, {"name": "Teacher accepts", "t": 228.2}, {"name": "When and follow-up", "t": 240.6}], "notes": [{"line": 0, "kind": "strength", "dim": "purpose_and_relationship_opening", "text": "Support framing plus praise that names a concrete moment, which is the kind of opening that makes a teacher feel observed fairly.", "better": null}, {"line": 2, "kind": "missed_opportunity", "dim": "coach_questioning_and_dialogue", "text": "A yes/no question that suggests the desired answer invites 'yes' and gives the teacher no reason to look closely at pupils' responses.", "better": "Ask an open question anchored in a moment, such as 'When group 7 read their sentence, what did you notice about how the other pupils responded?', then wait for the answer."}, {"line": 6, "kind": "missed_opportunity", "dim": "practice_or_modelling", "text": "A clear, observable step is offered, but the coach states it outright and the teacher only assents; the teacher never tries saying what they would ask.", "better": "After the suggestion, ask the teacher to say aloud the exact question they would put to pupils after they write their two sentences, and give a quick tip on the wording."}, {"line": 8, "kind": "strength", "dim": "commitment_and_follow_up", "text": "Coach asks for a when and proposes meeting the next day to review, giving the teacher a reason to follow through.", "better": null}], "scores": {"purpose_and_relationship_opening": 2, "teacher_self_reflection": 1, "coach_questioning_and_dialogue": 1, "evidence_from_the_lesson": 1, "focus_on_one_growth_area": 2, "concrete_action_step": 2, "practice_or_modelling": 0, "commitment_and_follow_up": 2, "tone_and_psychological_safety": 2}, "overall": 46, "lang": "sw", "rtl": false}], "impact": {"forest": [{"label": "Coached skill (main result)", "est": 0.0586, "ci": [0.0215, 0.0958], "kind": "main", "n": "907 debriefs, 817 teachers"}, {"label": "All other skills", "est": 0.0138, "ci": [-0.0035, 0.0298], "kind": "main", "n": "907 debriefs, 817 teachers"}, {"label": "Coached minus other skills", "est": 0.0447, "ci": [0.0085, 0.0806], "kind": "main", "n": "907 debriefs, 817 teachers"}, {"label": "Check: 14-day window", "est": 0.0638, "ci": [0.0276, 0.098], "kind": "main", "n": "846 debriefs, 760 teachers"}, {"label": "Check: one debrief per teacher", "est": 0.0615, "ci": [0.0232, 0.0995], "kind": "main", "n": "816 debriefs, 816 teachers"}, {"label": "Check: compare with not-yet-coached teachers", "est": 0.0486, "ci": [0.0091, 0.089], "kind": "main", "n": "849 debriefs, 764 teachers"}, {"label": "Placebo: two lessons BEFORE the debrief", "est": -0.0119, "ci": [-0.0463, 0.0198], "kind": "placebo", "n": "833 debriefs, 741 teachers"}, {"label": "Coached on questioning (C1)", "est": -0.0142, "ci": [-0.0401, 0.0131], "kind": "main", "n": "647 debriefs (exploratory)"}, {"label": "Coached on differentiation (B6)", "est": 0.2286, "ci": [0.0688, 0.3807], "kind": "main", "n": "109 debriefs (exploratory)"}, {"label": "Coached on group work (C9)", "est": 0.3416, "ci": [0.067, 0.5916], "kind": "main", "n": "65 debriefs (exploratory)"}, {"label": "Coached on feedback (C3)", "est": 0.0579, "ci": [-0.1143, 0.2262], "kind": "main", "n": "39 debriefs (exploratory)"}], "forest_title": "Change on the coached skill in the next lesson, compared with similar teachers (1 to 4 scale)", "forest_sub": "Each dot is the estimate, each line its 95% interval. The gold row is a placebo check that should sit on zero, and does. The last four rows split the main result by topic and are exploratory.", "verdict_html": "<div class=\"verdict\"><b class=\"v\">Yes, a little, and mostly where the step was concrete.</b>Teachers' next lessons moved toward the coached skill by +0.06 of a level (95% interval +0.02 to +0.10), more than similar teachers who were not debriefed, and only on that skill. The gain came from debriefs about differentiation and group work. Debriefs about questioning, the most common topic, showed none. When we read the lessons blind, teachers did do more of the agreed step afterwards, but also more of steps no one had asked for, so that test alone cannot confirm the effect.</div>", "detail_html": "<h3>Test A: lesson scores</h3><p><b>What we compared.</b> 907 ICT debriefs (817 teachers) where the teacher recorded a lesson in the four weeks before the debrief and another in the four weeks after. Each was matched with teachers who were not debriefed but recorded lessons on the same days, give or take three days (1,271 teachers in all). We looked at the one skill the debrief was about, the \"coached skill\", scored 1 to 4.</p>\n\n<table class=\"res\">\n<tr><th>On the coached skill, next lesson</th><th>Moved up a level</th><th>Stayed the same</th><th>Moved down</th></tr>\n<tr><td>Debriefed teachers (907)</td><td>12%</td><td>80%</td><td>8%</td></tr>\n<tr><td>Similar teachers, no debrief</td><td>10%</td><td>79%</td><td>10%</td></tr>\n</table>\n\n<p><b>How sure are we.</b> The difference is +0.06 of a level (95% interval +0.02 to +0.10). It held up every way we tested it:</p>\n<ul>\n<li>Other skills barely moved (+0.01, interval −0.004 to +0.03), so this is not teachers simply having a better day.</li>\n<li>The same comparison on two lessons that were both <i>before</i> the debrief showed nothing (−0.01, interval −0.05 to +0.02). So the coached teachers were not already on the way up.</li>\n<li>Comparing only with teachers who were coached later (the same kind of teacher coaches pick) gave +0.05. A 14-day window gave +0.06. One debrief per teacher gave +0.06. Leaving out lessons recorded by coaches' own accounts gave +0.06.</li>\n</ul>\n\n<p><b>Where the change happens (exploratory).</b> Splitting by what the debrief was about:</p>\n<ul>\n<li><b>Questioning (C1)</b>, the topic of 71% of debriefs: no change we could detect (−0.01, interval −0.04 to +0.01). With 647 debriefs we would have seen a change as small as 0.04.</li>\n<li><b>Differentiation (B6)</b>, 109 debriefs: +0.23 (interval +0.07 to +0.38).</li>\n<li><b>Group work (C9)</b>, 65 debriefs: +0.34 (interval +0.07 to +0.59).</li>\n<li><b>Feedback (C3)</b>, 39 debriefs: too few to tell (+0.06, interval −0.11 to +0.23).</li>\n</ul>\n<p>This split was not in our written plan, so treat it as a strong lead, not a finding. It fits a simple idea: \"put the children in pairs for this task\" is a step a teacher can do tomorrow, and a scorer can see. \"Ask better questions\" is not, unless the debrief turns it into one exact question to ask.</p>\n\n<p><b>The catch.</b> After a debrief, 73% of teachers recorded another lesson within four weeks, against 83% of teachers generally. Some teachers stop recording after a debrief, and we cannot see their next lesson. For the result to disappear, those extra teachers would have had to slip by almost half a level on the coached skill. That is far more than anyone else slipped, but we cannot rule it out from this data.</p>\n<h3>Test B: did the teacher do the exact thing they agreed?</h3>\n<p>Scores can hide what really happened, so we also read the lessons themselves. For 160 ICT teachers, an AI reader took the step agreed in the debrief (a real one: \"after explaining, put children in groups of four for 8 to 10 minutes of role-play, visit the quiet groups, then have each child write their own dialogue\") and looked for it in the teacher's lesson before the debrief and the lesson after. It also looked for a second, unrelated step, taken from a different teacher's debrief. The reader did not know which lesson came first, or which step was the real one.</p>\n\n<table class=\"res\">\n<tr><th>How much of the step was in the lesson (0 to 3)</th><th>Before</th><th>After</th><th>Change</th></tr>\n<tr><td><b>The step agreed in this debrief</b></td><td>0.41</td><td>0.66</td><td>+0.25 (interval +0.12 to +0.38)</td></tr>\n<tr><td>An unrelated step from someone else's debrief</td><td>0.41</td><td>0.58</td><td>+0.17 (interval +0.05 to +0.29)</td></tr>\n<tr><td><b>The difference</b></td><td></td><td></td><td>+0.08 (interval −0.09 to +0.25)</td></tr>\n</table>\n\n<p>Teachers did more of the agreed step after the debrief. The share of lessons where it was clearly there doubled, from 12% to 23%. But they also did more of steps nobody had asked them for. So we cannot say, from this test alone, that the debrief caused the specific change. The difference that is left (+0.08) is the same direction as Test A, and its interval easily includes Test A's result. Test B is simply too small (160 teachers) to confirm an effect that size.</p>\n\n<p><b>Can we trust the readers?</b> A quarter of the lesson pairs were read a second time by a separate reader. They agreed closely: 89% of ratings were identical, and the agreement score (ICC) was 0.93, where 0.8 or more counts as excellent.</p>\n\n<p><b>Two things we could not link to uptake (exploratory).</b> How well the debrief scored on our rubric did not predict whether the teacher took up the step (correlations near zero). Nor could we see a difference between steps the teacher said \"yes\" to and steps only the coach named. One reason may be that so few debriefs included practice (3%) that we could not see what practice does.</p>\n", "uptake": [{"label": "Agreed behaviour (target)", "est": 0.25, "ci": [0.1187, 0.3812], "kind": "main", "n": "160 teachers"}, {"label": "Unrelated behaviour (placebo)", "est": 0.1688, "ci": [0.05, 0.2875], "kind": "placebo", "n": "160 teachers"}, {"label": "Target minus placebo", "est": 0.0813, "ci": [-0.0875, 0.25], "kind": "main", "n": "160 teachers"}], "uptake_title": "Test B: how much of the agreed step appeared in the lesson after the debrief (0 to 3 scale)", "uptake_sub": "Read blind: the reader did not know which lesson came first. The gold row is an unrelated step from another teacher's debrief."}, "recommendations": [{"for": "Coaches", "do": "Before you leave, rehearse the step", "because": "Say: \"Show me how you will say it tomorrow.\" Let the teacher try it, adjust it once, and try again. This is the best-evidenced part of a debrief, and it happened in 3% of ICT debriefs."}, {"for": "Coaches", "do": "Ask first, then wait", "because": "Open with \"Which moment would you change, and why?\" and let the teacher finish. Today the teacher speaks first in 31% of ICT debriefs and the coach says 70% of the words."}, {"for": "Trainers", "do": "Turn 'better questions' into one exact question", "because": "Questioning is the topic of 71% of debriefs and showed no change in the next lesson. Concrete steps (pairs, groups, levelled tasks) did. Train coaches to agree the exact question, and the moment to ask it."}, {"for": "Trainers", "do": "Learn from each other's recordings", "because": "Among ICT coaches with three or more debriefs, average scores ran from 27 to 56 out of 100. The clips on this page come from our own coaches and can be a workshop set."}, {"for": "Product (the AI debrief guide)", "do": "End the guide with a rehearsal line and a commitment line", "because": "Coaches fully followed the guide in 3% of ICT debriefs and partly in 38%. Give them two short lines they will use: \"Say it to me now as you will say it to the class\", and \"When will you try it?\""}, {"for": "Product", "do": "Check the agreed step in the next lesson", "because": "Rumi already records the teacher's next lesson. Saving the agreed step as text, then looking for it in that lesson, is the test we ran here. Showing coaches the result would close the loop."}], "methods_html": "<p>We did this in four steps. Every number on this page comes from a file a script wrote, and every script is kept with the study so anyone can run it again.</p>\n\n<h3>1. What good looks like</h3>\n<p>An AI researcher read the published evidence on coaching conversations: the World Bank's Coach programme guidance, the large review of 60 coaching studies by Kraft, Blazar and Hogan, trials from South Africa, Peru and Brazil, and the best-known practice guides. From it we built a rubric of nine parts, each scored 0 to 3. Every source was checked: 21 of its 27 links opened directly, and the other 6 are journal and publisher pages that block automated visits, all for well-known published works.</p>\n\n<h3>2. Listening to the debriefs</h3>\n<ul>\n<li><b>Which debriefs.</b> Every ICT and Punjab debrief recorded from 26 September to 2 October that was long enough to judge (over about a minute of talk), and 60 Tanzania debriefs spread across coaches. We wanted more weeks, but WhatsApp keeps a voice note for only about a week, so older debriefs have no audio left to play.</li>\n<li><b>Transcripts.</b> The audio was transcribed again with word-level timings, so each clip starts and ends on a whole sentence and we know who is speaking. Rumi's own stored transcripts keep only the start of each turn.</li>\n<li><b>Readers.</b> A swarm of AI readers (Claude Sonnet) scored every debrief against the rubric. They counted who spoke how many words and how many questions were asked, marked the arc of the conversation, and picked the moments worth hearing. Each reader had no web access, no shell, and could only read and write files in the study folder.</li>\n<li><b>Second reads.</b> 36 debriefs were scored twice by separate readers. On the nine parts, weighted agreement (kappa) ran from 0.74 to 0.88, and the overall score agreed at ICC 0.91. One yes/no flag, whether the coach modelled the step, agreed poorly (kappa 0.25), so this page does not use it.</li>\n<li><b>Managers.</b> AI managers (Claude Opus) checked the readers against the transcripts, found the patterns, and chose the clips.</li>\n<li><b>Quote gate.</b> A clip appears only if its quote is found word for word in the transcript, inside the clip's own time window. Before the managers' checks, 99% (1070 of 1086) of the readers' quotes passed this gate. Clips that fail it are dropped, not fixed.</li>\n<li><b>One-way recordings.</b> Some recordings have no teacher voice at all: the coach gives a talk, or reads the AI guide aloud. We count a recording as one-way when the second voice says under 5% of the words AND the reader, judging by content, found the coach saying 95% or more. They are reported on their own and left out of the conversation scores, because a recording with no teacher in it cannot show what the conversation was like.</li>\n<li><b>Names.</b> Names of people and schools are replaced with [name] and [school] in all text. Coaches are shown as \"ICT Coach 07\" and so on. Voices in the audio are as recorded.</li>\n</ul>\n\n<h3>3. Did teaching change? Two independent tests</h3>\n<p>We wrote the analysis plan down <b>before</b> computing any result, and fixed its fingerprint (sha256 2883aaf8…) on our issue tracker. Anything not in that plan is marked \"exploratory\" on this page.</p>\n<ul>\n<li><b>Test A, lesson scores.</b> Teachers record their own lessons and Rumi scores them on FICO. For each ICT debrief we took the teacher's last recorded lesson before it and first after it, and compared the change on the coached skill with the change in teachers who were not debriefed, recording on the same days. Using the lesson before the debrief, not the observed lesson, removes the \"it was chosen because it was low\" effect. A placebo test (the same comparison on two lessons that both came before the debrief) must show nothing, and did.</li>\n<li><b>Test B, the transcripts.</b> For 200 teachers (one debrief each), a reader wrote down the exact behaviour the coach and teacher agreed on. A different AI reader then read the teacher's lesson before and after the debrief, labelled only A and B in random order, and counted that behaviour, plus an unrelated \"placebo\" behaviour from another teacher's debrief. The reader never knew which lesson came first or which behaviour mattered. The answer key sat in a folder the readers were blocked from opening, and we checked that block works. A quarter of the lesson pairs were read twice, independently, to measure agreement. 165 of the 200 debriefs had a step concrete enough to look for, and 160 lesson pairs could be judged.</li>\n<li><b>Checking the checker.</b> Before trusting Test A on real data we ran it on made-up data with a known answer: it found a planted improvement of exactly the right size, and across 30 made-up worlds with no improvement it raised a false alarm in 1 of 30, the rate chance alone gives.</li>\n</ul>\n\n<h3>4. Limits</h3>\n<ul>\n<li>Lesson scores come from Rumi's AI scoring of recorded lessons, not from a person in the room.</li>\n<li>Teachers choose when to record. 73% of debriefed teachers recorded another lesson within 28 days, against 83% of teachers generally, so some teachers drop out of the measurement after a debrief. The main result would disappear only if those extra teachers had slipped by almost half a level on the coached skill.</li>\n<li>Test A and Test B cover ICT only. Punjab and Tanzania do not yet have enough lessons recorded before and after debriefs on one framework.</li>\n<li>The audio covers one week. We checked it against 129 older ICT debriefs (July to September) read from text: they match closely, a median score of 43 against 44 out of 100, and every part within 0.13 points.</li>\n<li>Nothing here is about children's learning. Everything is about what the teacher did in the next recorded lesson.</li>\n</ul>\n", "references": [{"author": "Allen, J. P., Pianta, R. C., Gregory, A., Mikami, A. Y. and Lun, J.", "year": 2011, "title": "An Interaction-Based Approach to Enhancing Secondary School Instruction and Student Achievement", "url": "https://eric.ed.gov/?id=ED556046"}, {"author": "Bambrick-Santoyo, P.", "year": 2012, "title": "Leverage Leadership: A Practical Guide to Building Exceptional Schools", "url": "https://www.oreilly.com/library/view/leverage-leadership-a/9781118238929/"}, {"author": "Cilliers, J., Fleisch, B., Kotze, J., Mohohlwane, N., Taylor, S. and Thulare, T.", "year": 2021, "title": "Can Virtual Replace In-person Coaching? Experimental Evidence on Teacher Professional Development and Student Learning (RISE WP 20/050)", "url": "https://riseprogramme.org/sites/default/files/2021-01/RISE_WP-050_Cilliers_etal_2021_update_0.pdf"}, {"author": "Edmondson, A.", "year": 1999, "title": "Psychological Safety and Learning Behavior in Work Teams", "url": "https://eric.ed.gov/?id=EJ589456"}, {"author": "Gardezi, S., McNamara, G., Brown, M. and O'Hara, J.", "year": 2023, "title": "School inspections: a rhetoric of quality or reality?", "url": "https://www.frontiersin.org/journals/education/articles/10.3389/feduc.2023.1204642/full"}, {"author": "Gollwitzer, P. M. and Sheeran, P.", "year": 2006, "title": "Implementation intentions and goal achievement: A meta-analysis of effects and processes", "url": "https://www.socmot.uni-konstanz.de/publications/implementation-intentions-and-goal-achievement-meta-analysis-effects-and-processes"}, {"author": "Grossman, P., Compton, C., Igra, D., Ronfeldt, M., Shahan, E. and Williamson, P.", "year": 2009, "title": "Teaching Practice: A Cross-Professional Perspective", "url": "https://www.semanticscholar.org/paper/Teaching-Practice%3A-A-Cross-Professional-Grossman-Compton/6018abe8f22ac30ec7937edf6dea8989f3e9b105"}, {"author": "Hattie, J. and Timperley, H.", "year": 2007, "title": "The Power of Feedback", "url": "https://www.semanticscholar.org/paper/The-Power-of-Feedback-Hattie-Timperley/a341536770fc149df10408865bfb58f76246cfdc"}, {"author": "Heineke, S. F.", "year": 2013, "title": "Coaching Discourse: Supporting Teachers' Professional Learning", "url": "https://eric.ed.gov/?id=EJ1013985"}, {"author": "Kluger, A. N. and DeNisi, A.", "year": 1996, "title": "The effects of feedback interventions on performance: A historical review, a meta-analysis, and a preliminary feedback intervention theory", "url": "https://scholars.huji.ac.il/avrahamkluger/publications/effects-feedback-interventions-performance-historical-review-meta"}, {"author": "Knight, J.", "year": 2018, "title": "The Impact Cycle: What Instructional Coaches Should Do to Foster Powerful Improvements in Teaching", "url": "https://books.google.com/books/about/The_Impact_Cycle.html?id=79QuDwAAQBAJ"}, {"author": "Koc, F. S. and Savas, P.", "year": 2024, "title": "Supervision Models and Supervisory Feedback in English Language Teacher Education: A Meta-Synthesis Study Adopting a Discourse Analytic Perspective", "url": "https://tesl-ej.org/wordpress/issues/volume27/ej108/ej108a1/"}, {"author": "Kraft, M. A. and Gilmour, A. F.", "year": 2016, "title": "Can Principals Promote Teacher Development as Evaluators? A Case Study of Principals' Views and Experiences", "url": "https://eric.ed.gov/?id=EJ1118321"}, {"author": "Kraft, M. A., Blazar, D. and Hogan, D.", "year": 2018, "title": "The Effect of Teacher Coaching on Instruction and Achievement: A Meta-Analysis of the Causal Evidence", "url": "https://journals.sagepub.com/doi/abs/10.3102/0034654318759268"}, {"author": "Lampert, M., Franke, M. L., Kazemi, E., Ghousseini, H., Turrou, A. C., Beasley, H., Cunard, A. and Crowe, K.", "year": 2013, "title": "Keeping it complex: Using rehearsals to support novice teacher learning of ambitious teaching", "url": "https://www.scirp.org/reference/referencespapers?referenceid=2455221"}, {"author": "Popova, A., Evans, D. K., Breeding, M. E. and Arancibia, V.", "year": 2019, "title": "Teacher Professional Development around the World: The Gap between Evidence and Practice (CGD Working Paper 517)", "url": "https://www.cgdev.org/publication/teacher-professional-development-around-world-gap-between-evidence-and-practice"}, {"author": "Sims, S., Fletcher-Wood, H., O'Mara-Eves, A., Cottingham, S., Stansfield, C., Goodrich, J., Van Herwegen, J. and Anders, J.", "year": 2022, "title": "Effective teacher professional development: new theory and a meta-analytic test (EdWorkingPaper 22-507)", "url": "https://files.eric.ed.gov/fulltext/ED616856.pdf"}, {"author": "Wilichowski, T. and Popova, A. (World Bank Coach)", "year": 2021, "title": "Facilitating Effective 1-1 Coaching Sessions (Coach series summary)", "url": "https://thedocs.worldbank.org/en/doc/5b7f39c1822ef0127c8596fe0fb1ced0-0200022022/related/20220615-Facilitating-Effective-1-1-Coaching-Sessions-FINAL.pdf"}]};
